DELIMITER //
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ajt_t_adjuntos_entradas_otro_proyecto`(

	IN `ipy` int,

	IN `fse` TEXT

)
select a.id_adjunto,a.id_proyecto,a.tipo,a.etapa,a.fase,a.adjunto,DATE_FORMAT(a.fecha_registro, '%Y-%m-%d %H:%i'),a.usuario_registro,a.observacion

from adjunto a

where (a.id_proyecto = ipy and a.tipo = 'ENTRADA_OTRO') and (a.etapa = '7.3.2_ELEMENTOS DE ENTRADA' and a.fase = fse)//
DELIMITER ;

DELIMITER //
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ajt_t_adjuntos_entradas_pr_proyecto`(

	IN `ipy` int,

	IN `fse` TEXT

)
select a.id_adjunto,a.id_proyecto,a.tipo,a.etapa,a.fase,a.adjunto,DATE_FORMAT(a.fecha_registro, '%Y-%m-%d %H:%i'),a.usuario_registro,a.observacion

from adjunto a

where (a.id_proyecto = ipy and a.tipo = 'ENTRADA') and (a.etapa = '7.3.2_ELEMENTOS DE ENTRADA' and a.fase = fse)//
DELIMITER ;

DELIMITER //
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ajt_t_adjuntos_memoria_proyecto`(

	IN `ipy` int,

	IN `etp` varchar(100),

	IN `fse` TEXT

)
select a.id_adjunto,a.id_proyecto,a.tipo,a.etapa,a.fase,a.adjunto,DATE_FORMAT(a.fecha_registro, '%Y-%m-%d %H:%i'),a.usuario_registro,a.observacion

from adjunto a

where (a.id_proyecto = ipy and a.tipo = 'MEMORIA') and (a.etapa = etp and a.fase = fse)//
DELIMITER ;

DELIMITER //
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ajt_t_adjuntos_pruebas_proyecto`(

	IN `ipy` int,

	IN `fse` TEXT

)
select a.id_adjunto,a.id_proyecto,a.tipo,a.etapa,a.fase,a.adjunto,DATE_FORMAT(a.fecha_registro, '%Y-%m-%d %H:%i'),a.usuario_registro,a.observacion,

	a.usuario_verificacion,a.verificacion,DATE_FORMAT(a.fecha_verificacion, '%Y-%m-%d %H:%i')

from adjunto a

where (a.id_proyecto = ipy and a.tipo = 'PRUEBAS') and (a.fase = fse)//
DELIMITER ;

DELIMITER //
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ara_c_area`()
SELECT a.id_area, a.fch_registro, a.usu_registro, a.area, a.signatura, a.estado

FROM area a//
DELIMITER ;

DELIMITER //
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ara_m_area`(

	IN `usu_registro` VARCHAR(50),

	IN `area` VARCHAR(50),

	IN `signatura` VARCHAR(50),

	IN `id_area` INT

)
