DELIMITER //
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_m_d_t_progreso_proyecto`(

	IN `ipy` int

)
SELECT pr.fch_entrada AS 'PROYECTO','TIEMPO_TRABAJO',(select max(d.fch_registro)FROM proyecto p inner join memoria_c c on p.id_proyecto = c.fk_proyecto	inner join memoria_d d on c.id_memoria_c = d.fk_memoria_c where p.id_proyecto = ipy) AS 'FECHA_ULT_AVANCE',

(SELECT TIMESTAMPDIFF(YEAR,pr.fch_entrada,(select max(d.fch_registro)FROM proyecto p inner join memoria_c c on p.id_proyecto = c.fk_proyecto	inner join memoria_d d on c.id_memoria_c = d.fk_memoria_c where p.id_proyecto = ipy)))  AS ANIOS,

(SELECT (TIMESTAMPDIFF(MONTH,pr.fch_entrada,(select max(d.fch_registro)FROM proyecto p inner join memoria_c c on p.id_proyecto = c.fk_proyecto	inner join memoria_d d on c.id_memoria_c = d.fk_memoria_c where p.id_proyecto = ipy))) - (TIMESTAMPDIFF(YEAR,pr.fch_entrada,(select max(d.fch_registro)FROM proyecto p inner join memoria_c c on p.id_proyecto = c.fk_proyecto	inner join memoria_d d on c.id_memoria_c = d.fk_memoria_c where p.id_proyecto = ipy)) * 12)) AS MESES,

(SELECT DATEDIFF((select max(d.fch_registro)FROM proyecto p inner join memoria_c c on p.id_proyecto = c.fk_proyecto	inner join memoria_d d on c.id_memoria_c = d.fk_memoria_c where p.id_proyecto = ipy),DATE_ADD(DATE_ADD(pr.fch_entrada, 

	INTERVAL TIMESTAMPDIFF(YEAR,pr.fch_entrada,(select max(d.fch_registro)FROM proyecto p inner join memoria_c c on p.id_proyecto = c.fk_proyecto	inner join memoria_d d on c.id_memoria_c = d.fk_memoria_c where p.id_proyecto = ipy)) YEAR), 

	INTERVAL (TIMESTAMPDIFF(MONTH,pr.fch_entrada,(select max(d.fch_registro)FROM proyecto p inner join memoria_c c on p.id_proyecto = c.fk_proyecto	inner join memoria_d d on c.id_memoria_c = d.fk_memoria_c where p.id_proyecto = ipy))) - (TIMESTAMPDIFF(YEAR,pr.fch_entrada,(select max(d.fch_registro)FROM proyecto p inner join memoria_c c on p.id_proyecto = c.fk_proyecto	inner join memoria_d d on c.id_memoria_c = d.fk_memoria_c where p.id_proyecto = ipy)) * 12) MONTH))) AS DIAS,

'TIEMPO_TRASCURRIDO',

(SELECT TIMESTAMPDIFF(YEAR,pr.fch_entrada,CURDATE()))  AS ANIOS,

(SELECT (TIMESTAMPDIFF(MONTH,pr.fch_entrada,CURDATE())) - (TIMESTAMPDIFF(YEAR,pr.fch_entrada,CURDATE()) * 12)) AS MESES,

(SELECT DATEDIFF(CURDATE(),DATE_ADD(DATE_ADD(pr.fch_entrada, INTERVAL TIMESTAMPDIFF(YEAR,pr.fch_entrada,CURDATE()) YEAR), INTERVAL (TIMESTAMPDIFF(MONTH,pr.fch_entrada,CURDATE())) - (TIMESTAMPDIFF(YEAR,pr.fch_entrada,CURDATE()) * 12) MONTH))) AS DIAS,

CURDATE() AS 'FECHA_ACTUAL',

(select count(d.id_memoria_d)FROM proyecto p inner join memoria_c c on p.id_proyecto = c.fk_proyecto	inner join memoria_d d on c.id_memoria_c = d.fk_memoria_c where p.id_proyecto = ipy and d.estado < 3) AS 'ACTIVIDADES PENDIENTES',

(select count(d.id_memoria_d)FROM proyecto p inner join memoria_c c on p.id_proyecto = c.fk_proyecto	inner join memoria_d d on c.id_memoria_c = d.fk_memoria_c where p.id_proyecto = ipy and d.estado = 3) AS 'ACTIVIDADES FINALIZADAS'

FROM proyecto pr

where pr.id_proyecto = ipy//
DELIMITER ;

DELIMITER //
