CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_p_pru_c_cabecera`(

	IN `id_proyecto` INT,

	IN `id_p_prueba` INT,

	IN `id_prueba_c` INT

)
SELECT p.id_p_prueba, p.fk_proyecto, p.fk_prueba, pr.prueba, pr.t_prueba, p.cuantitativo, 

p.`cuantitativo+`, p.`cuantitativo-`, p.criterio, p.fk_prueba_c,

pc.fch_registro, pc.usu_registro, pc.programacion, pc.consecutivo,

pc.producto, pc.fch_inicial, pc.hr_inicial, pc.f_tecnica, pc.version, pc.lote_c, pc.lote_p,

pc.n_molde, pc.n_molde, pc.n_molde, pc.observacion, pc.conclusion, pc.c_cavidad, pc.colada, pc.t_muestreo, pc.cerrar, p.version,

p.serial, p.f_verificacion, p.conclusion

FROM p_prueba p INNER JOIN prueba pr ON p.fk_prueba = pr.id_prueba

INNER JOIN prueba_c pc ON p.fk_prueba_c = pc.id_prueba_c

WHERE p.fk_proyecto = id_proyecto AND p.id_p_prueba = id_p_prueba AND p.fk_prueba_c = id_prueba_c

ORDER BY p.id_p_prueba DESC, pr.t_categoria ASC, pr.t_prueba DESC//
DELIMITER ;

