DELIMITER //
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_usa_t_usuario`(

	IN `usuario` VARCHAR(50),

	IN `password` VARCHAR(50)

)
SELECT 

u.id_usuario, 

u.fch_registro, 

u.usu_registro, 

u.nombre, 

u.apellido, 

u.identificacion, 

u.usuario, 

u.password,

u.`e-mail`, 

u.estado, 

u.fk_cargo, 

c.cargo,

u.pass_mail,

IF(u.password = YEAR(curdate()) or  CHAR_LENGTH(u.password) < 30, 'Si', 'No' ) as Cifrar 

FROM usuario u 

INNER JOIN cargo c ON u.fk_cargo = c.id_cargo

WHERE u.usuario = usuario AND u.password = password//
DELIMITER ;

