	(2, 4, 'CAMBIO CB-0134 PARA CONEXIÓN A NIPLE.', 'SE CAMBIA LA ENTRADA DEL COMPONENTE B&Aacute;SICO RETIRANDO LA ROSCA DE LA PIEZA YA QUE LAS PRUEBAS NO FUERON SATISFACTORIAS, AHORA LA CONEXION SE REALIZARA CON NIPLE DE 5.8X7.6 MM&nbsp;<a href="UserFiles/File/0003/ENTRADAS/6849_V2_20160219_1541.XLS" target="_blank">6849_V2</a> .\r\n', 'MARIA ISABEL COLMENARES/DIRECTOR CALIDAD', '2015-05-19'),
	(3, 4, 'FICHA TÉCNICA DE NIPLE DE 5.8X7.6 ', 'ESPECIFICACIONES DEL TUBO DE PVC FLEXIBLE PARA LA CONEXI&Oacute;N DEL ENSAMBLE&nbsp;<a href="UserFiles/File/0003/ENTRADAS/6403_TUBO_5_8X7_6_V0_20160224_1125.XLS" target="_blank">6403_TUBO_5_8X7_6_V0</a> &nbsp;.\r\n', 'MARIA ISABEL COLMENARES/DIRECTOR CALIDAD', '2015-05-19'),
