	(1, 'MOLDE TWIST OFF CONNECTOR 2014', '0183', 'M-134', '2014-01-20', '12 SEMANAS', 'INYECCION', '061', '<p>\r\nFABRICAR UN MOLDE DE 16 CAVIDADES PARA TO CONNECTOR 2014 MARIPOSA FRESENIUS USA CB-152 TENER EN CUENTA P-027&nbsp;<a href="UserFiles/File/0001/ENTRADAS/Herramental.pdf" target="_blank">ANEXO &nbsp;</a>&nbsp;\r\n</p>\r\n<p>\r\n<img src="UserFiles/Image/0001/ENTRADAS/CB_152_0_MARIPOSA_20160120_1511.JPG" alt=" " width="450" height="219" />&nbsp;\r\n</p>\r\n', 'EDUARDO MUÑOZ / DIRECTOR TÉCNICO', 1, 1, '0', 'NESTOR CASTILLO/JEFE PROYECTO', '2016-01-20 20:03:08'),
	(2, 'ELECTRODOS FMC USA COLAS 270 ', '0187', 'E-159', '2014-05-20', '2 SEMANAS', 'SELLADO', '950,951', '<p>\r\nHACER UN JUEGO DE ELECTRODOS SIMILAR AL E-073 PERO UNOS 10 MM MAS ANCHO EL SELLADO POR ENCIMA DE LOS TROQUELES&nbsp;<a href="UserFiles/File/0002/ENTRADAS/R-PM-003_SELLADO_950_951.pdf" target="_blank">P-PM-003 SELLADO 950 Y 951</a>\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<ul>\r\n	<li><a href="UserFiles/File/0002/ENTRADAS/E-073001_DFT_20160226_1111.PDF" target="_blank">E-073001_DFT</a> </li>\r\n	<li><a href="UserFiles/File/0002/ENTRADAS/E-073002_DFT_20160226_1111.PDF" target="_blank">E-073002_DFT</a> </li>\r\n</ul>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<a href="UserFiles/File/0002/ENTRADAS/R-PM-003_SELLADO_950_951.pdf" target="_blank"></a>\r\n', 'EDUARDO MUÑOZ / DIRECTOR TÉCNICO', 1, 3, '0', 'NESTOR CASTILLO/JEFE PROYECTO', '2016-02-18 19:54:52'),
	(3, 'ELECTRODOS FRESENIUS BOCAS 270-40D', '0188', 'E-160', '2014-06-16', '2 SEMANAS', 'SELLADO', '958', '<p>\r\nFABRICAR UN JUEGO DE ELECTRODOS FRESENIUS USA AN&Aacute;LOGO AL E-101&nbsp;<a href="UserFiles/File/0002/ENTRADAS/R-PM-003_SELLADO_958.pdf" target="_blank">R-PM-003 SELLADO 958</a>&nbsp;.\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<ul>\r\n	<li><a href="UserFiles/File/0002/ENTRADAS/E-101002_1_20160226_1112.PDF" target="_blank">E-101002_1</a> </li>\r\n	<li><a href="UserFiles/File/0002/ENTRADAS/E-101001_2_20160226_1112.PDF" target="_blank">E-101002_2&nbsp;</a> </li>\r\n</ul>\r\n<p>\r\n&nbsp;\r\n</p>\r\n', 'EDUARDO MUÑOZ / DIRECTOR TÉCNICO', 1, 3, '0', 'NESTOR CASTILLO/JEFE PROYECTO', '2016-02-18 20:15:05'),
	(4, 'MOLDE CONECTOR BOLSA VIAL', '0147', 'M-110', '2011-08-02', '14 SEMANAS', 'INYECCION', 'N/A', '<p>\r\nFABRICAR UN MOLDE DE 8 CAVIDADES PARA CONECTOR VIAL SEGUN EL MU-O37 QUE CUMPLA CON CB-122 FRANGIBLE CON LUER\r\n</p>\r\n<ul>\r\n	<li><a href="UserFiles/File/0003/ENTRADAS/R-PM-003_INY_147.pdf" target="_blank">R-PM-003</a> </li>\r\n	<li><a href="UserFiles/File/0003/ENTRADAS/MU-037_20160219_845.PDF" target="_blank">MU-037</a> </li>\r\n	<li><a href="UserFiles/File/0003/ENTRADAS/CB-122_3_20160224_104.PDF" target="_blank">CB-122_3</a> </li>\r\n</ul>\r\n<p>\r\n&nbsp;\r\n</p>\r\n', 'EDUARDO MUÑOZ / DIRECTOR TÉCNICO', 1, 4, '0', 'NESTOR CASTILLO/JEFE PROYECTO', '2016-02-18 21:35:48'),
	(5, 'MOLDE FRANGIBLE LUER LOOK', '0148', 'M-111', '2011-08-22', '12 SEMANAS', 'INYECCION', 'N/A', '<p>\r\nFABRICAR UN MOLDE PARA UNA PIEZA AN&Aacute;LOGA AL CB-122 PERO CON ROSCA PARA FUNCI&Oacute;N DE LUER LOOK\r\n</p>\r\n<ul>\r\n	<li><a href="UserFiles/File/0003/ENTRADAS/R-PM-003_INY_148.pdf" target="_blank">R-PM-003</a> </li>\r\n	<li><a href="UserFiles/File/0003/ENTRADAS/CB-122_3_20160224_102.PDF" target="_blank">CB-122_3</a> </li>\r\n</ul>\r\n<p>\r\n&nbsp;\r\n</p>\r\n', 'EDUARDO MUÑOZ / DIRECTOR TÉCNICO', 1, 4, '0', 'NESTOR CASTILLO/JEFE PROYECTO', '2016-02-18 21:38:52'),
	(6, 'MOLDE PROTECTOR CONECTOR VIAL', '0185', 'M-135', '2014-01-17', '8 SEMANAS', 'INYECCION', 'N/A', '<p>\r\nFABRICAR UN MOLDE  PROTECTOR PUNTA VIAL CB-123\r\n</p>\r\n<ul>\r\n	<li><a href="UserFiles/File/0003/ENTRADAS/R-PM-003_INY_185.pdf" target="_blank">R-PM-003</a> </li>\r\n	<li><a href="UserFiles/File/0003/ENTRADAS/CB-123_2_0_20160219_849.PDF" target="_blank">CB-123_2_0</a></li>\r\n</ul>\r\n<p>\r\n&nbsp;\r\n</p>\r\n', 'EDUARDO MUÑOZ / DIRECTOR TÉCNICO', 1, 4, '0', 'NESTOR CASTILLO/JEFE PROYECTO', '2016-02-18 21:40:44'),
