INSERT INTO `memoria_d` (`id_memoria_d`, `fk_memoria_c`, `memoria`, `correo_actividad`, `autoridad`, `respuesta`, `usu_respuesta`, `fch_respuesta`, `correo_respuesta`, `correo_autor`, `estado`, `usu_registro`, `fch_registro`) VALUES
	(1, 2, 'A RAIZ DE CORREOS RECIBIDOS DE JOSE CARLOS LÓPEZ, SE PLANTEA EL DESARROLLO DE UN SPIKE PORT PARA LAS BOLSAS DE SOLUCIÓN SALINA EN REMPLAZO DE LA PIEZA SUMINISTRADA POR TECHNOFLEX DE FRANCIA CPRREO DEL 23/06/2009 DIRIGIDO A JOSE-CARLOS.LOPEZ@FMC-AG.COM.', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-01-21'),
	(2, 3, 'SE PLANTEA EL USO DE LA MISMA FÓRMULA ACEPTADA POR FRESENIUS USA PARA LA BOLSA, YA QUE ESTÁ INCLUIDA EN EL DRUG MASTER FILE QUE PLASTITEC TIENE CON LA FDA.', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-01-20'),
	(3, 3, 'UN PUNTO IMPORTANTE AL QUE SE LLEGA DEBIDO A QUE FRESENIUS MEDICAL CARE UA NO VA A PEGAR CON CICLOHEXANONA EL PUERTO AL TUBO, ES QUE LA PIEZA NO DEBERÍA TENER LÍNEA DE UNIÓN DE MATERIAL O KNIT LINE PARA QUE PASE LA PRUEBA MOS (IMPERMEABILIDAD A MICROORGANISMOS) EN LAS CONDICIONES EXTREMAS EN QUE HACEN LA PRUEBA AL NO INTRODUCIR LA PUNTA DE LA MARIPOSA ADENTRO DEL TUBO. ', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-01-20'),
	(4, 3, 'ESTE APARTE VIENE DE UN CORREO DE LUIS FELIPE PARA MÍ EL 11/10/2013 EDUARDO, LUEGO DE COMPARTIR LA CONVERSACIÓN DEL DÍA DE HOY CON LOS SEÑORES DE FMC USA QUIENES ESTÁN INTERESADOS EN COMPRAR UNA CANTIDAD IMPORTANTE DE TWIST-OFF, DONDE NOS PLANTEARON PROBLEMAS EN EL PROCESO DE VALIDACIÓN DE LAS MUESTRAS QUE A LA FECHA HEMOS ENVIADO: 1.	ELLOS NO PONEN CICLOHEXANONA, SOLO DEPENDEN DEL CALOR DEL AUTOCLAVE PARA PEGARLA AL TUBO DE LA BOLSA PRUEBA DONDE RETAN LA IMPERMEABILIDAD A MICROORGANISMOS DE LA SIGUIENTE MANERA: A.	INTRODUJERON SOLAMENTE 3/16? DE PULGADA Y NO PASO LA PRUEBA YA QUE 17/20 BOLSAS RESULTARON CONTAMINADAS B. INTRODUJERON SOLAMENTE 1/8? DE PULGADA Y NO PASO LA PRUEBA YA QUE 5/20 BOLSAS RESULTARON CONTAMINADAS C. LA PRUEBA INTRODUCIENDO LA TOTALIDAD DE LA MARIPOSA NO HAN CONCLUIDO (EL LUNES) ', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-01-20'),
	(5, 3, 'PARA SOLVENTAR ESTE ASPECTO Y AL MEDITAR SOBRE EL ORIGEN DE LAS LÍNEAS DE UNIÓN DE MATERIAL, PIENSO QUE PODEMOS APROVECHAR LA EXPERIENCIA PREVIA DE MOVIMIENTO DE MACHOS DURANTE LA FASE DE INYECCIÓN DE MODO QUE RECUBRA EL MACHO DE ARRIBA ABAJO, ABAJO SIN DEJAR LÍNEAS, Y QUE LUEGO EL MACHO SUBA PARA DEJAR EL ESPESOR DE MEMBRANA DESEADO.', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-01-20'),
	(6, 4, 'DE LA CONCEPCIÓN DE LA INYECCIÓN EDUARDO MUÑOZ', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-01-20'),
	(7, 4, 'DE LA CONSTRUCIÓN DEL MOLDE NESTOR CASTILLO', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-01-20'),
	(8, 4, 'DEL ASPECTO COMERCIAL LUIS FELIPE OSORIO', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-01-20'),
	(9, 5, 'LA PUNTA DEBE TENER DIMENSIONES SIMILARES A LAS DE LA MARIPOSA DE TECHNOFLEX. NO DEBE EXISTIR KNIT LINE ', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-01-20'),
	(10, 6, 'MATERIAL: CUMPLIR CON LA NORMATIVIDAD USP PARA PLÁSTICO CLASE VI, (ESTE ASPECTO VIENE YA PROBADO DE LA FORMULACIÓN USADA PARA ELLOS MISMOS EN MANGA F16201, DE ESTA FÓRMULA SE CUENTA CON LOS ESTUDIOS REALIZADOS POR TOKIXON)', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-01-20'),
	(11, 7, 'TENER EN CUENTA LOS MECANISMOS DE MOVIMIENTO DE MACHO SIMULTÁNEO CON LA INYECCIÓN DERIVADOS DEL ACCESORIO DE CONEXIÓN A VENOCLISIS USADO EN LAS BOLSAS DE PVC VENDIDAS A FRESENIUS MEDICAL CARE COLOMBIA.', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-01-20'),
	(12, 8, 'EL MATERIAL SE SOMETERÁ A ESTERILIZACIÓN CON E-BEAM PARA GARANTIZAR LA ESTERILIDAD ENTRE MEMBRANA Y LA CÚPULA. SE DEBE VERIFICAR EL CUMPLIMIENTO DE PROPIEDADES FISICOQUÍMICAS LUEGO DE IRRADIACIÓN.', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-01-20'),
	(13, 9, 'NO SE PREVÉN RIESGOS DIFERENTES A LOS ASOCIADOS CON LAS MARIPOSAS DE PVC QUE FABRICAMOS. LA ÚNICA DIFERENCIA RADICA EN QUE LOS SPIKE PORTS SE VAN A ENSAMBLAR SIN CICLOHEXANONA, PERO ES FRESENIUS USA QUIEN VA A CORRER LAS PRUEBAS MOS AL RESPECTO. ESPECIAL CUIDADO SE DEBE TENER EN LA OPERACIÓN DE MOVIMIENTO DEL MECANISMO DE AJUSTE DE ESPESOR DE MEMBRANA, YA QUE SI EL MOVIMIENTO NO SE DA, LA MEMBRANA QUEDARÍA MUY GRUESA Y AUNQUE ESTO NO PLANTEA UN RIESGO PARA EL PACIENTE, SI IMPOSIBILITARA EL UNO DE LA BOLSA. ', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-01-20'),
	(14, 11, 'SE LE INFORMA AL DISEÑADOR DEL MOLDE DEL REQUISITO DE MOVIMIENTO DEL MACHO DURANTE LA INYECCIÓN YA QUE ESTE MOVIMIENTO NO LO TIENE NINGUNO DE LOS MOLDES ACTUALES DE INYECCIÓN DE MARIPOSAS DE PP. SE VERIFICA QUE EN LA FICHA TÉCNICA DE PRODUCTO, ESTE SE HACE CON F16201. ', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-01-20'),
	(15, 12, 'ASIGNACION DE ACTIVIDAD CORRECTA, SE HA ENVIADO CORREO A LA PERSONA ASIGNADA INFORMANDO LA ACTIVIDAD', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-01-20'),
	(16, 13, 'EL PRODUCTO VA A SER PARTE DE UNA BOLSA EN USA. EL USO QUE SE VA A DAR ES EL MISMO QUE TIENE LA PIEZA COMPRADA AL ACTUAL PROVEEDOR.', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-01-20'),
	(17, 17, 'LOS DATOS DIMENSIONALES DE CAVIDAD POR CAVIDAD DE LA VALIDACIÓN DEL MOLDE ESTÁN EN EL DEP. DE ASEGURAMIENTO DE CALIDAD.', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-01-20'),
	(18, 18, 'ASIGNACION DE ACTIVIDAD CORRECTA, SE HA ENVIADO CORREO A LA PERSONA ASIGNADA INFORMANDO LA ACTIVIDAD', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-01-20'),
	(19, 18, 'ADJUNTO R-GC-134 INFORME PROYECTO.', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-01-25'),
	(20, 20, 'DESARROLLAR BOLSA DE DRENAJE  DE 7 LITROS PARA REEMPLAZAR LA BOLSA DE 5 LITROS QUE ACTUALMENTE SUMINISTRA OTRO PROVEEDOR', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-18'),
	(21, 21, '1. DISEÑAR FORMULA\r\n2. DEFINIR CAMBIOS EN ELECTRODOS.', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-04'),
	(22, 26, 'DEBIDO A QUE LOS TROQUELES DE ESTAS BOLSAS DEBEN SOPORTAR HASTA 7 KG Y PARA LOGRAR MAS ESTABILIDAD DURANTE LA FABRICACIÓN INDUSTRIAL DE ESTAS  BOLSAS DE DRENAJE PARA FMCUSA , SOLICITAMOS MAQUINAR UN  REFUERZO EN LA ZONA DE LOS TROQUELES. ', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-04'),
	(23, 23, 'DE LA CONCEPCIÓN DE LA FORMULACIÓN EDUARDO MUÑOZ Y DIEGO OROZCO.', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-04'),
	(24, 23, 'DE LAS MODIFICACIONES EN LOS ELECTRODOS: NESTOR CASTILLO.', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-04'),
	(25, 23, 'DE LOS RESULTADOS DE LAS PRUEBAS: MARÍA ISABEL COLMENARES.', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-04'),
	(26, 23, 'DEL ASPECTO COMERCIAL: LUIS FELIPE OSORIO', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-04'),
	(27, 28, 'SE ADJUNTA PLAN DE GESTION DE RIESGOS.', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-04'),
	(28, 24, '\r\nCUMPLIR CON LAS  ESPECIFICACIONES, PRUEBAS FUNCIONALES DESCRITAS EN LA FICHA TECNICA Y  REALIZAR PRUEBA DE LLENADO POR GOTEO ( BOLSAS A ESTUFA 54 °C DURANTE 1 HORA).', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-05'),
	(29, 31, 'LOS CRITERIOS DE ACEPTACION ESTAN DESCRITOS EN LA FICHA TECNICA FT-DT-1454.', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-05'),
	(30, 29, 'ENVIAR PRUEBAS DE FORMULA 11727 A LABORATORIO TECMOL PARA CUMPLIMIENTO DE USP Y FARMACOPEAS EUROPEAS.', 0, '[4]', 'RESULTADOS DE TECMOL EN LOS TRES LOTES FABRICADOS DE LA FORMULA 11727.', '4', '2016-02-05 17:31:08', 0, 0, 3, '5', '2016-02-05'),
	(31, 29, 'REALIZAR PRUEBAS FUNCIONALES Y DIMENSIONALES A LA BOLSA SEGÚN ESPECIFICACIONES DE LA FICHA TECNICA', 1, '[16]', 'SE REALIZAN PRUEBAS FUNCIONALES Y DIMENSIONALES A LOS TRES LOTES Y ESTAS CUMPLEN. \r\nLOS DATOS SE ENCUENTRAN EN LA PROGRAMACIÓN DE PRUEBAS.', '16', '2016-02-05 17:59:14', 0, 0, 3, '4', '2016-02-05'),
	(32, 37, 'REALIZAR INFORME DE VALIDACIÓN DE LOS TRES LOTES ENVIADOS A USA.', 0, '[16]', 'SE REALIZA INFORME DE VALIDACIÓN DE PROCESO DE BOLSAS DE DRENAJE USA.\r\nVER ADJUNTO.', '16', '2016-02-05 18:31:55', 0, 0, 3, '4', '2016-02-05'),
	(33, 25, 'CUMPLIR CON USP Y FARMACOPEAS EUROPEAS.', 0, '', NULL, NULL, NULL, 0, 0, 3, '4', '2016-02-18'),
	(34, 40, 'DISEÑO DEL CONECTOR FRANGIBLE Y DEL CONECTOR VIAL EN SI MISMO A PARTIR DE MUESTRAS DEL MERCADO.\r\n\r\nPOSTERIORMENTE SE DEBERÁ ACOMETER LA CONSTRUCCIÓN DE LOS MOLDES CORRESPONDIENTES Y TERMINAR TODOS LOS PASOS DE DISEÑO ESTABLECIDOS EN LA NORMA ISO 13485\r\n\r\n\r\n', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-24'),
	(35, 41, 'PARA EL FRANGIBLE EN SI MISMO SE TOMA COMO PUNTO DE PARTIDA UN CONECTOR DE ESTE TIPO USADO POR FRESENIUS MEDICAL CARE COLOMBIA PARA LAS BOLSAS FREKAFLEX EUROPA. ESTE DISEÑO AL SER USADO EN EUROPA NOS AHORRA TIEMPO DE DESARROLLO LOCAL. LUEGO DE FABRICADO EL MOLDE, SERÁ MUY IMPORTANTE LA VALIDACIÓN TANTO DEL ÉSTE COMO LA DEL PRODUCTO OBTENIDO, TENIENDO EN CUENTA ANÁLISIS DE RIESGOS TALES COMO EL DESPRENDIMIENTO DE PARTÍCULAS EN LA ZONA DE RUPTURA COMO EL DEL EVENTUAL DESENSAMBLE INDESEADO DE LOS COMPONENTES DEL CONJUNTO.', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-18'),
	(36, 41, 'POR OTRA PARTE, EN EL CONECTOR VIAL SE DEBERÁ VALIDAR ADEMÁS DEL MOLDE EN SI MISMO, QUE LA UNIÓN CON LOS VIALES SEA PERFECTAMENTE HERMÉTICA, QUE NO SE SUELTE EL FRASCO CON FACILIDAD Y QUE SEA MUY FÁCIL LA PERFORACIÓN DEL TAPÓN DE CAUCHO POR PARTE DEL PUNZÓN INTEGRADO EN EL CONECTOR VIAL.', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-18'),
	(37, 41, 'SE DEBERÁ TAMBIÉN VALIDAR QUE LUEGO DE INSTALADO EL CONJUNTO EN LA TUBERÍA DE LA BOLSA, NO HAYA FUGAS O GOTEOS ENTRE EL TUBO Y EL FRANGIBLE.', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-18'),
	(38, 42, 'DESARROLLO GENERAL : EDUARDO MUÑOZ', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-18'),
	(39, 42, 'DISEÑO DE LOS MOLDES: GUILLERMO CANO', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-18'),
	(40, 42, 'FABRICACIÓN DE LOS MOLDES: NÉSTOR CASTILLO', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-18'),
	(41, 42, 'PRUEBAS DE LOS MOLDES: LUIS EDUARDO RODRÍGUEZ', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-18'),
	(42, 42, 'EVALUACIÓN DE CALIDAD: MARÍA ISABEL COLMENARES', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-18'),
	(43, 42, 'VALIDACIÓN DE LOS MOLDES: GRUPO DE VALIDACIÓN', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-18'),
	(44, 42, 'EVALUACIÓN DE RIESGOS: GRUPO DE EVALUACIÓN DE RIESGOS', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-18'),
	(45, 43, 'EL CONJUNTO DEBERÁ SER ENSAMBLABLE FÁCILMENTE, Y PERMANECER ENSAMBLADO AÚN DESPUÉS DE PASAR POR AUTOCLAVE, ADEMÁS DEBERÁ EVITAR CUALQUIER FUGA BIEN SEA ENTRE EL TUBO DE LA BOLSA Y EL CUERPO DEL FRANGIBLE, ASÍ COMO EN LA UNIÓN AL FRASCO VIAL.\r\n\r\nES TAMBIÉN MUY IMPORTANTE MINIMIZAR LA POSIBILIDAD DE QUE EL CONJUNTO SUELTE PARTÍCULAS, BIEN SE COMO SUBPRODUCTO DE LA SOLDADURA DE LAS DOS PARTES, O DE LA RUPTURA DEL FRANGIBLE EN SI MISMA.\r\n\r\nPOR SUPUESTO, AL SER USADO DIRECTAMENTE EN CONTACTO CON UNA SOLUCIÓN INTRAVENOSA NO DEBERÍA EXISTIR LA POSIBILIDAD DE TENER MATERIALES ADICIONALES TALES COMO RESIDUOS DE PEGANTE ETC.\r\n\r\nTAMBIÉN SE DEBE INCLUIR EN EL PRODUCTO UN PROTECTOR DEL PUNZÓN DEL CONECTOR VIAL HECHO EN POLIPROPILENO. ESTE ELEMENTO DEBERÁ SER VENTILADO PARA PERMITIR EL PASO DEL OXIDO DE ETILENO, Y NO DEBERÁ SALIRSE CON FACILIDAD DEL PUNZÓN DEL CONECTOR VIAL\r\n', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-24'),
	(46, 44, 'PARA E PRODUCTO EN SI MISMO NO EXISTE UNA NORMA ESPECÍFICA, PERO LA IDEA ES USAR MATERIAS PRIMAS, EN ESTE CASO POLICARBONATO DEL MISMO TIPO DE LOS USADOS EN NUESTROS SITIOS DE INYECCIÓN, Y QUE TAMBIÉN ESTÁN EN CONTACTO DIRECTO CON SOLUCIONES INTRAVENOSAS. SE ANEXA LITERATURA DEL FABRICANTE DE LA RESINA DE POLICARBONATO EN LA QUE SE EVIDENCIA QUE ESTA ES APTA PARA USO MEDICO.', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-24'),
	(47, 45, 'EL DISEÑO DE LAS PIEZAS VIENE DE MUESTRAS USADAS EN EL MERCADO\r\nEL PRODUCTO ES USADO AMPLIAMENTE POR FRESENIUS MEDICAL CARE EN EUROPA. SE PUEDE USAR CUALQUIERA DE LOS DOS POLICARBONATOS QUE HAN SIDO UTILIZADOS PREVIAMENTE EN ARTICULOS COMO LOS SITIOS DE INYECCION\r\n', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-24'),
	(48, 46, 'EL MATERIAL ENSAMBLADO SERÁ ESTERILIZADO CON OXIDO DE ETILENO, Y ASÍ SERÁ DESPACHADO', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-18'),
	(49, 47, 'LUEGO DE REVISAR LOS RIESGOS ASOCIADOS,, SE LLEGA A LA CONCLUSIÓN DE QUE EL ENSAMBLE ENTRE LAS DOS PIEZAS SE DEBE HACER MECÁNICO, USANDO UN CONECTOR HEMBRA LUERLOCK EN EL FRANGIBLE Y UN LUER LOCK MACHO EN EL CONECTOR VIAL.\r\n\r\nSE LLEGA A ESTA CONCLUSIÓN LUEGO DE HACER VARIAS PRUEBAS:\r\n1.	SOLDADURA CON CICLOHEXANONA. SE CONCLUYE QUE AUNQUE EL ENSAMBLE ES RÁPIDO, Y ESTE SOLVENTE LO HEMOS USADO POR MUCHOS AÑOS UNIENDO PIEZAS DE PVC FLEXIBLE, NO ES ADECUADO YA QUE EL POLICARBONATO NO LO RESISTE QUÍMICAMENTE, Y SE CRAQUELA, RAZONES POR LA CUAL SE DESCARTA.\r\n2.	SOLDADURA CON PEGANTES INSTANTÁNEOS: LA SOLDADURA ES BUENA PERO NO SE USA DADO EL RIESGO DE QUE QUEDE PEGANTE QUE LUEGO SE VAYA CON LA SOLUCIÓN INTRAVENOSA. AUNQUE EXISTEN OTRO TIPO DE PEGAMENTOS DE CURADO ULTRAVIOLETA PARA USO MÉDICO, EL COLOR DE LAS PIEZAS AZUL OSCURO, DIFICULTARÍA EL PASO DE LA RADIACIÓN UV\r\n3.	SOLDADURA ROTACIONAL: LUEGO DE HACER PRUEBAS VARIAS, SE DESECHA ESTE TIPO DE SOLDADURA, QUE AUNQUE MUY BUENO EN SI MISMA, PRESENTA EL RIESGO DE LA GENERACIÓN DE PARTÍCULAS PROVENIENTES DE LA FRICCIÓN, PARTÍCULAS QUE PODRÍAN SER ARRASTRADAS POR LA SOLUCIÓN.\r\n4.	ENSAMBLE MECÁNICO A FONDO. AUNQUE EL RESULTADO INICIAL ES SATISFACTORIO, LUEGO DE PASAR POR AUTOCLAVE SE VE QUE EL CONJUNTO SE DESENSAMBLE MUY FÁCILMENTE, RAZÓN POR LA CUAL SE DESECHA\r\n5.	LA CONCLUSIÓN FINAL SERÁ LA DE INCORPORAR UN ANILLO DE ENROSQUE LUER LOCK, DE MODO QUE EL CONJUNTO NO TENGA REBABAS, PERO QUE AL MISMO TIEMPO NO DE DESENSAMBLE PREMATURAMENTE.\r\n6.	OTRA CONCLUSIÓN ES QUE EL TUBO SOLDADO A LA BOLSA DEBE SER DE 6 X 8 Y NO DE 6.25 X 8.25 PARA EVITAR ELQ EL SEGMENTO ROTO DEL FRANGIBLE PUDIERA LLEGAR A SOLTARSE Y O BIEN TAPAR LA SALIDA DEL LÍQUIDO O BIEN IR A PARAR DENTRO DE LA BOLSA.\r\n', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-18'),
	(50, 49, 'LUEGO DE LOS ENSAYOS DEL MOLDE DE CONECTOR VIAL SE VE QUE SE DEBE TRABAJAR CON UNA REFERENCIA DE ALTA FLUIDEZ. SE PIDE A BAYER UNA MUESTRA DE ESTE MATERIAL EVIDENCIANDO QUE EL MOLDE TRABAJA MUCHO MEJOR, Y SE HACE LA IMPORTACIÓN DE ESTE MATERIAL. EN LA FICHA TÉCNICA COSTA LA REFERENCIA ADECUADA.\r\n\r\nPARA EL FRANGIBLE SE DEFINE EL USO DE LAS MISMAS REFERENCIAS DE POLICARBONATO USADAS PARA LOS SITIOS DE INYECCIÓN\r\n\r\nPOR OTRA PARTE, PARA EL ANILLO LUER LOCK, DEL QUE NO SE TIENE MOLDE, SE PIDEN MUESTRAS A HAEMOTRONIC.\r\n\r\nLA IDEA SERÁ USAR ESTA PIEZA ESTÁNDAR Y HACER A MANO EL ENSAMBLE DE LAS PARTES.\r\n\r\nGERMÁN PINZÓN SE ENCARGA DE LA MÁQUINA QUE SIRVE PARA ENSAMBLAR DICHO ANILLO CON EL CONECTOR VIAL\r\n', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-18'),
	(51, 50, 'EL PRODUCTO SE ACEPTA SI:\r\n\r\nESTÁ HECHO CON LOS POLICARBONATOS RECOMENDADOS, SU ENSAMBLE SE HACE CON CONECTOR Y ANILLO LUER LOCK, LA RUPTURA DE LA PARTE NO GENERA PARTÍCULAS INDESEABLES, Y NO EXISTEN FUGAS DE LÍQUIDO ENTRE EL TUBO Y EL FRANGIBLE O ENTRE EL CONECTOR VIAL Y EL VIAL.\r\n', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-18'),
	(52, 53, 'AL CONTAR CON AUTOCLAVE EN EL LABORATORIO, PODEMOS SIMULAR \r\n1.	LLENADO DE BOLSA\r\n2.	CIERRE CON EL CONJUNTO\r\n3.	ESTERILIZACIÓN EN AUTOCLAVE\r\n4.	EVALUACIÓN DE LOS RESULTADOS DE FUGAS, PARTÍCULAS DE RUPTURA, Y EL DESENSAMBLE NO DESEADO\r\n', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-18'),
	(53, 54, 'LOS PROBLEMAS DERIVADOS DEL SISTEMA DE ENSAMBLE DE LAS PIEZAS, TALES COMO RESIDUO DE PEGANTES, O REBABAS PRODUCIDAS POR SOLDADURA ROTACIONAL SE IDENTIFICARON EN LAS PRUEBAS, RAZÓN POR LA CUAL SE DECIDIÓ EL ENSAMBLE LUER USANDO NIPLE DE PVC (TUBO)', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-24'),
	(54, 57, 'EL CONTROL DE LOS CAMBIOS QUE SE REQUIRIERON DURANTE LA FABRICACIÓN DE LOS MOLDES ESTÁ A CARGO DE NÉSTOR CASTILLO', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-18'),
	(55, 48, 'REALIZAR PRUEBAS DE ESTANQUEIDAD, PASO DE LIQUIDO ATRAVEZ DEL ENSAMBLE, SOLDADURA EN EL ENSAMBLE Y VERIFICACIÓN DE PARTICULAS.', 0, '[4]', 'PRIMER PRUEBA : DE 23 UNIDADES SE EVIDENCIA 6 CON FALLA EN LA SOLDADURA. TAMBIÉN SE ENCUENTRA UNA BOLSA CON PARTÍCULA AZUL Y OTRAS DOS CON PARTÍCULAS BLANCAS (ASPECTO PELUSA). SEGUNDA PRUEBA: DE 20 UNIDADES FALLARON 11 POR SOLDADURA, UNA CON PUNTA DEL FRANGIBLE DENTRO DE LA BOLSA Y SE OBSERVA RUPTURA DEL CONECTOR VIAL AL ENSAMBLARLO. ', '4', '2016-02-18 17:54:22', 0, 0, 3, '5', '2016-02-18'),
	(56, 37, 'SE ENVÍAN TRES LOTES PARA EVALUACIÓN POR PARTE DEL CLIENTE. \r\nADJUNTO CERTIFICADOS DE CALIDAD Y DESPACHO DEL PRODUCTO.', 1, '', NULL, NULL, NULL, 0, 0, 3, '4', '2016-02-19'),
	(57, 48, 'REALIZAR NUEVAS PRUEBAS CON LA MODIFICACION DEL COMPONENTE BÁSICO SIN ROSCA Y EL NIPLE PARA CONEXION.', 0, '[4]', 'SE REALIZAN PRUEBAS FUNCIONALES CON LA NUEVA MODIFICACIÓN Y CUMPLEN CON TODAS LAS ESPECIFICACIONES, NO SE OBSERVAN PARTÍCULAS SUELTAS, BUENA HERMETICIDAD ENTRE EL FRANGIBLE Y EL VIAL Y NO SE OBSERVAN FUGAS ENTRE LA CONEXIÓN AL DUCTO DE LA BOLSA.', '4', '2016-02-19 16:15:10', 0, 0, 3, '5', '2016-02-19'),
	(58, 48, 'REPORTAR DIMENSIONALES DE CADA UNO DE LOS COMPONENTES BÁSICOS Y EL ENSAMBLE.', 0, '[16]', 'SE REPORTAN DIMENSIONALES DE LA PIEZA EN LA PROGRAMACIÓN DE PRUEBAS.\r\nTODAS CUMPLEN.', '16', '2016-02-19 16:39:40', 0, 0, 3, '4', '2016-02-19'),
	(59, 51, 'SE ADJUNTA RESULTADOS DE ESTERILIDAD DEL PRODUCTO. \r\nRESULTADO APROBADO.', 0, '', NULL, NULL, NULL, 0, 0, 3, '4', '2016-02-19'),
	(60, 56, 'SE ENVÍA PRODUCTO AL CLIENTE  CON CERTIFICADO DE CALIDAD 45385.', 0, '', NULL, NULL, NULL, 0, 0, 3, '4', '2016-02-19'),
	(61, 55, 'SE VERIFICÓ CADA REGISTRO EN LA PROGRAMACIÓN DE LAS PRUEBAS COMO EVIDENCIA.', 0, '', NULL, NULL, NULL, 0, 0, 3, '4', '2016-02-24'),
	(62, 50, 'SE ADJUNTA NUEVA FICHA TÉCNICA CON LOS CAMBIOS DEL FRANGIBLE Y EL NIPLE.', 0, '', NULL, NULL, NULL, 0, 0, 3, '4', '2016-02-19'),
	(63, 52, 'LOS REGISTROS DE TRAZABILIDAD DE ESTE PRODUCTO SE ENCUENTRAN EN EL BATCH RECORD.', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-24'),
	(64, 39, 'VER DOCUMENTO ANEXO', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-24'),
	(65, 46, 'EXISTE ANTECEDENTE DE LOS SITIOS DE INYECCION USADOS EN LAS BOLSAS DE NUTRICION PARENTERAL QUE SE ESTERILIZAN TAMBIEN EN ETO Y QUE SON FABRICADOS EN EL MISMO MATERIAL', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-24'),
	(66, 49, 'SE EVIDENCIA QUE EL LA UNION VIA EL ANILLO QUE SE PRETENDÍA IMPORTAT DE HAEMOTRONIC SE PUEDE DESENSAMBLAR MUY FACILMENTE, POR LO QUE SE DECIDE USAR UN NIPLE DE UNION EN PVC FLEXIBLE. EL PVC FLEXIBLE SE ADHIERE AL POLICARBONATO IMPIDIENDO EL DESENSAMBLE', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-24'),
	(67, 56, 'EL CLIENTE FRESENIUS APRUEBA  EL  PRODUCTO A TRAVEZ DE UNA NUEVA ORDEN DE COMPRA.', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-24'),
	(68, 24, 'por solicitud del cliente se cambian el espesor de la pared sencilla de 0.30 mm a:\r\n1. 0.27 mm, con espesor de soldadura de 0.26+/-0.03\r\n2. 0.33 mm. con espesor de soldadura de 0.28+/-0.03.', 0, '[3][12][7][4][10]', 'Envío resultado de pruebas funcionales, solo cumplió el espesor de pared sencilla de 0.27 mm con espesores de sellado de 0.29 y 0.32, las demás fallaron en la prueba de caída.', '4', '2016-03-11 10:02:44', 1, 0, 3, '5', '2016-03-02'),
	(69, 58, 'Dentro de la estrategia de la compañía se ha establecido la producción de bolsas para sangre. Este proyecto se llevará a cabo en varias etapas, iniciando con la producción de las denominadas Bolsas de Transferencia. Estas bolsas se consideran dispositivos médicos, y se deben esterilizar entre otras posibilidades con Oxido de Etileno. Una segunda etapa para el futuro será la de la fabricación de bolsas de sangre y plaquetas, y estas requerirán un proceso farmacéutico consistente en la preparación de anticoagulantes y su esterilización con vapor, actividad que deberá desarrollarse en un laboratorio farmacéutico propiamente dicho', 1, '[3][5][6][12][7][2][4][16][10]', 'Se considera cerrado y comunicado el Establecimiento de Objetivos del Diseño', '5', '2016-03-03 16:06:41', 1, 0, 3, '5', '2016-03-03'),
	(70, 59, 'Etapas preliminares: La inquietud de desarrollo de este producto empezó hace varios años, pero sólo hasta ahora con la situación particular de mercado, se liberan las máquinas en las que se puede acometer esta iniciativa.\r\nPodemos definir varias etapas.\r\n1. Desarrollo de una formulación que sirva para hacer películas para fabricar tanto bolsas para sangre como bolsas para plaquetas. Este desarrollo se había hecho cuando se pretendía vender película a Diamed, Brasil, por lo que se cuenta con un trabajo previamente hecho.\r\n2. Desarrollo de conector Opercule. Este elemento es el conector de la gran mayoría de bolsas de sangre y de transferencia, y se cuenta con la experiencia previa del desarrollo de un molde de esta naturaleza para la sociedad Macopharma de Francia, molde que se modificó en su momento para hacer el "Spike Port" de las bolsas de PVC que se le vendieron por millones a Fresenius Medical care Colombia\r\n3. Desarrollo del molde en Y en PVC Trabajo ya realizado que se decomuntará en forma restrospectiva en este desarrollo\r\n4. Determinación de la viabilidad de hacer un selle "peelable" para conformar el capuchón protector del opercule.\r\n5. Diseño del procedimiento para ensamblar Opercule + Capuchón\r\n6. Diseño del procedimiento para soldar el conjunto anterior a la boca de la nueva bolsa.\r\n7. Diseño del sistema de soldadura del perímetro incluyendo la generación de las ranuras que quedan en los costados de la bolsa usadas para organizar los tubos de las bolsas.\r\n8. Diseño del sistema para troquelar el contorno e la bolsa propiamente dicha\r\n9. Empaque y esterilización de las bolsas de Transferencia', 1, '[3][5][6][12][7][2][4][8][16][10]', 'El 15 de Junio de 2016, se reciben conectores Opercule del lote interno C1531-26A16 P6206-26F02, se solicita la fabricación de manga que servira para las pruebas de sellado de capuchon.\r\nel 17 de Junio de 2016 se recibe manga para realizar prueba de sellado de capuchon (Lote interno 13901-26F16 P4892-26F17-4).\r\nEl 20 de Junio se realizan pruebas de sellado de capcuhon, encontrando que los mandriles estandar tienen un diametro menor al requerido para esta aplicacion. ', '5', '2016-06-23 09:11:42', 1, 0, 3, '5', '2016-03-03'),
	(71, 1, 'El cliente solicita el desarrollo de un conector twist off para sustituir el actual proveedor de esa pieza. Debemos diseñar una pieza que sea contratipo de la actual.', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-03-03'),
	(72, 10, 'Se evidencia requisito de farmacopea de USA mediante certificado de análisis para plástico clase VI realizado por Toxikon.El plano de trabajo muestra la similitud en las dimensiones de la punta.', 0, '', NULL, NULL, NULL, 0, 0, 3, '1', '2016-03-03'),
	(73, 14, 'Los planos del molde debidamente aprobados son archivados en la oficina del Jefe de proyectos', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-03-04'),
	(74, 15, '1. se define uso de fórmula ya aprobado por el cliente\r\n2. El diseño del molde es similar a moldes que han hecho millones de partes adecuadas para el propósito de este molde\r\n3. El sistema de propuesto para  movimiento del macho que le dará el espesor final a la membrana, y que permite el llenado de la cavisas sin knit lines, es análogo al usado enm el mode del acople Fresenius', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-03-04'),
	(75, 16, 'El principal problema potencial en el uso de esta pieza es que no de haga oportunamente el movimiento del macho durante el ciclo de inyección.\r\n\r\nPienso que Germán puede adicionar sensores de posición y un PLC que monitoree la posición de los machos antes y después de cada inyectada de modo que si el macho no está en la posición alejada antes de la inyección del PVC, o si no finaliza en la posición mas cercana anvíe una señal para detener la operación automática del molde', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-03-04'),
	(83, 36, '<p class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<p class="MsoNormal">\r\n<span style="background-color: #eeeeee; color: #292929; font-family: &quot;Segoe UI&quot;, sans-serif; font-size: 7pt; text-transform: uppercase">LA\r\nVERIFICACI&Oacute;N SE ENCUENTRA EN LAS RESPUESTAS DE CADA UNA DE LAS ACTIVIDADES DEL\r\nPROYECTO.</span>&nbsp;\r\n</p>\r\n', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-03-04'),
	(84, 19, 'EL CONTROL DE LOS CAMBIOS QUE SE REQUIRIERON DURANTE LA FABRICACIÓN DEL MOLDES ESTÁ A CARGO DE NÉSTOR CASTILLO.', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-03-07'),
	(85, 5, 'CONTROL DE CAMBIO 1\r\nEl cliente solicita reducción en el diámetro de conexión al punzón para que el conector sea funcional con otros tipos de punzones del mercado.\r\n', 1, '[4][8][16]', 'Se reduce Ø5.63 a Ø5.43 y se hace ranura de Ø5.03 en los machos de las cavidades D, I, P según plano M-134016.2.0\r\n', '8', '2016-04-21 13:04:17', 0, 0, 3, '5', '2016-04-19'),
	(86, 17, 'Realizar pruebas  funcionales a Cavidades de prueba D ,I ,P:\r\nIntegridad de membrana\r\nIntegridad de twist off\r\nPrueba  de  ensamble en bolsa después de autoclave, perforadas con punzón de diámetro de 5.5 mm comprobar estanqueidad después de  24 horas.\r\nComprobar diámetro de ranura y Diámetro reducido.\r\n', 0, '[16]', 'Se adjunta informe con resultado de pruebas y el detalle de los dimensionales se encuentra en la programación(7.3.5). con fecha 2016-04-21.\r\nla cavidad que  se enviara al cliente es la "P".', '16', '2016-04-19 13:00:21', 0, 0, 3, '4', '2016-04-19'),
	(87, 14, 'Se envían 140 conectores de la Cavidad P, identificados con lote 6985-26D11', 0, '', NULL, NULL, NULL, 0, 0, 3, '4', '2016-04-22'),
	(88, 24, 'Notificación de cliente:\r\n1) Las bolsas "nominales" que nos mandaron en Diciembre tienen un grosor de pelicula de 0.3mm y un grosor de soldadura de 0.27mm, aun no le hacemos las pruebas funcionales por lo que voy a asumir que no van a tener ningun problema. Para nuestras pruebas de verificacion de disenio necesitamos bolsas en los limites inferiores y superiores pero despues de las pruebas de calidad que le hicieron a estas mismas nos estamos dando cuenta de que las tolerancias que inicialmente se asignaron estan mal ya que se encontraron fallas. Por lo tanto, las 6,000 bolsas que tenemos ya no nos servirian como nominal, tendriamos que empezar desde cero. ', 0, '', NULL, NULL, NULL, 0, 0, 3, '4', '2016-03-08'),
	(89, 24, 'fabricar muestras con pared sencilla de 0.29, 0.35 y 0.40 +/- 0.03 mm, para enviar a validación por parte del cliente.', 0, '[3][12][4][10]', 'Se genera orden de producción 1502.', '3', '2016-04-20 12:06:26', 1, 0, 3, '5', '2016-04-19'),
	(90, 33, 'Certificados de calidad de las tres muestras realizadas para enviar al cliente así:\r\nTres lotes :7289-26D18, 7289-26D19, 7289-26D20.\r\nUn lote : 7288-26D19.\r\nUn lote : 7294-26C18.\r\n', 0, '', NULL, NULL, NULL, 0, 0, 3, '4', '2016-04-23'),
	(91, 31, 'Se incluyen nuevas fichas técnicas con las especificaciones con las cuales van a ser fabricadas las muestras  y enviadas al cliente.', 0, '', NULL, NULL, NULL, 0, 0, 3, '4', '2016-04-18'),
	(92, 24, 'El cliente informa de problemas de rupturas en las zonas de los pliegues encontrados en las muestras enviadas. Se decide disminuir unos 4 grados Shore A la dureza de la formulación, y hacer nuevas pruebas.\r\nEs importante que la bolsa siga pudiendo recibir fácilmente el líquido que se le introduzca luego de la esterilización EtO, y que siga resistiendo los ojales.\r\nDiego: Por favor ordenar nuevas pruebas y reportarme resultados de calidad antes de nviar nuevas muestras.', 0, '[3][6][12][7][2][4][16][10]', 'Se ordena a Insumos Luis Edurdo Rodriguez lo siguiente[////]Peletizar la F 11727 v 160711  [////]Extruir manga P 7330 270x 0.35[////]Cantidad 2 rollos[////]Compuesto 2 mezclas de 89 kg[////]Ver tarea en 7.3.2.A', '3', '2016-07-29 16:51:11', 0, 0, 3, '5', '2016-06-21'),
	(93, 77, 'Se debe diseñar una tapa sencilla que pueda reemplazar 2 tipos de tapas usados actualmente en los dializadores de Fresenius Medical Care de Estados Unidos. se busca una reducción de costos y evitar daños en el empaque del producto producidos por la dureza de las tapas actuales en una envoltura que queda muy justa en la actualidad.', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-06-21'),
	(94, 78, 'En diciembre de 2014 se recibe una llamada del Dr. Fernando Aguirre de Fresenius Medical care North America en la que me pide el desarrollo de una tapa para dializador que sustituya las dos tapas que se unsan en la actualidad, y que además generan a veces rupturas en el envoltorio del dializador, envoltorio que debe mantener la esterilidad, y cuya falla genera rechazos en las clínicas de hemodiálisis.\r\n\r\nEnvía muestras físicas del dializador y sus tapas', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-06-21'),
	(95, 79, 'El producto a ofrecer se producirá por inyección. Inicialmente se plantea hacer un molde prototipo que le permita al cliente evaluar las piezas, y una vez aceptado diseño y precio se procederá a solicitar al cliente el capex necesario para la fabricación del molde industrial de colada caliente.\r\nEl molde prototipo se hará en plastitec, y será sufragado por el cliente.\r\nEl cliente deberá aceptar las piezas prototipo.', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-06-21'),
	(96, 80, '*) De la formulación: Eduardo Muñoz\r\n*) Del plano inicial de la pieza: Guillermo Cano\r\n*) Del diseño del molde prototipo: Guillermo Cano\r\n*) De la fabricación del molde prototipo. Néstor Castillo\r\n*) De ordenar pruebas: Diego Orozco\r\n*) De realizar las pruebas: Luis Eduardo Rodríguez\r\n*) De evaluar geometrías de la pieza. Wilmer Hernández\r\n*) De aceptación del prototipo: Fresenius Medical Care North America\r\n*) Buscar empaque adecuado: Luis Felipe Osorio - Milton Manrique', 0, '[3][5][7][2][4][15][8][16]', 'se adjunta dimensionales de la pieza, cumplen con lo especificado en el plano.', '4', '2016-06-21 14:25:54', 1, 0, 3, '5', '2016-06-21'),
	(97, 81, 'La pieza deberá ser usada en los tipos de puerto que tiene el dializador. Se prevé que vaya montada en los puertos inferior y superior del dializador, en los que debe dejar paso de aire, y también en los puertos laterales. En estos puertos debe hacer un cierre hermético mientras se hace el priming del dializador con la solución de diálisis.\r\nEl tapón debe ser fácil desmontar y retirar.\r\nEn fecha posterior, 26 de Mayo de 2016 especifican que la presión que debe soportar la pieza es de 1 bar (Makenzie E. Jones)', 0, '[3][5][7][2][4][8][16]', 'se adjunta informe.', '4', '2016-06-21 14:19:10', 1, 0, 3, '5', '2016-06-21'),
	(98, 82, 'No hay ningún requisito legal o reglamentario,', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-06-21'),
	(99, 83, 'Se toma la idea de la composición del twist off desarrollado para las bolsas de polipropileno ya que el material empleado sirve para generar fricción con el policarbonato, material en el que está hecho el dializador de modo que la pieza no se salga fácilmente, cosa que ocurriría si se hace únicamente con polipropileno', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-06-21'),
	(100, 59, 'Exgtruir un rollo de manga 120 x 0.39  con F 13901   P 4892  y entregarlo a German Pinzon', 0, '[7]', 'Ya se fabricó la manga y se entregó a German Pinzón. Viernes 17/06/2016', '7', '2016-06-21 11:31:49', 1, 0, 3, '3', '2016-06-21'),
	(101, 80, 'Se hacen 2 ranuras en macho P-032013 para generar anillos en diámetro externo de conexión de CB-157 y corregir fuga.\r\n\r\nDiego, le solicito ordenar prueba de molde.\r\n\r\nMª Isabel, le solicito ordenar verificar muestras y notificar resultados, se debe probar con aire a 1 bar le estoy enviando el filtro optiflux.\r\n', 0, '[3][5][7][2][4][8][16][10]', 'Se genera informe el 21 de Junio en los numerales 7.3.1 C y 7.3.2 A', '4', '2016-07-28 12:25:49', 1, 0, 3, '8', '2016-06-22'),
	(102, 59, 'Registro de nombre comercial (Hemoflex) y Obtención del Registro Sanitario.\r\n\r\nEl registro se tramita con la colaboración del abogado Luis Carlos Urquijo', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-06-22'),
	(103, 63, 'Se debe registrar el nombre comercial "HEMOFLEX" así cono obtener el registro sanitario de la bolsa de transferencia.\r\nSe coordina con Catalina Angel el trabajo del abogado externo Luis Carlos Urquijo', 0, '[5]', NULL, NULL, NULL, 0, 0, 1, '5', '2016-06-23'),
	(104, 99, 'Se realizan pruebas de sellado de capuchón con opercule usando mandriles estándar de 4.5 mm de diametro. Por esta razon el dia 2016/06/24 se solicita al area de proyectos la fabricacion con mandriles de 5mm de diametro de punta redonda. El 27 de junio de 2016 se realizaron pruebas de sellado. El resultado es optimo en cuanto a que se hizo mas parejo el sellado al rededor del mandril. Sin embargo se observa que el diametro de los electrodos es insuficiente. Actualmente es de 7 mm. Por tal  razon se solicita al area de proyectos que incremente este diametro a 7.3 mm. ', 0, '', NULL, NULL, NULL, 0, 0, 3, '6', '2016-06-28'),
	(105, 19, 'El 2016-05-24 se retorna de Ø5.4 a Ø5.6 y se mantiene el anillo de Ø4.9 en las cavidades D, I, P[////]Se adjuntan planos de la mariposa y el ensamble', 1, '', NULL, NULL, NULL, 0, 0, 3, '8', '2016-06-06'),
	(106, 17, 'Verificar los cambios:  de Ø5.4 a Ø5.6 y mantenimiento del anillo de Ø4.9 en las cavidades D, I, P[////]Se adjuntan planos de la mariposa y el ensamble adjuntados por Nestor Castillo en Control de Cambios', 1, '[16]', ' Se adjunta informe con resultado de pruebas y el detalle de los dimensionales se encuentra en la programación(7.3.5). con fecha 2016-06-08. la cavidad que se enviara al cliente es la "P", ya que la "I", Presenta una rebaba en la parte superior y el anillo de la cavidad "D" esta muy grande (5.1 mm).', '16', '2016-06-08 11:34:59', 1, 0, 3, '4', '2016-06-07'),
	(107, 14, 'Se envían 200 unidades de la cavidad P el 2016-06-10 identificadas con el lote 6985-26C07 ', 1, '', NULL, NULL, NULL, 0, 0, 3, '4', '2016-06-10'),
	(108, 24, 'Luis Eduardo,[////][////]Peletizar la F 11727 v 160711 .[////]Extruir manga P 7330  270x 0.35[////]Cantidad             2 rollos[////]Compuesto        2 mezclas de 89 kg[////]', 0, '[7]', 'Se peletiza  compuesto formula 11727 v 160711 con lote C:11727-26G12-5 en la E5C, se fabrican 2 rollos de manga 270*0.35  código: 7330 en la E5M y se hace entrega a almacén.[////][////]Durante la prueba el proceso fue estable y no se presentaron novedades.', '7', '2016-07-12 16:16:56', 1, 0, 3, '3', '2016-07-12'),
	(109, 24, 'Wilson,[////][////]Fabricar bolsas con electrodos 270  OPB16-019[////]', 0, '[12][10]', 'Se realiza montaje de electrodos # 950-951 para sellar bolsas drenaje 7 litros, se tienen inconvenientes con el ajuste del troquelado ya que, con la calidad de troquelado estándar el ojal se rasga, se ajusta cada troquel independientemente para realizar los sellados, los cuales según informes de calidad pasan las pruebas respectivas. cabe anotar que el ajuste de los troquelados llevo bastante tiempo ( el doble del nominal) y el filo de los troqueles no se podría garantizar para producciones de alto volumen de unidades. Así mismo el cuadre del sellado presenta fallas ya que los troqueles quedan en el mismo electrodo. SE SUGIERE TROQUELADORA INDEPENDIENTE AL SELLADO para disminuir tiempos de sellado y optimizar el proceso. ', '12', '2016-07-21 08:48:46', 0, 0, 3, '3', '2016-07-12'),
	(110, 24, 'Ma. Isabel, Leidy, Wilmer,[////][////]Bolsas dobladas en 4/4 a estufa 54 °C durante 1 hora [////][////]Llenado por goteo[////][////][////]Condiciones:[////][////]Carga nominal de 7Litros mas una fuerza adicional de 15N, durante una hora. [////]Se prueban los 3 hojales.[////]', 1, '[4][16]', 'SE ADJUNTA IMAGEN DE SEGUNDAS PRUEBAS DE OJAL CON CONCEPTO CUMPLE. AUTOCLAVE: CUMPLE -HERMETICIDAD: CUMPLE -PRENSA: CUMPLE -ESTALLIDO: CUMPLE - GOTEO: CUMPL', '4', '2016-07-26 11:45:35', 1, 0, 3, '3', '2016-07-12'),
	(111, 24, 'Debido a las dificultades en el ajuste de electrodos debemos extruir 3 rollos adicionales de la manga P 7330  270x 0.35', 0, '[7]', 'Se fabrican 4 rollos de manga 270*0.35 código 7330 con lote: 11727-26G14  y se entregan al almacen producto en proceso', '7', '2016-07-15 14:24:34', 1, 0, 3, '3', '2016-07-15'),
	(112, 5, 'En los machos lado boquilla de las cavidades D, I, P se retorna de Ø5.63 a Ø5.43 se mantiene ranura para anillo y en la punta de ambos machos se eliminan radios de 0.5 mm[////]Diego, le solicito ordenar prueba de molde.', 1, '[3][4][16]', 'Asigono a Luis Eduardo Rodriguez actividad en 7.3.2 A', '3', '2016-07-25 16:52:00', 0, 0, 3, '8', '2016-07-22'),
	(113, 5, 'En los machos lado boquilla de las cavidades D, I, P se retorna de Ø5.63 a Ø5.43 se mantiene ranura para anillo y en la punta de ambos machos se eliminan radios de 0.5 mm[////]Diego, le solicito ordenar prueba de molde. [////]Luis Eduardo proceder utilizando la F 16201 TVA v 11-08-25', 0, '[7]', 'Se fabrican 500 unidades de mariposa código 6984 con formula 16201: LOTE = C16201-26C07 P6984-26G25, se entrega al almacén producto en proceso. ', '7', '2016-07-26 07:54:54', 1, 0, 3, '3', '2016-07-25'),
	(114, 5, 'Se fabrican 500 unidades de mariposa código 6984 con formula 16201: LOTE = C16201-26C07 P6984-26G25, se entrega al almacén producto en proceso. [////]Ma. Isabel hacer la verificacion de estas mariposas ', 0, '[4]', 'Se entregan 400 unidades a Felipe Osorio para despacho al cliente CC 48193', '4', '2016-07-28 14:45:28', 1, 0, 3, '3', '2016-07-26'),
	(115, 33, 'Se envian 50 bolsas  identificadas con lote 7184-26G14. El 15 de Julio de 2016', 1, '', NULL, NULL, NULL, 0, 0, 3, '4', '2016-07-26'),
	(116, 5, 'Debemos hacer nuevas muestras de mariposa de PVC para Fresenius USA.[////][////]Por favor hacer un compuesto basado en el F16211 (Interstab GS-4571) pero 2 grados shore A menos que la F 16201[////][////]Por favor ordenar fabricación de esas muestras (Igual cantidad de las que enviamos la última vez)[////][////]Ver informe adjunto.', 1, '[3]', 'Se genera F16237 ver entradas dpto de produccion', '3', '2016-09-06 16:06:17', 0, 0, 3, '5', '2016-09-06'),
	(117, 5, 'Debemos inyectar mariposas para Fresenius USA. Alistar el molde e informar las cavidades que tinen el ultimo diseño.', 0, '[8]', 'Se habilita el resto de machos según planos M-134016.4 y M-134015.5 de la última prueba.[////]', '8', '2016-09-12 12:56:57', 0, 0, 3, '3', '2016-09-06'),
	(118, 5, 'FAbricar compuesto con la F 16237', 0, '[7]', 'Se fabrica compuesto formula 16237 lote 16237-26I06-5 quedo en espera de entrega del molde para realizar las muestras', '7', '2016-09-07 07:31:18', 1, 0, 3, '3', '2016-09-06'),
	(120, 5, 'Se entregan a Calidad muestras para verificacion  mariposas Lote  6984-26I28', 0, '[4][16]', 'Se verifican muestras, se realizan pruebas, todas con resultados cumple.[////]Se adjunta informe.', '16', '2016-09-29 16:58:50', 1, 0, 3, '3', '2016-09-29'),
	(121, 5, 'Wilson ensamblar 500 mariposas P 6984-26I28 con cupula P 6661-26I06 segun OPB16-030 ver adj', 0, '[10]', 'se ensamblan 500 unidades con los siguientes insumos:[////]mariposa C:16237-26I28  P:6984-26I28-1[////]cupula  C:16237-26I06   P:6661-26I23-2[////]Lote generado: 6985-26I28[////]Se entrega a logistica en R-PRF 017 # 35015.[////]', '10', '2016-09-29 17:19:22', 0, 0, 3, '3', '2016-09-29'),
	(122, 5, 'PF  entrega a logistica en R-PRF 017 # 35015. Ma. Isabel emitir el Certificado de Calidad', 0, '[4]', 'Se envían 500 mariposa lote 6985-26I28 según FT-E-0234 v3.[////]de todas las cavidades, con los siguientes cambios:[////]1. Formula 16237[////]2. Anillo con Diámetro interno 4.9+/-0.1mm [////]3. Reducción Diámetro Interno parte recta ( zona cerca de la membrana)  a  5.1[////]', '4', '2016-09-30 12:12:28', 1, 0, 3, '3', '2016-09-30'),
	(124, 57, 'Con el fin de facilitar el llenado y la operación del molde M-110 aumentar el diámetro externo del punzón del conector vial de 3.65 a 3.95 mm. Así mismo ajustar la tapa protectora a este nuevo diámetro.', 0, '[8]', 'El 2017-01-05 se amplía 0.3 mm el diámetro externo de la punta del conector vial.[////]El 2017-01-24 se modifica molde prototipo P-031 ampliando 0.3 mm el cono interno ajustando a punta vial.', '8', '2017-01-05 13:35:35', 1, 0, 3, '5', '2016-12-10'),
	(126, 57, 'Se amplía 0.3 mm el diámetro externo de la punta del conector vial y el diámetro interno del protector punta vial[////]Diego, le solicito ordenar prueba de moldes M-110 y P-031 (M-135)', 1, '[3]', 'Se hacen varios  montajes a partir del 2017-01-05', '3', '2017-01-05 16:50:21', 0, 0, 3, '8', '2017-01-05'),
	(127, 57, 'Verificar muestras y notificar resultados tanto del conector vial como de la tapa protectora', 0, '[4][16]', 'Se realizaron pruebas tanto de conector vial como de la tapa protectora, ambos con resultados satisfactorios. (cumple)[////][////]Ver informes de los resultados de las pruebas realizadas en los archivos adjuntos.', '16', '2017-01-10 17:23:07', 1, 0, 3, '3', '2017-01-10'),
	(128, 57, 'Generar Certificado de Calidad para las muestras', 1, '[4]', 'Se envían 20 unidades Conector Vial + Frangible Azul lote 6850-27A24 ', '4', '2017-01-27 17:35:28', 1, 0, 3, '4', '2017-01-27'),
	(129, 5, 'Debemos hacer nuevas muestras de mariposa de PVC para Fresenius USA, por falla en la membrana de las cavidades J Y L.[////][////]Por favor hacer compuesto  F16201( formula anterior).[////][////]Ordenar fabricación de esas muestras incrementando el espesor a 0.60 mm.', 1, '[3][8]', 'Se genera OPB17-008 para la fabricacion y envio de 10.000 mariposas a FUSA', '3', '2017-02-25 14:38:13', 1, 0, 3, '5', '2017-02-02'),
	(130, 5, 'Actualizar FT y reportar resultado de pruebas', 1, '[4][16]', 'Se generan nuevas versiones en las fichas técnicas de componente básico y  ensamble, incluyendo la formula 16201 y el nuevo espesor de membrana.', '4', '2017-02-22 16:03:49', 1, 0, 3, '3', '2017-02-21'),
	(131, 5, 'Reportar resultado de pruebas realizadas.', 1, '[16]', 'Se realizan todas las pruebas con resultados "cumple".', '16', '2017-02-27 16:31:25', 0, 1, 3, '4', '2017-02-27'),
	(132, 5, 'Se envían 10.000 mariposas lote 6985-27B16 según FT-E-0234 v4.[////]de todas las cavidades, con los siguientes cambios:[////]1. Formula 16201[////]2. Espesor de membrana 0.6+/-0.1[////]', 1, '', NULL, NULL, NULL, 0, 0, 3, '4', '2017-03-02'),
	(133, 31, 'Revisadas las formulas de manga y ductos (2) debemos reasignar  las de los ductos 885 y 1022  a  codificacion de la serie 11727. Esta es una modificacion documental unicamente.', 0, '[3]', 'Se asignan para los ductos los numeros de formula asi:[////]P 6780  F 11729 (era 885)[////]P 2705 F 11730  (era 1022)', '3', '2017-02-28 11:39:01', 1, 0, 3, '5', '2017-02-28'),
	(134, 31, 'Modificar la FT-DT-1454 con la nueva codificacion de las F de los ductos ', 1, '[4]', 'Se cambia FT-DT-1454 A V5 incorporando los siguientes cambios:[////]1. Ducto externo código 6780 F 11729 (era 885)[////]2. Ducto interno código 2705 F 11730 (era 1022)', '4', '2017-03-01 11:52:27', 1, 0, 3, '3', '2017-03-01'),
	(135, 119, 'Colocar casquetes esféricos  para obtener resaltes anti adherencia en el pistón siliprene.', 0, '[8]', 'Se ersionan casquetes esfericos inscritos en un circulo de Ø5.8', '8', '2017-03-31 11:16:32', 0, 0, 3, '5', '2017-03-30'),
	(136, 119, 'Desarrollar formulas que nos permitan tener mejor resellabilidad del septum de los sitios de inyección.', 0, '[3]', 'Se desarrollan formulas compuesto F siliprene 13644,  13645 y 13646.[////][////][////]', '3', '2016-04-04 15:37:09', 1, 0, 3, '5', '2016-04-01'),
	(137, 119, 'Favor hacer puertos con estos 3 tipos de pistones que están identificados con sus respectivas formulas. [////]Cantidad la que se considere necesaria.[////]', 0, '[10]', 'REPORTE DE FABRICACION:[////][////]TURNO TRES:[////][////]PRUEBA 1 Fórmula 13645-26D20 [////][////]Se producen 30.000 unidades la maquina molesta en la alimentación del pistón.[////]El pistón se encuentra demasiado siliconado, y se pega a las tolvas[////][////]TURNO UNO:[////][////]PRUEBA 2 Fórmula 13646-26D20[////][////]Se producen 40.000 unidades  ninguna novedad, trabaja bien la máquina.[////][////][////]PRUEBA 3 Fórmula 13644-26D20[////][////]Se producen 40.000 unidades  la máquina molesta porque no alimenta pistón[////][////]', '10', '2016-04-20 15:57:51', 1, 0, 3, '3', '2016-04-15'),
	(138, 119, 'Hacer pruebas de resellabilidad según instrucciones de don Eduardo Muñoz.', 0, '[4]', 'Se realizan pruebas de las tres formulaciones.[////]ver informe adjunto.', '4', '2016-04-25 16:00:08', 1, 0, 3, '3', '2016-04-23'),
	(139, 119, 'Producir pistón con  el compuesto fabricado  F 13646[////]Código: P 7459.[////]Fabricar puerto estándar calidad Fresenius Andina.[////]Código P 7460[////][////]', 0, '[12][7][10]', 'Se realizan pruebas con el nuevo pistón en las líneas grafadoras 3-4 durante 24 horas. El comportamiento de la maquina se afectó en la alimentación de la tolva circular a la lineal ya que el pistón es más sensible al proceso de vibración de la tolva (se evidencio durante el trabajo de la máquina que salta más) por esta razón es más difícil guiarlo para que ingrese a la lineal, adicional muchos de los pistones se pegaron en parejas dificultando la correcta ubicación para el ingreso al lineal (podría ser por la silicona aunque con el estándar no es tan frecuente este comportamiento) se realizaron trabajos para poder manejarlo, reemplazo por fibras nuevas, ajuste con el límite mínimo, nominal y máximo del nivel de vibración (frecuencia), alineación mecánica del sistema, cambio de las tapas de acrílico por unas 5 mm más largas, finalmente una persona pendiente empujando el pistón en los momentos en que se quedaba estancado, este comportamiento se evidenció en los dos equipos de prueba grafadoras 3-4, pero hasta el momento de inicio de la prueba venían trabajando bien.[////]Debemos definir si finalmente se va a trabajar con este pistón para realizar cambios más significativos en los equipos como aumentar el área de sand blasting a las tolvas lineal e incluir la circular, en la grafadora 4 se debería remplazar el sistema de vibración circular (tema ya expuesto y en cotización)  ya que sí se evidencia un cambio entre los dos productos que afecta la cadencia de producción de la maquina además de requerir una persona moviendo los pistones. [////]', '12', '2016-06-05 16:16:45', 1, 0, 3, '3', '2016-06-02'),
	(140, 119, 'No son buenas noticias para este proyecto, ya que por ahora todos los sitios que use Fresenius MEDICAL care Colombia deberán ser así.[////][////]Una característica que he visto en casi todos los pistones en caucho, es que tienen en cada cara plana 4 pequeños puntos en alto relieve, que sirven para que las caras planas  impregnadas en silicona no se puedan tocar directamente, precisamente para no quedar pegadas. En la semana entrante veremos con Diego y Nestor la conveniencia de hacer esta modificación con el fin de ver si logramos mejorar el uso de este nuevo pistón.[////]', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-06-06'),
	(141, 119, 'Se erosionan casquetes esféricos de R0.5 Prof. 0.12 para obtener resaltes anti adherencia en el pistón siliprene quedan con distancia entre centros de 5.2 mm inscritos en un circulo de Ø5.8 según plano M-057002.3.0[////]Solicito ordenar prueba de molde verificación de muestras.[////]', 1, '[3][4]', 'Se evalúan dos lotes de la formula blanda 13646 comparándola con la formula estándar 1369 y en las dos lotes evaluados se observa una desmejora en el aspecto por la presencia de rajaduras críticas y formación de brotes que sobresalen del diámetro de conformado.[////][////]ver informe adjunto.', '4', '2017-05-10 15:12:59', 1, 0, 3, '8', '2017-04-17'),
	(142, 119, 'Luis Eduardo,[////][////]Extruir compuesto SILIPRENE con fórmulas 13644 y 13647.  Reportar novedades del proceso.[////][////]Inyectar mínimo 40.000  pistones con c/u de estas fórmulas IDENTIFICADOS con el número de formula.[////]', 0, '[7]', '  El comportamiento en la peletizada fue el siguiente: la fórmula 13647 fue complicado la extrusión equivalente a la fórmula 13646, la  fórmula  13644 sin novedad en la extrusión, en estos momentos se está inyectando la fórmula 13647  comportándose de la misma manera que la fórmula 13646, en los dos casos las formulas 13646 y 13647 son muy similares.  [////] [////]', '7', '2017-05-10 16:44:14', 1, 0, 3, '3', '2017-05-10'),
	(143, 119, 'Wilson, Jaime,[////][////]Fabricar puerto estándar en las dos grafadoras con los pistones inyectados con Formulas 13644 y 13647. Reportar novedades del proceso.[////]', 0, '[12][10]', 'SE REALIZAN PRUEBAS CON NUEVO PISTON EN LAS GRAFADORAS 3-4 SIN PRESENTAR NOVEDADES EN LAS TOLVAS CIRCULARES NI EN EL SISTEMA DE ALIMENTACION AUTOMATICO.', '12', '2017-05-15 15:51:24', 1, 0, 3, '3', '2017-05-10'),
	(144, 119, 'Hacer las pruebas a los puertos estandar fabricados con pistones formulas 13644 y  13647. Incluir las pruebas de resellabilidad con aguja calibre 18 G', 0, '[4][16]', ' Se evalúan dos lotes de la formula blanda 13647, 13644 comparándola con la formula estándar 1369 y solo en uno de los lotes evaluados se observa una mejora notable en el aspecto por disminución de rajaduras críticas  en la formula 13644.[////][////]Se adjunta informe[////]', '4', '2017-05-15 11:21:26', 1, 0, 3, '3', '2017-05-10'),
	(145, 109, 'Se adjunta plan de riesgos para este cambio en la formulación.', 1, '', NULL, NULL, NULL, 0, 0, 3, '4', '2016-04-07'),
	(146, 101, 'Mejora de producto. Se busca mejorar la resellabilidad del septum de los sitios de inyección para que soporte su uso con agujas calibre 1.2 mm de duámetro', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-19'),
	(147, 102, 'pedir asesoría a fabricante de materia prima', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-03-06'),
	(148, 104, 'Desarrollo de pistón que tolere calibres de aguja mayores que los aprobados por norma ', 0, '[3][12][7][4][8][16][10]', 'Se inician pruebas con diferentes formulaciones:[////]13644-26D20: CUMPLE[////]13645-26D20: NO CUMPLE (FALLO 1/100)[////]13646-26D20: CUMPLE[////]ESTANDAR  1369-26B18: NO CUMPLE (FALLO 1/100)[////]Se hace prueba con aguja Calibre 18 ( diámetro 1.26 mm)[////][////] [////]', '4', '2016-02-21 15:57:01', 0, 0, 3, '5', '2016-02-20'),
	(149, 105, 'Debe cumplir con la  ISO 8871-1[////]y las especificaciones dadas en la FT-CB-0040V3', 0, '[4]', 'Se adjunta correos del cliente solicitando cambio:[////]De: Arturo.Paez@fmc-ag.com [mailto:Arturo.Paez@fmc-ag.com] [////]Enviado el: jueves, 21 de abril de 2016 09:36 a.m.[////]Para: EXTERN Maria Isabel[////]CC: William.Alfonso@fmc-ag.com[////]Asunto: RE: Cumplimiento de ISO 8871-5 Elastomeric parts for parenteral and for devices for pharmaceutical use[////][////]Maria Isabel buenos días: [////][////]Durante la visita realizada con Don Eduardo y el Dr Alfonso a la central de mezclas evidenciamos las siguientes condiciones de trabajo: [////][////]1.        Se están usando en el proceso de preparación agujas calibre 14 y 16. (Mas gruesas que las de calibre 21 que son las aprobadas por la norma) [////]2.        Se realizan varias penetraciones en un mismo elastómero con la misma aguja y también en diferentes elastómeros con la misma aguja [////]3.        Se evidenció fuga en el elastómero  en 4/ 8 bolsas  que se probaron con la aguja calibre 14. [////]4.        Se verificó el proceso de mezcla y el tiempo de permanencia de la aguja es superior al indicado en la norma. [////]', '4', '2016-04-21 15:42:07', 0, 0, 3, '5', '2016-04-21'),
	(150, 103, 'Datos de diseño previo FT-CB-0040 v3', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-18'),
	(151, 106, 'ISO 8871-1', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-24'),
	(152, 110, 'Cumplir pruebas descritas en  I-GC-008', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-04-28'),
	(153, 112, 'Criterios dados en I-GC-008', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-22'),
	(154, 113, 'Prueba de permeabilidad a microorganismos', 0, '[4]', 'Se envía muestra a Laboratorio para prueba de Permeabilidad a Microorganismos 13644-27E10 (P7444) puerto 7084-27E10', '4', '2017-06-12 16:16:44', 1, 0, 3, '5', '2017-06-12'),
	(155, 117, 'Véase 7.3.6 ', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2016-02-25'),
	(156, 121, 'El objeto de esta modificación es poder tener un segundo proveedor de materia prima usada en la capa exterior de las películas de polipropileno. Este sería un proveedor local y se busca poder tener en lo posible un menor costo en la película.[////]Se desea usar como contratipo del Bormed HD800CF el Propilco 08H85-1', 0, '[3][5][6][12][7][2][4][16][10]', NULL, NULL, NULL, 0, 0, 1, '5', '2017-06-13'),
	(157, 122, 'Las etapas serán:[////]Búsqueda de la referencia que sería la candidata a reemplazar la materia actual basada en propiedades reportadas en las fichas técnicas.[////]Emisión de las órdenes de fabricación de los ensayos[////]Evaluación del comportamiento del material durante la coextrusión de la película[////]Evaluación de aspecto de la película[////]Evaluación del comportamiento de la película durante la soldadura de las bolsas[////]Evaluación del comportamiento de las bolsas terminadas', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-06-13'),
	(158, 123, 'Se tienen las fichas técnicas tanto del material existente como el del candidato a contratipo. Verifico que las propiedades de punto de fusión sean similares, así como el tipo de polímero (homopolímero en ambos casos)', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-06-13'),
	(159, 124, 'Dentro del marco del proyecto de desarrollo de una segunda materia prima para reemplazar el polipropileno de la capa externa de las películas se definan las siguientes responsabilidades y autoridades.[////]Diego Orozco: Ordenar las pruebas de coextrusión[////]Eduardo Muñoz: Coordinar la modificación[////]Jaime Villegas: Evaluar el desempeño de la película en el proceso de soldadura[////]Luis Eduardo Rodríguez:Correr los ensayos de coextrusión y reportar el comportamiento[////]Luis Felipe Osorio: Si el desarrollo es exitoso deberá negociar un precio competitivo frente a los costos actuales del material actual. [////]María Isabel Colmenares y Wilmer Hernández: Evaluación de apariencia de la película, y de los resultados de las pruebasde calidad prescritas internamente para liberar el producto Película de PP y bolsas de PP[////]Wilson Bustos. Supervisar el desempeño del material durante el proceso de soldadura y empaque de las bolsas de prueba', 1, '[3][5][12][7][2][4][16][10]', 'resulatdos reportados en actividades del proyecto.', '4', '2017-08-24 16:47:06', 0, 0, 3, '5', '2017-06-13'),
	(160, 125, 'La película con el nuevo material en la capa externa debe cumplir las mismas exigencias de la película actual. [////]Apariencia, [////]sellado de bolsas, [////]no contaminación de las herramientas de soldadura,[////]Integridad de las bolsas fabricadas[////]Pruebas de caída,[////]', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-06-13'),
	(161, 126, 'Los mismos de la película actual[////][////]En cuanto a Biocompatibilidad:[////]ISO 15747[////]Farmacopea Europea monografía 3.2.2.1[////]Plástico clase VI USP[////]Prueba inyección Intracutánea[////]Prueba Inyección sistémica[////]Pirógenos[////]Citotoxicidad[////]Hemólisis[////][////]Nota: Dado que no hay modificación de la capa en contacto con las soluciones no se requiere repetir las pruebas citadas.[////][////]Las pruebas funcionales de resistencia si se evaluarán internamente.[////][////]', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-06-13'),
	(162, 127, 'Se había intentado usar en el pasado el Propilco 08H85DB-BC.[////]Daba muy buena apariencia pero los aditivos antislip que tiene esta referencia migraban a la herramienta de soldadura afectando la calidad del sellado, por lo que se requería paradas contantes para limpiar la herramienta.[////]El nuevo material es básicamente el anterior sin los aditivos antiblock y antislip.', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-06-13'),
	(163, 128, 'La apariencia de la película no debe desmejorar en relación con la película actual.', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-06-13'),
	(164, 129, 'María Isabel: Por favor hacer la gestión de riesgos del cambio de material en la capa externa de las películas de PP', 1, '[4]', 'Se realiza Plan de Gestión de Riesgo. Ver adjunto', '4', '2017-06-13 16:42:23', 1, 0, 3, '5', '2017-06-13'),
	(165, 140, 'Diego: Por favor solicitar a Luis Eduardo que se efectúe el primer ensayo con el material 08H85-1 de propilco y me informan para cuándo se puede realizar la prueba. [////]Dado que la muestra de material que tenemos es de 25 kg, por favor usarla en su totalidad para hacer una cantidad de película representativa.[////]Si la apariencia desmejora abortar el ensayo al no cumplir con un requisito e informarme. Gracias', 1, '[3]', 'Se genera correo a Luis Eduardo con fecha 2017-06-16 con las instrucciones y codificaciones pertinentes', '3', '2017-06-16 15:40:47', 0, 0, 3, '5', '2017-06-14'),
	(166, 141, 'Fresenius Medical Care solicita, a ríaz de una auditoría llevada a cabo por su casa matriz mantener una doble bolsa en el empaque de los sitios de inyección, así como la continuidad de la identificación del producto. Aunque el amterial se empacaba en bolsas individuales de 1000 unidades, y a su vez varios de estos paquetes en una segunda bolsa debidamente identificada cumpliendo con el los requisitos, lo que finalmente ocurría cuando se dispensaba paquetes de 1000 unidades y quedaban sin dispensar paquetes, los paquetes que salían quedaban sin una identificación, y perdían la segunda bolsa de empaque.[////]También queían poder leer ellos mismos las etiquetas con un scanner, pero dado que el código de barras manejaba una información interna en Plastitec que no tenía ningún significado para ellos, pidieron la aparición de un segundo código de barras que les permitiera saber el código interno (en fresenius) del producto, así como identificación del lote en cuestión.[////]Esta sugerencia nos ha parecido útil por lo que se puede implementar para todas las etiquetas internas de todos los productos y para todos los clientes.[////]En en análisis de riesgos se verá que no se quita ninguna información contenida actalmente, y por el contrario se adiciona información que puede resultar útil para los clientes.[////]Dado que se van a fabricar dos tipos de sitios con diferente resellabilidad, se plantea que para evitar confusiones el color de la bolsa primaria para cada tipo de septum sea diferente', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-06-14'),
	(167, 142, 'Solicitar a Yamile que le pida al proveedor Infotrack el cambio en la etiqueta[////]Que Yamile verifique que las nuevas etiquetas no alteren el proceso actual de picking para la generación de la etiqueta externa. y que el código de barras adicional que se genere sea legible.[////]A logística que pida al proveedor eserplex las bolsa de color[////]Wilmer y María Isabel verificar que la bolsa de color no transfiera pigmento al producto terminado.[////]Cuando se haya verificado el correcto funcionamiento se deberá cambiar la ficha técnica cuidando el control de cambios[////]Logística deberá enviar al cliente la nueva versión de la ficha técnica', 1, '[3][7][2][4][15][16][10][9]', 'Se recibe propuesta del diseño de la etiqueta de parte del proveedor Infotrack, se verifica con Don Eduardo y se procede a aceptarla y a comenzar proceso para pruebas internas. 2017-06-21.[////][////]Se aplican cambios en ambiente productivo el día 2017-10-31, verificando la generación de etiquetas internas con doble código de barras; el personal fue divulgado previamente en los cambios.', '9', '2017-11-29 09:42:46', 0, 0, 1, '5', '2017-06-14'),
	(168, 143, 'Para que evitemos internamente la confusión de los pistones de siliprene corrientes y resistentes al pinchazo estos deberán en la zona de inyección empacarse en bolsas de color diferente.[////]Logística debe solicitar también al proveddor estas bolsas', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-06-14'),
	(169, 144, 'Eduardo Muñoz:  Dar directrices de la nueva etiqueta.[////]Luis Eduardo Rodríguez: De asegurarse que los pistones de siliprene corrientes y resistentes al pinchazo se empaquen en bolsas de diferente color, como lo indicará la ficha técnica respectiva.[////]Luis Felipe Osorio: Enviar al cliente la nueva ficha técnica que se genere cuando se entreguen los diferentes tipos de sitio. Informar a Fresenius a partir de qué fecha se identificacrán los paquetes internos con la nueva etiqueta de modo individual.[////]María Isabel Colmenares y Wilmer Hernández: Generación de las nuevas fichas, su divulgación y verificar la no migración del colorante de las bolsas al producto empacado[////]Wilson Bustos, Instruir a las empacadoras del cambio de etiqueta interna que en adelante se hará a cada paquete individual de 1000 unidades, así como el uso de los diferentes colores de las bolsas de empaque primario.[////]Yamile Tafur: Solicitar el cambio de etiqueta a Infotrack, y verificar que la nueva etiqueta siga funcionando para el picking, generación de etiqueta externa y llevar sin alteración los registros que genera infotrack. Igualmente verificar que el segundo código de barras sea legible. Preguntar a Luis Felipe los códigos internos de Fresenius que deberán a futuro aparecer en el segundo código de barras. Estos códigos serán coincidentes con el código establecido en las órdenes de compra de fresenius. [////]', 1, '[5][7][2][4][16][10][9]', 'Se hace verificación con el primer material empacado lote 7480-27E26. Tiempo de permanencia del producto 10 dias.', '4', '2017-06-22 16:26:06', 0, 0, 2, '5', '2017-06-14'),
	(170, 145, 'El producto como tal no cambia para nada por lo que no se anota nada en este punto.', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-06-14'),
	(171, 146, 'El producto como tal no cambia para nada por lo que no se anota nada en este punto.', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-06-14'),
	(172, 147, 'El uso de bolsa coloreada en azul nunca ha evidenciado transferencia del colorante a los contenidos', 0, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-06-14'),
	(173, 160, 'María Isabel:[////]Por favor hacer la actividad de gestión de riesgos para:[////]Fabricación de compuestos de siliprene corriente y resistente a pinchazo tendiente a evitar confusión en la correcta identificación del material (Color en empaque)[////]Lo mismo para la inyección de los pistones,  y piezas ensambladas.[////]Nueva etiqueta.[////]Reunir a la gente para el debate', 1, '[3][12][7][2][4][15][10][9]', NULL, NULL, NULL, 0, 0, 1, '5', '2017-06-14'),
	(174, 140, 'Luis Eduardo, [////]El proximo martes debemos extruir lo siguiente,[////]P7445  PP_TUB_CT-E4-15947_460 mmX190µ  utilizar la FT-ES-0005  E4 15947. Si funciona la apariencia utilizar los 25 kg exitentes de M1071 y asignar el codigo P 7491 para  la manga refilada PPFILM CT-E4-15947 135 mm X 190µ . Si todo funciona se colocara una nota en la FT-ES-0001 correspondiente a la E4 15948 de que el M1071 es MP equivalente de la M1010 y se integraria al I-PR-003 Tabla de MP equivalentes. [////]Una vez terminada el M1071 continuar con el M1010 hasta completar la manga necesaria para la OP 14511', 1, '[7]', 'Don Diego:[////]                   se probo el material en la capa externa según lo ordenado, la manga no presenta cambios de apariencia ni inconvenientes a la hora de la extrusión. para tener mayor información del comportamiento sugiero tener 100 kilos para trabajar la maquina por mas tiempo.[////]se logro fabricar  1 rollo padre código 7445 de 590 metros para refilar 3 rollos hijos codigo  7491 de 531 metros cada rollo para un total en metros de 1593.    [////][////]', '7', '2017-06-20 14:58:12', 1, 0, 3, '3', '2017-06-16'),
	(175, 140, 'Jaime, Wilson, procesar los 3 rollos P7491 a bolsas 100 ml P 7001 FT-DT-1248 v 9 segun OPB17-025.[////][////]Jaime reportar comportamiento de los moldes dado que  la materia prima en prueba va en la capa externa (M1071 vs M1010)', 0, '[12][10]', '', '12', '2017-10-17 14:19:05', 0, 0, 3, '3', '2017-06-17'),
	(176, 140, 'Ma. Isabel, Wilmer,[////][////]Hacer las pruebas necesarias a las bolsas P7001 E4 15947', 0, '[4][16]', 'Se realizaron todas las pruebas con resultados satisfactorios.[////]adjunto tabla e informes.', '4', '2017-06-21 16:35:09', 1, 0, 3, '3', '2017-06-17'),
	(177, 24, 'Para dar continuidad al desarrollo el Cliente coloco la PO 45009908523 por 3.000  bolsas P7184 FT-DT-1454 v 5. Proceder a la fabricación.', 0, '[10]', 'El 3 de agosto de 2017 se fabrica bolsa DRAINAGE BAG TEST X 7 LITROS OP 1758 PARA FRESENIUS NORTH AMERICA con lote:7184-27H02  ,en la linea bocas 21 . [////]cantidad:  3000 unidades.[////] Y se entregan muestras de estas  a calidad[////]', '10', '2017-08-03 12:18:30', 1, 0, 3, '3', '2017-08-02'),
	(178, 24, 'Registrar las pruebas realizadas a las bolsas P7184 segun la OP 1758.', 0, '[4][16]', 'Se realizan pruebas funcionales:[////]3 unidades Prensa por 2 horas Cumple[////]3 unidades Autoclave Cumple[////]3 unidades Hermeticidad Cumple[////]3 unidades Estallido Cumple[////]3 unidades Caída Se realizan en turno 1 Cumple  (Esta prueba no aplica sin embargo se realizó para ver el resultado).[////]3 unidades Llenado después de autoclave con 1.5 más de peso Se realizan en turno 1 Cumple  [////]3 unidades Ojal después de Autoclave Se realizan en turno 1 Cumple  [////]1 unidad para Llenado a goteo Se termina de realizar en turno 1 Cumple[////]Pruebas de ojal sin autoclave por 1 hora y media Se realizan en turno 1   Cumple[////][////]', '4', '2017-08-04 12:44:31', 1, 0, 3, '3', '2017-08-02'),
	(180, 33, 'Se envían 3000 bolsas identificadas con lote 7184-27H02. El 11 de agosto de 2017[////]se adjunta certificado de calidad CC 52620.', 1, '', NULL, NULL, NULL, 0, 0, 3, '4', '2017-08-11'),
	(181, 90, 'Se envían 110 unidades con lote 7146-26F15 formula 15921, para fresenius USA.[////]los cambios en la geometría de la pieza son:[////]Anillos en diámetro externo de conexión y reducción del diámetro a 15.5 mm  para mejorar la interferencia.[////]Se adjunta certificado de calidad y plano.', 1, '', NULL, NULL, NULL, 0, 0, 3, '4', '2017-08-29'),
	(182, 97, 'Debemos volver a hacer muestras de la bolsa de drenaje de Fresenius Reynosa.[////][////]Por favor usar la película disponible de 0.35 mm de espesor.[////][////]Las especificaciones deben ceñirse a las que se indican en la ficha que ellos enviaron y que ayer le entregué a Wilson[////][////]Son 25 unidades.[////][////]Para no perturbar la producción en colas screen por favor usar la máquina individual que está situada en el área de bolsas de nutrición parenteral para hacer el sellado de las colas.[////][////]Cuando tengan un espacio adecuar una boca para pegar los tubos.[////][////]Tan pronto estén listas la muestras enviarlas a Irving Hernández usando la cuenta FedEx de ellos Número 0785-0021-2[////]', 1, '[12][10]', 'El 13 de septiembre de 2017 se fabrica bolsa DRAIN BAG TEST W / IP 7 L FRESENIUS NORTH AMERICA [////]se utilizo[////]Manga C: 11727-27H02 P:7330-27H02-5[////][////]Ducto Interno: C:11730-27H03 P: 2705-27H03-4[////]Ducto Externo: C:11729-27H03 P: 6780-27H03-1[////][////]Ensamble: 6055-27I11[////][////]Sellado en la linea colas 6 con lote:7184-27H02 ,[////]y sellado en la linea bocas 20 . con lote 7184-27I11.[////][////]Se entregan 25 unidades aprobadas a logistica OP VSolin 1795.[////][////]Y se entregan muestras de estas a calidad ', '10', '2017-09-13 13:00:24', 1, 0, 3, '5', '2017-09-13'),
	(183, 97, 'Hacer cambio de ficha tecnica y reportar resultado de pruebas.', 1, '[4][16]', 'El 17-09-16 Se envían 25 bolsas  Lote # 7184-27I11  FT-DT-1454 v6', '4', '2017-09-16 16:13:47', 1, 0, 3, '5', '2017-09-13'),
	(184, 186, 'Diseñar una pieza que reemplace la cúpula actual para corregir los problemas reportados por el cliente fresenius andina (conector con cúpula doble, al revés, metida y sin cúpula).', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-11-09'),
	(185, 161, '1. Elaboración de planos de la nueva pieza\r\n2 Fabricación de cavidades prototipo para montarlas en molde de cúpula de PP\r\n3. Fabricación de muestras prototipo\r\n4. Estudio de funcionamiento de la pieza en máquina ensambladora de mariposa\r\n5. Estudio de funcionamiento de twist off ensamblado en la máquina Plümat\r\n6. Verificación de estanqueidad entre el nuevo tapón y el cuerpo del twist off\r\n2. Entrega de muestras al cliente.\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-11-09'),
	(186, 164, 'De la concepción del cambio en el molde: Eduardo Muñoz.', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-11-09'),
	(187, 164, 'De las modificaciones en el molde: Nestor Castillo.', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-11-09'),
	(188, 164, 'De la prueba en producción: Diego Orozco, Luis Eduardo Rodriguez, Wilson Bustos, Jaime Villegas.', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-11-09'),
	(189, 164, 'De los resultados de las pruebas: María Isabel Colmenares , Wilmer Hernandez.[////]', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-11-09'),
	(190, 162, 'Revisar el plano del prototipo frente a las primeras piezas obtenidas.[////]Revisión de especificaciones generadas para elaborar la FT.[////]Revisión de requisitos de funcionamiento y desempeño.[////] ', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-11-09'),
	(192, 165, 'Los métodos se aseguran mediante los registros de actividades o tareas generadas en el aplicativo y los registros adjuntos que describen la codificación y los lotes de las muestras.', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-11-09'),
	(193, 166, 'Recursos necesarios: [////]-Taller de mecanizado para modificación del molde cavidades prototipo.[////]-Material para pruebas.[////]-Personal involucrado.[////]-Equipos para pruebas.[////]', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-11-09'),
	(194, 167, '-Pruebas de torsión al conector ensamblado con este nuevo tapón.[////]-Pruebas para garantizar que el tapón no se suelte del conector.[////]-Probar detección de conector sin tapón en la linea de ensamble.[////]-Prueba de impermeabilidad a microorganismos despues de autoclave.[////]\r\n-Prueba dimensional de ancho de aletas.[////]', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-11-09'),
	(195, 168, 'No son necesarios requisitos adicionales ya que el tapon no entra en contacto con las soluciones.', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-11-09'),
	(196, 170, 'Se toma como base las dimensiones de la cúpula PP actual para construir las dimensiones iniciales del prototipo.', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-11-09'),
	(197, 171, 'El plano del prototipo para la verificación de las dimensiones de las muestras.', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-11-09'),
	(198, 173, 'No se requiere ya que los materiales y las cantidades son las mismas, la soldadura entre el conector y el tapon H no cambian ya que las formulaciones son iguales. ', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-11-09'),
	(199, 174, 'Torsión  menor  o igual a  50 Ncm.[////]el tapón no debe salirse del conector al aplicarle una presión de 2 Bar.[////]cumplir con las dimensiones de la FT .[////]El peso de la pieza debe ser equivalente con la cúpula actual.[////]El tapón no debe quedar undido.[////][////][////]', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-11-09'),
	(200, 175, 'Las características de uso son las mismas. ', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-11-09'),
	(201, 19, 'Se adjunta documentación de calificación y FTP-I-001', 0, '', NULL, NULL, NULL, 0, 0, 3, '8', '2016-04-19'),
	(202, 169, 'Se realiza plan de riesgos para esta nueva pieza.', 1, '', NULL, NULL, NULL, 0, 0, 3, '4', '2017-11-09'),
	(203, 185, 'Elaborar plano para prototipo tapon H.', 1, '[8]', 'Plano Tapón H CB-178.1', '8', '2018-01-11 10:25:23', 1, 1, 3, '5', '2017-11-09'),
	(204, 185, 'Programar la fabricación de 500 unidades de tapon en H.', 1, '[3]', 'Se programa la fabricación de 500 unidades para verificacion y  prueba en la ensambladora.', '3', '2018-02-06 14:48:26', 1, 0, 3, '5', '2017-11-09'),
	(205, 185, 'Revisar dimensiones frente al plano y realizar pruebas funcionales.', 1, '[4][16]', 'Se realizan pruebas preliminares a las muestras entregadas.[////]ver informe adjunto.', '16', '2017-12-01 16:37:05', 1, 0, 3, '5', '2017-11-09'),
	(206, 185, 'verificar la atura ideal de la pieza en funcion de la torsion requerida para romper el twist off.', 1, '[4][16]', 'Se realizan las pruebas a diferentes alturas definiendo la altura ideal con 1.5 mm menos.[////][////]Se adjunta informe de pruebas preliminares realizadas y con las 5 cavidades ya recortadas.', '16', '2017-12-01 18:00:09', 1, 0, 3, '5', '2017-11-09'),
	(207, 185, 'Verificar funcionamiento de la ensambladora con el nuevo tapon H.', 1, '[12][10]', 'se realizan pruebas preliminares con tapones H en la maquina ensambladora de mariposas 4, encontrando que se desplazan bien por las tolvas circulares y lineales, a pesar de no tener la suficiente cantidad de tapones para la prueba. se ajusta desplazamiento del cilindro de inserción y no se observa falla por doble tapón ensamblado o mariposas sin tapón H, pendiente realizar una prueba con una cantidad mayor de tapones para poder determinar el trabajo de la maquina en ciclo continuo.', '12', '2017-11-28 15:20:55', 0, 0, 3, '5', '2017-11-09'),
	(208, 185, 'Construir las cavidades de acuerdo a la altura optima sobre el molde de cúpula PP 2.', 1, '[8]', 'El 2018-01-10 se realiza montaje de 5 cavidades prototipo para prueba de retenciones M-160[////]El 2018-01-22 Se realiza montaje con 20 cavidades de Tapón H y 20 con cúpula, el molde no se puede trabajar en automático porque se quedan algunas cúpulas en el lado fijo.[////]El 2018-01-24 se finaliza fabricación del molde y se realiza montaje', '8', '2018-01-24 14:32:30', 1, 0, 3, '5', '2017-11-09'),
	(209, 185, 'Verificar las 40 cavidades ya con la altura definida en el nuevo molde.', 1, '[4][16]', 'Se verifican las 40 cavidades del molde M-160 y cumplen con las especificaciones del plano CB-178.1.0.[////]Se realizan pruebas de estanqueidad, torsión del twist off con el tapón H y  retención del tapón en el conector, con resultados satisfactorios.[////]Ver archivos adjuntos.', '16', '2018-02-06 14:34:50', 1, 0, 3, '5', '2017-11-09'),
	(210, 176, 'con la experiencoa que existe podemos verificar el funcioanmiento en la ensambladora y la maquina plumat para determinar la correcta hermeticidad del ensamble.', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-11-09'),
	(211, 177, 'estan listadas en la sección de actividades del proyecto.', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-11-09'),
	(212, 178, 'la verificación se encuentra en las respuestas de cada una de las actividades del proyecto.', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-11-09'),
	(213, 37, 'Se env&iacute;an a  Fresenius Medical Care North America, Para VALIDACION&nbsp; identificadas con los siguientes lotes y cantidades:[////]7184-27L05 : 1000 bolsas[////]7184-27L06 :  1000 bolsas[////]7184-27L07:   1000 bolsas[////][////][////] \r\n', 0, '', NULL, NULL, NULL, 0, 0, 3, '4', '2018-01-10'),
