	(321, 316, '<div>\r\nRetroalimentacion del cliente sobre uso de puerto de insercion ( spike port)\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<div>\r\n<a href="UserFiles/File/0001-1/001-1/001-1/SOLICITUD%20PRUEBAS%20CON%20SPIKE%20PORT.docx" target="_blank">INFORME CLIENTE&nbsp;</a> \r\n</div>\r\n<div>\r\n<p class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<br />\r\n</div>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2020-03-01'),
	(322, 292, '<p style="line-height: normal; background: #eeeeee" class="MsoNormal">\r\nLAS ETAPAS DE ESTE DISE&Ntilde;O SER&Aacute;N:\r\n</p>\r\n<p style="line-height: normal; background: #eeeeee" class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<ul>\r\n	<li>Elaboraci&oacute;n planos de la nueva&nbsp; Pieza</li>\r\n	<li>Fabricaci&oacute;n de cavidades prototipo</li>\r\n	<li>Fabricaci&oacute;n muestras prototipo</li>\r\n	<li>Verificaci&oacute;n pruebas funcionales y dimensionales.</li>\r\n	<li>Verificaci&oacute;n capacidad de esterilizaci&oacute;n de la membrana (air vent)</li>\r\n	<li>Prueba de perforaci&oacute;n con equipo de infusi&oacute;n usado por el cliente</li>\r\n</ul>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<p style="line-height: normal; background: #eeeeee" class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<p style="line-height: normal; background: #eeeeee" class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<p style="line-height: normal; background: #eeeeee" class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<p style="line-height: normal; background: #eeeeee" class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<p style="line-height: normal; background: #eeeeee" class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2018-06-11'),
	(323, 293, '<div>\r\nLAS REVISIONES NECESARIAS PARA EL PROYECTO, SON:\r\n</div>\r\n<div>\r\n<ul>\r\n	<li>Revisi&oacute;n de Piezas prototipo frente al&nbsp; Plano&nbsp;</li>\r\n	<li>Revisi&oacute;n de especificaciones para generaci&oacute;n de Ficha T&eacute;cnica</li>\r\n	<li>Revisi&oacute;n de requisitos de funcionamiento y desempe&ntilde;o.</li>\r\n</ul>\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<p class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2018-06-11'),
	(324, 294, '<p>\r\nLAS ACTIVIDADES DE VERIFICACI&Oacute;N, VALIDACI&Oacute;N Y TRANSFERENCIA APROPIADAS EN CADA ETAPA, SON:\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<ul>\r\n	<li>&nbsp;Verificar cumplimiento de especificaciones de la ficha t&eacute;cnica</li>\r\n	<li>&nbsp;Verificar cumplimiento de pruebas establecidas en el I-GC-006</li>\r\n	<li>&nbsp;Validaci&oacute;n mediante env&iacute;o de muestras prototipo al cliente</li>\r\n	<li>Transferir ficha t&eacute;cnica, Instructivo de control, actualizaci&oacute;n de tara y unidades de empaque.</li>\r\n</ul>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2018-06-11'),
	(325, 295, '<div>\r\nLAS RESPONSABILIDADES ASIGNADAS A ESTE PROYECTO, SON:\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<div>\r\n<ul>\r\n	<li>Interacci&oacute;n con el cliente:&nbsp; Luis Felipe Osorio</li>\r\n	<li>Modificaciones del molde y generaci&oacute;n Plano Componente b&aacute;sico y ensamble: Nestor Castillo</li>\r\n	<li>Coordinaci&oacute;n pruebas de producci&oacute;n: Diego Orozco</li>\r\n	<li>Fabricaci&oacute;n de piezas inyectadas: Luis Eduardo Rodriguez</li>\r\n	<li>Ensamble de piezas inyectadas: Wilson Bustos.</li>\r\n	<li>Generaci&oacute;n de&nbsp; Ficha t&eacute;cnica de producto: Ma. Isabel Colmenares.</li>\r\n	<li>Verificaci&oacute;n y validaci&oacute;n del producto: Ma. Isabel Colmenares - Wilmer Hernandez.&nbsp;</li>\r\n	<li>Transferencia del Dise&ntilde;o: Ma. Isabel Colmenares</li>\r\n</ul>\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<p style="line-height: normal; background: #eeeeee" class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2018-06-11'),
	(326, 296, '<div>\r\nLOS M&Eacute;TODOS QUE ASEGURAN LA TRAZABILIDAD DE LAS SALIDAS DEL DISE&Ntilde;O A LAS ENTRADAS DEL DISE&Ntilde;O, SON:\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<div>\r\n<ul>\r\n	<li>Registro y seguimiento de actividades en Aplicativo reuniones:&nbsp;<a href="../Reunion/Inicio.jsp">http://172.16.2.117:8084/Reunion/Inicio.jsp</a></li>\r\n	<li>Registro de actividades del Proyecto en D&amp;D:&nbsp;<a href="Proyecto.jsp">http://172.16.2.117:8084/Diseno_desarrollo/Proyecto.jsp</a></li>\r\n	<li>Correos</li>\r\n	<li>Certificados de calidad de muestras enviadas&nbsp;</li>\r\n</ul>\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<div>\r\n<br />\r\n</div>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2018-06-11'),
	(327, 297, '<p>\r\nLOS RECURSOS USADOS, SER&Aacute;N:\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<ul>\r\n	<li>Taller de mecanizado&nbsp; para&nbsp; modificaci&oacute;n del molde.</li>\r\n	<li>Materiales para prueba</li>\r\n	<li>Personal involucrado</li>\r\n	<li>Equipos de prueba</li>\r\n</ul>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<p style="line-height: normal; background: #eeeeee" class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2018-06-11'),
	(328, 298, '<p>\r\nLOS REQUISITOS, SON:\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<ol>\r\n	<li>&nbsp;DESEMPE&Ntilde;O: Cumplir&nbsp; 1.1&nbsp; Prueba de integridad de membrana (estanqueidad) a 129 &deg;C&nbsp; Y&nbsp; 1.2&nbsp; &nbsp;Prueba de Integridad de twist off a 129 &deg;C.</li>\r\n	<li>USABILIDAD: Cumplir prueba de torsi&oacute;n.</li>\r\n	<li>SEGURIDAD DE ACUERDO CON EL USO PREVISTO: 3.1 Pruebas dimensionales seg&uacute;n ficha t&eacute;cnica FT-E-0299 3.2 An&aacute;lisis F&iacute;sico Qu&iacute;mico del material Seg&uacute;n Farmacopea Europea capitulo 3.1.14</li>\r\n</ol>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<p style="margin-left: 0cm" class="MTemaNormal" align="left">\r\n&nbsp;\r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2018-06-11'),
	(329, 299, '<p>\r\nEL MATERIAL DE LA FORMULA DEBE SER PL&Aacute;STICO CLASE VI:<br />\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<ul>\r\n	<li>Class VI USP	USP 40 NF35, 2017. &lt;88&gt;</li>\r\n</ul>\r\n&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Biological Reactivity Test, In Vivo.	<br />\r\n&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\r\n<p>\r\n&nbsp;\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<ul>\r\n	<li>USP Physicochemical Test for Plastics	USP 40 NF 35, 2017. &lt;661&gt; Tests</li>\r\n</ul>\r\n&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; on Plastic Materials and Components used to package Medical Articles	<br />\r\n<br />\r\n<p>\r\n&nbsp;\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2018-06-11'),
	(330, 301, '<p>\r\nSE TOMA COMO BASE LAS DIMENSIONES DEL CONECTOR TRANSFERIDO POR&nbsp; FRESENIUS USA\r\n</p>\r\n<table border="0" cellspacing="0" cellpadding="0">\r\n	<tbody>\r\n		<tr height="18" style="height: 13.5pt">\r\n			<td class="xl65" width="47" height="18" style="height: 13.5pt; width: 35pt">3.1</td>\r\n			<td class="xl73" colspan="2" width="269" style="border-left: none; width: 202pt">Ancho\r\n			aletas/Wings Widht</td>\r\n			<td class="xl66" width="47" style="border-left: none; width: 35pt">X1</td>\r\n			<td class="xl71" width="108" style="border-left: none; width: 81pt">24.5+/-0.5</td>\r\n		</tr>\r\n		<tr height="17" style="height: 12.75pt">\r\n			<td class="xl67" height="17" style="height: 12.75pt; border-top: none">3.2</td>\r\n			<td class="xl72" colspan="2" style="border-left: none">Di&aacute;metro Externo\r\n			tap&oacute;n/External Cap Diameter</td>\r\n			<td class="xl68" style="border-top: none; border-left: none">X2</td>\r\n			<td class="xl69" style="border-top: none; border-left: none">8.3+/-0.2</td>\r\n		</tr>\r\n		<tr height="17" style="height: 12.75pt">\r\n			<td class="xl67" height="17" style="height: 12.75pt; border-top: none">3.3</td>\r\n			<td class="xl72" colspan="2" style="border-left: none">Di&aacute;metro Interno de\r\n			conexi&oacute;n/Connection Diameter</td>\r\n			<td class="xl69" style="border-top: none; border-left: none">X3</td>\r\n			<td class="xl70" style="border-top: none; border-left: none">5.2+/-0.2</td>\r\n		</tr>\r\n		<tr height="17" style="height: 12.75pt">\r\n			<td class="xl67" height="17" style="height: 12.75pt; border-top: none">3.4</td>\r\n			<td class="xl72" colspan="2" style="border-left: none">Diametro Externo de\r\n			conexi&oacute;n/External lower Diameter</td>\r\n			<td class="xl69" style="border-top: none; border-left: none">X4</td>\r\n			<td class="xl69" style="border-top: none; border-left: none">7,0+/-0,2</td>\r\n		</tr>\r\n		<tr height="17" style="height: 12.75pt">\r\n			<td class="xl67" height="17" sty