	(331, 302, '<div>\r\nREQUISITOS ESENCIALES:\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<div>\r\n<ul>\r\n	<li>El plano del prototipo para la verificaci&oacute;n dimensional&nbsp;</li>\r\n	<li>Ficha t&eacute;cnica del producto.</li>\r\n	<li>Cumplir pruebas de estanqueidad descritas en I-GC-006.</li>\r\n</ul>\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<p style="background: #eeeeee">\r\n&nbsp;\r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2018-06-11'),
	(332, 303, '<p>\r\nLAS SALIDAS CUMPLIERON CON LOS REQUISITOS DE ENTRADA DEL DISE&Ntilde;O:\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<ul>\r\n	<li>Especificaciones del plano y la Ficha t&eacute;cnica FT-E-0299V0 : Cumplieron VER Certificado de Calidad&nbsp;<a href="UserFiles/File/0001-1/001-1/001-1/CC%207716-28F27.pdf" target="_blank">No. 57350</a> </li>\r\n	<li>Pruebas de desempe&ntilde;o: Cumplieron.&nbsp;<a href="UserFiles/File/0001-1/001-1/001-1/R-GC-139 V3 2018-07-18 DIMENSIONAL.xls" target="_blank">Ver informe</a> </li>\r\n	<li>Pruebas de Usabilidad:&nbsp;<a href="UserFiles/File/0001-1/001-1/001-1/torque.xlsx" target="_blank">Cumplieron</a> </li>\r\n	<li>Seguridad de acuerdo con el uso previsto: Cumplieron.&nbsp;<a href="UserFiles/File/0001-1/001-1/001-1/Specifications F17200 V5.pdf" target="_blank">Ver informe</a> &nbsp;Toxikon Project No. 18-00187-N6 para plastico Clase VI y Toxikon Project No. TE180034/18-B0110</li>\r\n</ul>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2018-07-19'),
