	(334, 316, '<p>\r\nSE CAMBIA MATERIAL DE EMPAQUE Y VERSI&Oacute;N DE LA FICHA T&Eacute;CNICA FT-E-0299 V1. CAMBIA CAJA No.&nbsp; 11 A No. 3 Y NUMERO DE UNIDADES POR CAJA DE 9000 A 7000 UNIDADES POR MALTRATO DURANTE TRANSPORTE.\r\n</p>\r\n<p>\r\nSE ENV&Iacute;AN 5 LOTES PARA EVALUACI&Oacute;N DEL CAMBIO.\r\n</p>\r\n<p class="MsoNormal">\r\n<span style="font-size: 10pt; line-height: 115%; font-family: Arial, sans-serif">7716-28H22:&nbsp; 9000 UDS</span>\r\n</p>\r\n<p class="MsoNormal">\r\n<span style="font-size: 10pt; line-height: 115%; font-family: Arial, sans-serif">7716-28H23:&nbsp; 9000 UDS</span>\r\n</p>\r\n<p class="MsoNormal">\r\n<span style="font-size: 10pt; line-height: 115%; font-family: Arial, sans-serif">7716-28H24:&nbsp; 9000 UDS</span>\r\n</p>\r\n<p class="MsoNormal">\r\n<span style="font-size: 10pt; line-height: 115%; font-family: Arial, sans-serif">7716-28H25:&nbsp; 9000 UDS</span>\r\n</p>\r\n<p>\r\n<span style="font-family: Arial, sans-serif; font-size: 10pt">7716-28H27:</span>&nbsp; <font size="2">27000 UDS</font>\r\n</p>\r\n<p>\r\n&nbsp;<a href="UserFiles/File/0001-1/001-1/001-1/CERTIFICADOS DE CALIDAD.pdf" target="_blank">CERTIFICADOS&nbsp;</a> \r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2018-09-11'),
