	(370, 298, '<div>\r\n<br />\r\n</div>\r\n<div>\r\n<p style="color: #006699; font-family: &quot;Segoe UI&quot;; font-size: 9px; text-transform: uppercase; background-color: #eeeeee">\r\nPOR SOLICITUD DEL CLIENTE se necesita garantizar la integridad de la membrana sin exceder el grosor de 0.4 MM ,GARANTIZANDO LA ELIMINACI&Oacute;N DE FUGAS DEBIDO A LA POSIBLE RETENCI&Oacute;N DE EXCESO DE AIRE Y/O MATERIAL (BOLSAS DE AIRE).\r\n</p>\r\n<p style="color: #006699; font-family: &quot;Segoe UI&quot;; font-size: 9px; text-transform: uppercase; background-color: #eeeeee">\r\n<a href="UserFiles/File/0001-1/001-1/2020-06-15 Spike Port Observations Summary.pdf" target="_blank">VER INFORME</a>\r\n</p>\r\n<p style="color: #006699; font-family: &quot;Segoe UI&quot;; font-size: 9px; text-transform: uppercase; background-color: #eeeeee">\r\n&nbsp;\r\n</p>\r\n<p style="color: #006699; font-family: &quot;Segoe UI&quot;; font-size: 9px; text-transform: uppercase; background-color: #eeeeee">\r\n<strong>&nbsp;rEQUISITO:</strong>\r\n</p>\r\n<p style="color: #006699; font-family: &quot;Segoe UI&quot;; font-size: 9px; text-transform: uppercase; background-color: #eeeeee">\r\n&nbsp;CUMPLIMIENTO DE PRUEBAS FUNCIONALES.\r\n</p>\r\n<p style="color: #006699; font-family: &quot;Segoe UI&quot;; font-size: 9px; text-transform: uppercase; background-color: #eeeeee">\r\n&nbsp;\r\n</p>\r\n</div>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '4', '2020-06-16'),
