	(385, 318, '<div>\r\n<br />\r\n</div>\r\n<div>\r\n&nbsp;las etapas establecidas para este cambio en el D&amp;D, son:\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<ul>\r\n	<li class="MsoNormal" style="color: #34495e; line-height: normal; background: #eeeeee"><span style="font-size: 7pt">ELABORACI&Oacute;N PLANOS DE LA NUEVA&nbsp; PIEZA</span></li>\r\n	<li class="MsoNormal" style="color: #34495e; line-height: normal; background: #eeeeee"><span style="font-size: 7pt">FABRICACI&Oacute;N DE CAVIDADES PROTOTIPO</span></li>\r\n	<li class="MsoNormal" style="color: #34495e; line-height: normal; background: #eeeeee"><span style="font-size: 7pt">FABRICACI&Oacute;N Y ENTREGA DE&nbsp; MUESTRAS PROTOTIPO</span></li>\r\n	<li class="MsoNormal" style="color: #34495e; line-height: normal; background: #eeeeee"><span style="font-size: 7pt">VERIFICACI&Oacute;N PRUEBAS FUNCIONALES Y\r\n	DIMENSIONALES.</span></li>\r\n	<li class="MsoNormal" style="color: #34495e; line-height: normal; background: #eeeeee"><span style="font-size: 7pt">FABRICACION MOLDE FINAL</span></li>\r\n	<li class="MsoNormal" style="color: #34495e; line-height: normal; background: #eeeeee"><span style="font-size: 7pt">FABRICACION PRE SERIE</span></li>\r\n	<li class="MsoNormal" style="color: #34495e; line-height: normal; background: #eeeeee"><span style="font-size: 7pt">REVISON EMPAQUE Y EMBALAJE.</span></li>\r\n</ul>\r\n<div>\r\n&nbsp;&nbsp;\r\n</div>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2020-03-20'),
	(386, 319, '<p class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<p style="margin-bottom: 0.0001pt; line-height: normal; background: #eeeeee" class="MsoNormal">\r\n<span style="font-size: 7pt; font-family: &quot;Segoe UI&quot;, sans-serif; color: #34495e; text-transform: uppercase">LAS REVISIONES NECESARIAS PARA EL PROYECTO, SON:</span>\r\n</p>\r\n<ul>\r\n	<li class="MsoNormal" style="color: #34495e; line-height: normal; background: #eeeeee"><span style="font-size: 7pt; font-family: &quot;Segoe UI&quot;, sans-serif; text-transform: uppercase">REVISI&Oacute;N DE PIEZAS PROTOTIPO FRENTE AL&nbsp;\r\n	PLANO&nbsp;</span></li>\r\n	<li class="MsoNormal" style="color: #34495e; line-height: normal; background: #eeeeee"><span style="font-size: 7pt; font-family: &quot;Segoe UI&quot;, sans-serif; text-transform: uppercase">REVISI&Oacute;N DE ESPECIFICACIONES PARA GENERACI&Oacute;N\r\n	DE FICHA T&Eacute;CNICA</span></li>\r\n	<li class="MsoNormal" style="color: #34495e; line-height: normal; background: #eeeeee"><span style="font-size: 7pt; font-family: &quot;Segoe UI&quot;, sans-serif; text-transform: uppercase">REVISI&Oacute;N DE REQUISITOS DE FUNCIONAMIENTO Y\r\n	DESEMPE&Ntilde;O.</span></li>\r\n</ul>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2020-03-20'),
	(387, 320, '<p style="line-height: normal; background: #eeeeee" class="MsoNormal">\r\n<span style="font-size: 7pt">LAS ACTIVIDADES DE\r\nVERIFICACI&Oacute;N, VALIDACI&Oacute;N Y TRANSFERENCIA APROPIADAS EN CADA ETAPA, SON:</span>\r\n</p>\r\n<p style="line-height: normal; background: #eeeeee" class="MsoNormal">\r\n<span style="font-size: 7pt">&nbsp;</span>\r\n</p>\r\n<ul>\r\n	<li class="MsoNormal" style="color: #34495e; line-height: normal; background: #eeeeee"><span style="font-size: 7pt">&nbsp;VERIFICAR CUMPLIMIENTO DE\r\n	ESPECIFICACIONES DE LA FICHA T&Eacute;CNICA</span></li>\r\n	<li class="MsoNormal" style="color: #34495e; line-height: normal; background: #eeeeee"><span style="font-size: 7pt">&nbsp;VERIFICAR CUMPLIMIENTO DE PRUEBAS\r\n	ESTABLECIDAS EN EL I-GC-033</span></li>\r\n	<li class="MsoNormal" style="color: #34495e; line-height: normal; background: #eeeeee"><span style="font-size: 7pt">VERIFICAR&nbsp; PERMEABILIDAD DE MICROORGANISMOS ENTRE&nbsp; EL NUEVO ENSAMBLE Y LA BOLSA DE PVC Y PP</span></li>\r\n	<li class="MsoNormal" style="color: #34495e; line-height: normal; background: #eeeeee"><span style="font-size: 7pt">VERIFICAR ADHERENCIA DEL VIAL CON EL DUCTO.</span></li>\r\n	<li class="MsoNormal" style="color: #34495e; line-height: normal; background: #eeeeee"><span style="font-size: 7pt">VALIDAR MEDIANTE ENV&Iacute;O DE MUESTRAS PROTOTIPO AL CLIENTE</span></li>\r\n	<li class="MsoNormal" style="color: #34495e; line-height: normal; background: #eeeeee"><span style="font-size: 7pt">VALIDAR&nbsp; MOLDES&nbsp; DE COMPONENTES&nbsp; &nbsp;IQ,OQ Y PQ .&nbsp;</span></li>\r\n	<li class="MsoNormal" style="color: #34495e; line-height: normal; background: #eeeeee"><span style="font-size: 7pt">TRANSFERIR FICHA T&Eacute;CNICA, INSTRUCTIVO DE\r\n	CONTROL, ACTUALIZACI&Oacute;N DE TARA Y UNIDADES DE EMPAQUE. TANTO EN INYECCION COMO EN FARMACEUTICO Y&nbsp;</span>ENTRENAMIENTO DEL PERSONAL</li>\r\n</ul>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2020-03-20'),
