	(397, 342, '<p>\r\nSE ENVIAN 200 MUESTRAS AL CLIENTE IDENTIFICADAS CON EL LOTE 8213-30C21\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<p>\r\n<a href="UserFiles/File/0003-1/0003-1/8213-30C21.pdf" target="_blank">CERTIFICADO DE CALIDAD No.66831</a> \r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '4', '2020-07-16'),
	(398, 330, '<p>\r\nSE SUMINISTRA LA INFORMACION APROPIADA PARA LA PRODUCCION Y EL CONTROL DE LA MISMA.\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<p>\r\n<a href="UserFiles/File/0003-1/0003-1/CB-123.4.0 Conector V_Mod.pdf" target="_blank">PLANO CONECTOR VIAL</a> \r\n</p>\r\n<p>\r\n<a href="UserFiles/File/0003-1/0003-1/CB-192 1 0 Frangible Luer V.pdf" target="_blank">PLANO FRANGIBLE</a> \r\n</p>\r\n<p>\r\n<a href="UserFiles/File/0003-1/0003-1/8213 V0.pdf" target="_blank">FICHA TECNICA CONJUNTO&nbsp;</a> \r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '4', '2020-07-17'),
