	(435, 378, '<p>\r\nSE REALIZA PLAN DE RIESGOS PARA ESTA NUEVA PIEZA.\r\n</p>\r\n<p>\r\n<a href="UserFiles/File/0013/0013/R-GC_V3_GESTION DE RIESGOS FRANGIBLE JP (INICIAL).pdf" target="_blank">PLAN DE RESIGOS INICIAL 2022&nbsp;</a> \r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '17', '2022-03-25'),
	(436, 379, 'SE TOMA COMO BASE EL COMPONENTE BASICO FRANGIBLE Y LA PIEZA OBTENIDO DEL CLIENTE PARA DEFINIR LONGITUD DEL DUCTO DE LA BOLSA.\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '17', '2022-03-25'),
	(437, 380, 'LEVANTA PLANO DE LA PIEZA ENTREGADA POR EL CLIENTE CUYAS DIMENSIONES SON PROBADAS Y VALIDADAS POR EL MERCADO\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '17', '2022-03-25'),
	(438, 381, 'RESULTADOS PRUEBAS DIMENSIONALES Y DE ESTANQUEIDAD&nbsp;\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '17', '2022-03-25'),
	(439, 382, '<p>\r\nNO SE REQUIEREN MATERIALES ADICONALES A LOS YA EXISTENES.\r\n</p>\r\n<p>\r\nFRANGIBLE LUER UTILIZA EL MISMO POLICARBONATO QUE LAS OTRAS REFERENCIAS DE FRANGIBLE&nbsp;&nbsp;\r\n</p>\r\n<p>\r\nBOLSA ES PVC YA VALIDADA Y EN FABRICACION PARA EL CLIENTE\r\n</p>\r\n<p>\r\nTAPA UTILIZA POLIPROPILENO QUE SE UTILIZA PARA OTROS PRODUCTOS&nbsp;\r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '17', '2022-03-25'),
	(440, 383, '<table border="0">\r\n	<tbody>\r\n		<tr>\r\n			<td colspan="2" style="padding: 2px 5px 5px 2px; border-color: rgb(52, 73, 94) rgb(238, 238, 238) rgb(238, 238, 238) rgb(52, 73, 94); font-size: 9px; border-right-width: 1px; border-right-style: solid; border-bottom-width: 1px; border-bottom-style: solid"><br />\r\n			<br />\r\n			<p style="color: #006699">\r\n			-LAS DIMENSIONES DEBEN SER ACORDE A LA FICHA TECNICA\r\n			</p>\r\n			<p style="color: #006699">\r\n			-SE DEBE CUMPLIR LA PRUEBA DE ESTANQUEIDAD, NO PASO DE AIRE AL APLICAR 0.2 BAR DE PRESION\r\n			</p>\r\n			<p style="color: #006699">\r\n			-EL FRANGIBLE DEBE SER DE QUIEBRE SUAVE Y LA LANCETA DEBE QUEDAR TRABADA EN EL DUCTO\r\n			</p>\r\n			<p style="color: #006699">\r\n			-LOS ACCEOSORIOS, FRANGIBLE LUER + TAPA EN UN DUCTO Y EL ENSAMBLE DEL SEGUNDO DUCTO DEBEN ESTAR ALINEADOS\r\n			</p>\r\n			<p style="color: #006699">\r\n			&nbsp;\r\n			</p>\r\n			<div>\r\n			<br />\r\n			</div>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '17', '2022-03-25'),
	(441, 384, '<p>\r\nLAS CARACTERISTICAS ESENCIALES DEL PRODUCTO ESTAN DETALLADAS EN LOS PLANOS CB-214 PARA EL FRANGIBLE LUER Y CB-213 PARA LA TAPA, FICHA TECNICA DE ENSAMBLE FT-E-0391 V0 Y FICHA TECNICA DE PRODUCTO FINAL FT-DT-1871V V3\r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '17', '2022-03-25'),
	(442, 385, 'CON LA EXPERIENCIA QUE EXISTE PODEMOS VERIFICAR EL CORRECTO ENSAMBLE DEL CONJUNTO FRANILE LUER+TAPA Y SUS RESPECTIVAS PRUEBAS DE CALIDAD, RESALTANDO PRINICPALMENTE LA ESTANQUEIDAD Y EL QUIEBRE DEL FRANGIBLE\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '17', '2022-03-25'),
	(443, 386, 'ESTAN LISTADAS EN LA SECCION DE ACTIVIDADES DEL PROYECTO.\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '17', '2022-03-25'),
	(444, 387, '<p>\r\nLA VERIFICACION SE ENCUENTRA EN LAS RESPUESTAS DE CADA UNA DE LAS ACTIVIDADES DEL PROYECTO.\r\n</p>\r\n<p>\r\n<a href="UserFiles/File/0013/0013/VERIFICACION DEL DYD R-GC-185.pdf" target="_blank">&nbsp;INFORME DE VERIFICACION.&nbsp;</a> \r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '17', '2023-09-19'),
	(445, 388, '<a href="UserFiles/File/0013/0013/VALIDACION DEL DYD R-GC-186.pdf" target="_blank">INFORME DE VALIDACION.</a> \r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '17', '2023-09-19'),
	(446, 388, '<a href="UserFiles/File/0013/0013/VALIDACION DEL DYD R-GC-186.pdf" target="_blank">INFORME DE VALIDACION.</a> \r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '17', '2023-09-19'),
	(447, 389, '<a href="UserFiles/File/0013/0013/TRANSFERENCIA  DYD R-GC-167.pdf" target="_blank">INFORME DE TRANSFERENCIA.</a> \r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '17', '2023-09-19'),
	(448, 388, '<a href="UserFiles/File/0013/0013/INFORME_DE_CALIFICACION_FRANGIBLE_LUER.pdf" target="_blank">INFORME DE CALIFICACION</a> \r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '17', '2023-10-03'),
	(450, 378, '<p>\r\nSE REALIZA GESTION DEL PLAN DE RIESGO.\r\n</p>\r\n<p>\r\n<a href="UserFiles/File/0013/0013/R-GC-096_V3_GESTION_DE_RIESGOS FRANGIBLE JP 2023.pdf" target="_blank">PLAN DE RIESGO 2023&nbsp;</a> \r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '17', '2023-03-24'),
	(451, 352, '<a href="UserFiles/File/0011/GESTION_DE_RIESGOS_SITIOS_DE_INYECCION_PP.pdf" target="_blank">PLAN GESTION DEL RIESGO.</a> \r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '17', '2021-09-29'),
	(452, 352, '<a href="UserFiles/File/0011/GESTION_DE_RIESGOS_SITIOS_DE_INYECCION_EN_PP_2024.pdf" target="_blank">GESTION PLAN DE RIESGO 2024</a> \r\n', 1, '', NULL, NULL, NULL, 0, 0, 3, '17', '2024-04-05'),
	(453, 368, 'Proyecto queda en &quot;stand by&quot; dada la prioridad de otros proyectos, la modificaci&oacute;n de las grafadoras y el estado de ordenes del cliente Beker entre otros.\r\n', 0, '', NULL, NULL, NULL, 0, 0, 3, '17', '2021-12-12'),
	(454, 368, 'SE REACTIVA EL PROYECTO DE SITIO DE INYECCION EN PP DADO EL STATUS DE ORDENES, AUMENTO DE INTERES POR PARTE DEL MERCADO Y AVANCE DE LAS GRAFADORAS.\r\n', 0, '', NULL, NULL, NULL, 0, 0, 3, '17', '2024-03-15'),
	(455, 374, '<p class="MsoNoSpacing">\r\nINTERACCI&Oacute;N CON EL CLIENTE:&nbsp; LUIS FELIPE OSORIO\r\n</p>\r\n<p class="MsoNoSpacing">\r\nDE LA GENERACION DE PLANOS DE LA MUESTRA DEL CLIENTE:\r\nNESTOR CASTILLO\r\n</p>\r\n<p class="MsoNoSpacing">\r\nDE LA FABRICACION DEL MOLDE: PROVEEDOR EXTERNO VIA EDUARDO\r\nMU&Ntilde;OZ\r\n</p>\r\n<p class="MsoNoSpacing">\r\nDE LA VERIFICACION DE LOS PLANOS DEL MOLDE: NESTOR\r\nCASTILLO \r\n</p>\r\n<p class="MsoNoSpacing">\r\nGENERACI&Oacute;N DE FICHA T&Eacute;CNICA DE PRODUCTO: MARIA ISABEL\r\nCOLMENARES\r\n</p>\r\n<p class="MsoNoSpacing">\r\nCOORDINACI&Oacute;N PRUEBAS DE PRODUCCI&Oacute;N: RODRIGO PE&Ntilde;A\r\n</p>\r\n<p class="MsoNoSpacing">\r\nFABRICACI&Oacute;N DE PIEZAS INYECTADAS: ANDREA CASTIBLANCO\r\n</p>\r\n<p class="MsoNoSpacing">\r\nENSAMBLE DE PIEZAS INYECTADAS: WILSON BUSTOS \r\n</p>\r\n<p class="MsoNoSpacing">\r\nVERIFICACI&Oacute;N Y VALIDACI&Oacute;N DEL PRODUCTO: MARIA ISABEL\r\nCOLMENARES, WILMER HERNANDEZ\r\n</p>\r\n<p class="MsoNoSpacing">\r\nTRANSFERENCIA DEL DISE&Ntilde;O: MARIA ISABEL COLMENARES\r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, 1, '17', '2022-03-22'),
	(463, 163, 'Verificar cumplimiento de las especificaciones de la FT.[////]Verificar pruebas de funcionalidad y usabilidad.[////]Verificar ensamble del tapón al  conector.(detección de conector sin tapón)[////]Validación frente al envío de muestras al cliente.[////]Transferencia hacia la producción :[////]Revisión de taras y correspondencia entre la FT aprobada y las muestras para entrega a producción.', 1, '', NULL, NULL, NULL, 0, 0, 3, '5', '2017-11-09'),
