INSERT INTO `memoria_d_log` (`id_memoria_d_log`, `fk_memoria_d`, `tipo_log`, `fch_registro`, `usu_registro`, `fk_memoria_c`, `memoria`, `correo_actividad`, `autoridad`, `respuesta`, `usu_respuesta`, `fch_respuesta`, `correo_respuesta`, `correo_autor`, `fecha_registro`, `estado`) VALUES
	(1, 28, 'AUTOR', '2016-02-04', '5', 24, 'CUMPLIR CON LAS PRUEBAS FUNCIONALES DESCRITAS EN LA FICHA TECNICA Y REALIZAR PRUEBA DE LLENADO POR GOTEO ( BOLSAS A ESTUFA 54 °C DURANTE 1 HORA).\r\n', 0, '', NULL, NULL, NULL, 0, 0, '2016-02-05 22:07:31', NULL),
	(2, 30, 'AUTOR', '2016-02-05', '5', 25, 'ENVIAR PRUEBAS DE FORMULA 11727 A LABORATORIO TECMOL PARA CUMPLIMIENTO DE USP Y FARMACOPEAS EUROPEAS.', 0, '', NULL, NULL, NULL, 0, 0, '2016-02-05 22:27:07', NULL),
	(3, 30, 'AUTOR', '2016-02-05', '5', 25, 'ENVIAR PRUEBAS DE FORMULA 11727 A LABORATORIO TECMOL PARA CUMPLIMIENTO DE USP Y FARMACOPEAS EUROPEAS.', 0, '[4]', NULL, NULL, NULL, 0, 0, '2016-02-05 22:27:46', NULL),
	(4, 20, 'AUTOR', '2016-02-04', '5', 20, 'FABRICAR BOLSA DE 7 LITROS DE DRENAJE PARA FRESENIUS USA.', 1, '', NULL, NULL, NULL, 0, 0, '2016-02-18 14:21:31', NULL),
	(5, 20, 'AUTOR', '2016-02-18', '5', 20, 'POTENCIALMENTE REEMPLAZAR  LAS BOLSAS DE DRENAJE  DE 5 LITROS ACTUALMENTE ENSAMBLADAS EN LOS SETS DE DRENAJE LIBERTY (N/P 026-20226) POR BOLSAS DE 7 LITROS DISEÑADAS POR PLASTITEC.', 0, '', NULL, NULL, NULL, 0, 0, '2016-02-18 17:03:05', NULL),
	(6, 56, 'AUTOR', '2016-02-19', '4', 37, 'SE ENVÍAN LOTES AL CLIENTE CON SUS RESPECTIVOS CERTIFICADOS DE CALIDAD.', 0, '[3][5][2]', NULL, NULL, NULL, 0, 0, '2016-02-19 14:13:35', 1),
	(7, 56, 'AUTOR', '2016-02-19', '4', 37, 'SE ENVÍAN LOTES AL CLIENTE CON SUS RESPECTIVOS CERTIFICADOS DE CALIDAD.', 1, '', NULL, NULL, NULL, 0, 0, '2016-02-19 15:44:58', 3),
	(8, 56, 'AUTOR', '2016-02-19', '4', 37, 'SE ENVÍAN TRES LOTES PARA EVALUACIÓN POR PARTE DEL CLIENTE. ', 0, '', NULL, NULL, NULL, 0, 0, '2016-02-19 15:46:25', 3),
	(9, 34, 'AUTOR', '2016-02-18', '5', 40, 'DISEÑO DEL CONECTOR FRANGIBLE Y DEL CONECTOR VIAL EN SI MISMO A PARTIR DE MUESTRAS DEL MERCADO.\r\n\r\nPOSTERIORMENTE SE DEBERÁ ACOMETER LA CONSTRUCCIÓN DE LOS MOLDES CORRESPONDIENTES\r\n', 0, '', NULL, NULL, NULL, 0, 0, '2016-02-24 13:39:41', 3),
	(10, 45, 'AUTOR', '2016-02-18', '5', 43, 'EL CONJUNTO DEBERÁ SER ENSAMBLABLE FÁCILMENTE, Y PERMANECER ENSAMBLADO AÚN DESPUÉS DE PASAR POR AUTOCLAVE, ADEMÁS DEBERÁ EVITAR CUALQUIER FUGA BIEN SEA ENTRE EL TUBO DE LA BOLSA Y EL CUERPO DEL FRANGIBLE, ASÍ COMO EN LA UNIÓN AL FRASCO VIAL.\r\n\r\nES TAMBIÉN MUY IMPORTANTE MINIMIZAR LA POSIBILIDAD DE QUE EL CONJUNTO SUELTE PARTÍCULAS, BIEN SE COMO SUBPRODUCTO DE LA SOLDADURA DE LAS DOS PARTES, O DE LA RUPTURA DEL FRANGIBLE EN SI MISMA.\r\n\r\nPOR SUPUESTO, AL SER USADO DIRECTAMENTE EN CONTACTO CON UNA SOLUCIÓN INTRAVENOSA NO DEBERÍA EXISTIR LA POSIBILIDAD DE TENER MATERIALES ADICIONALES TALES COMO RESIDUOS DE PEGANTE ETC.\r\n\r\nTAMBIÉN SE DEBE INCLUIR EN EL PRODUCTO UN PROTECTOR DEL PINZÓN DEL CONECTOR VIAL HECHO EN POLIPROPILENO. ESTE ELEMENTO DEBERÁ SER VENTILADO PARA PERMITIR EL PASO DEL OXIDO DE ETILENO, Y NO DEBERÁ SALIRSE CON FACILIDAD DEL PUNZÓN DEL CONECTOR VIAL\r\n', 0, '', NULL, NULL, NULL, 0, 0, '2016-02-24 13:43:58', 3),
	(11, 46, 'AUTOR', '2016-02-18', '5', 44, 'PARA E PRODUCTO EN SI MISMO NO EXISTE UNA NORMA ESPECÍFICA, PERO LA IDEA ES USAR MATERIAS PRIMAS, EN ESTE CASO POLICARBONATO DEL MISMO TIPO DE LOS USADOS EN NUESTROS SITIOS DE INYECCIÓN, Y QUE TAMBIÉN ESTÁN EN CONTACTO DIRECTO CON SOLUCIONES INTRAVENOSAS', 0, '', NULL, NULL, NULL, 0, 0, '2016-02-24 13:45:56', 3),
	(12, 47, 'AUTOR', '2016-02-18', '5', 45, 'EL DISEÑO DE LAS PIEZAS VIENE DE MUESTRAS USADAS EN EL MERCADO\r\nEL PRODUCTO ES USADO AMPLIAMENTE POR FRESENIUS MEDICAL CARE EN EUROPA\r\n', 0, '', NULL, NULL, NULL, 0, 0, '2016-02-24 13:53:53', 3),
	(13, 53, 'AUTOR', '2016-02-18', '5', 54, 'LOS PROBLEMAS DERIVADOS DEL SISTEMA DE ENSAMBLE DE LAS PIEZAS, TALES COMO RESIDUO DE PEGANTES, O REBABAS PRODUCIDAS POR SOLDADURA ROTACIONAL SE IDENTIFICARON EN LAS PRUEBAS, RAZÓN POR LA CUAL SE DECIDIÓ EL ENSAMBLE LUER LOCK CON ANILLO', 0, '', NULL, NULL, NULL, 0, 0, '2016-02-24 14:33:57', 3),
	(14, 61, 'AUTOR', '2016-02-19', '4', 55, 'SE VERIFICÓ CADA REGISTRO EN LA PROGRAMACIÓN DE LAS PRUEBAS.', 0, '', NULL, NULL, NULL, 0, 0, '2016-02-24 14:59:55', 3),
	(16, 67, 'AUTOR', '2016-02-24', '5', 56, 'EL CLIENTE FRESENIUS APRUEBA  EL  PRODUCTO A TRAVEZ DE UNA ORDEN DE COMPRA.', 0, '', NULL, NULL, NULL, 0, 0, '2016-02-24 15:44:36', 3),
	(17, 76, 'AUTOR', '2016-03-04', '5', 22, 'Para el frangible en si mismo se toma como punto de partida un conector de este tipo usado por Fresenius Medical Care Colombia para las bolsas Frekaflex Europa. Este diseño al ser usado en Europa nos ahorra tiempo de desarrollo local. Luego de fabricado el molde, será muy importante la validación tanto del éste como la del producto obtenido, teniendo en cuenta análisis de riesgos tales como el desprendimiento de partículas en la zona de ruptura como el del eventual desensamble indeseado de los componentes del conjunto.\r\n\r\nPor otra parte, en el conector vial se deberá validar además del molde en si mismo, que la unión con los viales sea perfectamente hermética, que no se suelte el frasco con facilidad y que sea muy fácil la perforación del tapón de caucho por parte del punzón integrado en el conector vial.\r\n\r\nSe deberá también validar que luego de instalado el conjunto en la tubería de la bolsa, no haya fugas o goteos entre el tubo y el frangible.\r\n', 0, '', NULL, NULL, NULL, 0, 0, '2016-03-04 15:33:45', 3),
	(18, 84, 'AUTOR', '2016-03-07', '5', 19, 'EL CONTROL DE LOS CAMBIOS QUE SE REQUIRIERON DURANTE LA FABRICACIÓN DE LOS MOLDES ESTÁ A CARGO DE NÉSTOR CASTILLO.', 0, '', NULL, NULL, NULL, 0, 0, '2016-03-07 12:22:21', 3),
	(19, 85, 'RESPONSABLE', '2016-04-19', '5', 5, 'CONTROL DE CAMBIO 1\r\nEl cliente solicita reducción en el diámetro de conexión al punzón para que el conector sea funcional con otros tipos de punzones del mercado.\r\n', 0, '[4][8][16]', 'Se reduce Ø5.63 a Ø5.43 y se hace ranura de Ø5.03 en los machos de las cavidades D, I, P según plano M-134016.2.0\r\n', '8', '2016-05-04 10:04:59', 0, 0, '2016-05-04 18:04:17', 1),
	(20, 70, 'RESPONSABLE', '2016-03-03', '5', 59, 'Etapas preliminares: La inquietud de desarrollo de este producto empezó hace varios años, pero sólo hasta ahora con la situación particular de mercado, se liberan las máquinas en las que se puede acometer esta iniciativa.\r\nPodemos definir varias etapas.\r\n1. Desarrollo de una formulación que sirva para hacer películas para fabricar tanto bolsas para sangre como bolsas para plaquetas. Este desarrollo se había hecho cuando se pretendía vender película a Diamed, Brasil, por lo que se cuenta con un trabajo previamente hecho.\r\n2. Desarrollo de conector Opercule. Este elemento es el conector de la gran mayoría de bolsas de sangre y de transferencia, y se cuenta con la experiencia previa del desarrollo de un molde de esta naturaleza para la sociedad Macopharma de Francia, molde que se modificó en su momento para hacer el "Spike Port" de las bolsas de PVC que se le vendieron por millones a Fresenius Medical care Colombia\r\n3. Desarrollo del molde en Y en PVC Trabajo ya realizado que se decomuntará en forma restrospectiva en este desarrollo\r\n4. Determinación de la viabilidad de hacer un selle "peelable" para conformar el capuchón protector del opercule.\r\n5. Diseño del procedimiento para ensamblar Opercule + Capuchón\r\n6. Diseño del procedimiento para soldar el conjunto anterior a la boca de la nueva bolsa.\r\n7. Diseño del sistema de soldadura del perímetro incluyendo la generación de las ranuras que quedan en los costados de la bolsa usadas para organizar los tubos de las bolsas.\r\n8. Diseño del sistema para troquelar el contorno e la bolsa propiamente dicha\r\n9. Empaque y esterilización de las bolsas de Transferencia', 1, '[3][5][6][12][7][2][4][8][16][10]', 'El 15 de Junio de 2016, se reciben conectores Opercule del lote interno C1531-26A16 P6206-26F02, se solicita la fabricación de manga que servira para las pruebas de sellado de capuchon.', '6', '2016-06-15 15:17:47', 0, 0, '2016-06-20 22:20:58', 1),
	(21, 96, 'RESPONSABLE', '2016-06-21', '5', 80, '*) De la formulación: Eduardo Muñoz\r\n*) Del plano inicial de la pieza: Guillermo Cano\r\n*) Del diseño del molde prototipo: Guillermo Cano\r\n*) De la fabricación del molde prototipo. Néstor Castillo\r\n*) De ordenar pruebas: Diego Orozco\r\n*) De realizar las pruebas: Luis Eduardo Rodríguez\r\n*) De evaluar geometrías de la pieza. Wilmer Hernández\r\n*) De aceptación del prototipo: Fresenius Medical Care North America\r\n*) Buscar empaque adecuado: Luis Felipe Osorio - Milton Manrique', 0, '[3][5][7][2][4][15][8][16]', 'se adjunta dimensionales de la pieza, cumplen con lo especificado en el plano.', '4', '2016-06-21 14:25:37', 0, 0, '2016-06-21 19:25:54', 1),
	(22, 70, 'RESPONSABLE', '2016-03-03', '5', 59, 'Etapas preliminares: La inquietud de desarrollo de este producto empezó hace varios años, pero sólo hasta ahora con la situación particular de mercado, se liberan las máquinas en las que se puede acometer esta iniciativa.\r\nPodemos definir varias etapas.\r\n1. Desarrollo de una formulación que sirva para hacer películas para fabricar tanto bolsas para sangre como bolsas para plaquetas. Este desarrollo se había hecho cuando se pretendía vender película a Diamed, Brasil, por lo que se cuenta con un trabajo previamente hecho.\r\n2. Desarrollo de conector Opercule. Este elemento es el conector de la gran mayoría de bolsas de sangre y de transferencia, y se cuenta con la experiencia previa del desarrollo de un molde de esta naturaleza para la sociedad Macopharma de Francia, molde que se modificó en su momento para hacer el "Spike Port" de las bolsas de PVC que se le vendieron por millones a Fresenius Medical care Colombia\r\n3. Desarrollo del molde en Y en PVC Trabajo ya realizado que se decomuntará en forma restrospectiva en este desarrollo\r\n4. Determinación de la viabilidad de hacer un selle "peelable" para conformar el capuchón protector del opercule.\r\n5. Diseño del procedimiento para ensamblar Opercule + Capuchón\r\n6. Diseño del procedimiento para soldar el conjunto anterior a la boca de la nueva bolsa.\r\n7. Diseño del sistema de soldadura del perímetro incluyendo la generación de las ranuras que quedan en los costados de la bolsa usadas para organizar los tubos de las bolsas.\r\n8. Diseño del sistema para troquelar el contorno e la bolsa propiamente dicha\r\n9. Empaque y esterilización de las bolsas de Transferencia', 1, '[3][5][6][12][7][2][4][8][16][10]', 'El 15 de Junio de 2016, se reciben conectores Opercule del lote interno C1531-26A16 P6206-26F02, se solicita la fabricación de manga que servira para las pruebas de sellado de capuchon.\r\nel 17 de Junio de 2016 se recibe manga para realizar prueba de sellado de capuchon (Lote interno 13901-26F16 P4892-26F17-4).\r\nEl 20 de Junio se realizan pruebas de sellado de capcuhon, encontrando que los mandriles estandar tienen un diametro menor al requerido para esta aplicacion. ', '6', '2016-06-20 17:20:58', 1, 0, '2016-06-23 14:11:42', 1),
	(23, 105, 'AUTOR', '2016-07-06', '8', 19, 'Se vuelve Ø5.4 a Ø5.6 y se mantiene el anillo de Ø5[////]', 0, '', NULL, NULL, NULL, 0, 0, '2016-07-06 16:41:55', 3),
	(24, 105, 'AUTOR', '2016-07-06', '8', 19, 'Se vuelve Ø5.4 a Ø5.6 y se mantiene el anillo de Ø5[////]Se adjuntan planos', 0, '', NULL, NULL, NULL, 0, 0, '2016-07-06 16:46:25', 3),
	(25, 105, 'AUTOR', '2016-07-06', '8', 19, 'Se vuelve Ø5.4 a Ø5.6 y se mantiene el anillo de Ø4.9[////]Se adjuntan planos', 0, '', NULL, NULL, NULL, 0, 0, '2016-07-06 16:49:28', 3),
	(26, 105, 'AUTOR', '2016-07-06', '8', 19, 'Se retorna de Ø5.4 a Ø5.6 y se mantiene el anillo de Ø4.9[////]Se adjuntan planos', 0, '', NULL, NULL, NULL, 0, 0, '2016-07-06 16:58:42', 3),
	(27, 105, 'AUTOR', '2016-07-06', '8', 19, 'El 2016-05-24 el Ø5.4 vuelve a Ø5.6 y se mantiene el anillo de Ø4.9 en las cavidades D, I, P[////]Se adjuntan planos de la mariposa y el TO', 0, '', NULL, NULL, NULL, 0, 0, '2016-07-06 17:13:17', 3),
	(28, 110, 'RESPONSABLE', '2016-07-12', '3', 24, 'Ma. Isabel, Leidy, Wilmer,[////][////]Bolsas dobladas en 4/4 a estufa 54 °C durante 1 hora [////][////]Llenado por goteo[////][////][////]Condiciones:[////][////]Carga nominal de 7Litros mas una fuerza adicional de 15N, durante una hora. [////]Se prueban los 3 hojales.[////]', 0, '[4][16]', 'En Screen 4 Turno 3 sacan muestras Fresenius Norte América PVC Drain Bag test X 7 litros lote:7184-26G12.[////]Prueba de ojal No cumple en electrodo 951.', '4', '2016-07-14 15:05:32', 0, 0, '2016-07-14 20:06:25', 1),
	(29, 110, 'RESPONSABLE', '2016-07-12', '3', 24, 'Ma. Isabel, Leidy, Wilmer,[////][////]Bolsas dobladas en 4/4 a estufa 54 °C durante 1 hora [////][////]Llenado por goteo[////][////][////]Condiciones:[////][////]Carga nominal de 7Litros mas una fuerza adicional de 15N, durante una hora. [////]Se prueban los 3 hojales.[////]', 0, '[4][16]', 'En Screen 4 Turno 3 sacan muestras Fresenius Norte América PVC Drain Bag test X 7 litros lote:7184-26G12.[////]Prueba de ojal No cumple en electrodo 951. Se adjunta informe con imágenes del defecto y detalle de otras pruebas', '4', '2016-07-14 15:06:25', 1, 0, '2016-07-26 16:45:35', 1),
	(30, 101, 'RESPONSABLE', '2016-06-22', '8', 80, 'Se hacen 2 ranuras en macho P-032013 para generar anillos en diámetro externo de conexión de CB-157 y corregir fuga.\r\n\r\nDiego, le solicito ordenar prueba de molde.\r\n\r\nMª Isabel, le solicito ordenar verificar muestras y notificar resultados, se debe probar con aire a 1 bar le estoy enviando el filtro optiflux.\r\n', 0, '[3][5][7][2][4][8][16][10]', 'don Diego confirmar formula y código de producto para realizar las respectivas pruebas, ¿que cantidad se fabrica? ', '7', '2016-06-22 14:31:30', 0, 0, '2016-07-28 17:25:49', 1),
	(31, 114, 'RESPONSABLE', '2016-07-26', '3', 5, 'Se fabrican 500 unidades de mariposa código 6984 con formula 16201: LOTE = C16201-26C07 P6984-26G25, se entrega al almacén producto en proceso. [////]Ma. Isabel hacer la verificacion de estas mariposas ', 0, '[4]', 'Se aprueba fabricación de las cavidades I y P. Adjunto informe', '4', '2016-07-26 11:10:26', 1, 0, '2016-07-28 19:45:28', 1),
	(32, 119, 'AUTOR', '2016-09-28', '8', 5, 'Diego, le solicito ordenar prueba de molde, se modifican machos lado móvil según plano M-134015.6', 1, '[3]', 'Se monta molde 2016-09-28 y se inyectan 2.000  mariposas con el Lote 16237-26I28. ', '3', '2016-09-29 16:41:11', 0, 0, '2016-11-01 00:35:26', 1),
	(33, 124, 'RESPONSABLE', '2017-01-25', '5', 57, 'Con el fin de facilitar el llenado y la operación del molde M-110 aumentar el diámetro externo del punzón del conector vial de 3.65 a 3.95 mm. Así mismo ajustar la tapa protectora a este nuevo diámetro.', 0, '[8]', 'El 2017-01-05 se amplía 0.3 mm el diámetro externo de la punta del conector vial.', '8', '2017-01-25 15:28:49', 1, 0, '2017-01-25 21:32:18', 1),
	(34, 156, 'AUTOR', '2017-06-13', '5', 121, 'El objeto de esta modificación es poder tener un segundo proveedor de materia prima usada en la capa exterior de las películas de polipropileno. Este sería un proveedor local y se busca poder tener en lo posible un menor costo en la película.', 0, '[3][5][6][12][7][2][4][16][10]', NULL, NULL, NULL, 0, 0, '2017-06-13 16:38:58', 1),
	(35, 156, 'AUTOR', '2017-06-13', '5', 121, 'El objeto de esta modificación es poder tener un segundo proveedor de materia prima usada en la capa exterior de las películas de polipropileno. Este sería un proveedor local y se busca poder tener en lo posible un menor costo en la película.[////]Se desea usar como contratipo del Bormed 08H85-1 el Propilco 08H85-1', 0, '[3][5][6][12][7][2][4][16][10]', NULL, NULL, NULL, 0, 0, '2017-06-13 16:48:08', 1),
	(36, 165, 'AUTOR', '2017-06-13', '5', 140, 'Diego: Por favor solicitar a Luis Eduardo que se efectúe el primer ensayo con el material 08H85-1 de propilco y me informan para cuándo se puede realizar la prueba. Gracias', 1, '[3]', NULL, NULL, NULL, 0, 0, '2017-06-14 15:52:33', 1),
	(37, 166, 'AUTOR', '2017-06-14', '5', 141, 'Fresenius Medical Care solicita, a raís de una auditoría llevada a cabo por su casa matriz ', 0, '', NULL, NULL, NULL, 0, 0, '2017-06-14 17:02:26', 3),
	(38, 166, 'AUTOR', '2017-06-14', '5', 141, 'Fresenius Medical Care solicita, a ríaz de una auditoría llevada a cabo por su casa matriz mantener una doble bolsa en el empaque de los sitios de inyección, así como la continuidad de la identificación del producto. Aunque el amterial se empacaba en bolsas individuales de 1000 unidades, y a su vez varios de estos paquetes en una segunda bolsa debidamente identificada cumpliendo con el los requisitos, lo que finalmente ocurría cuando se dispensaba paquetes de 1000 unidades y quedaban sin dispensar paquetes, los paquetes que salían quedaban sin una identificación, y perdían la segunda bolsa de empaque.[////]Tambipen queían poder leer ellos mismos las etiquetas con un scanner, pero dado que el código de barras manejaba una información interna en Plastitec que no tenía ningún significado para ellos, pidieron la aparición de un segundo código de barras que les permitiera saber el código interno (en fresenius) del producto, así como identificación del lote en cuestión.[////]Esta sugerencia nos ha parecido útil por lo que se puede implementar para todas las etiquetas internas de todos los productos y para todos los clientes.[////]En en análisis de riesgos se verá que no se quita ninguna información contenida actalmente, y por el contrario se adiciona información que puede resultar útil para los clientes.', 0, '', NULL, NULL, NULL, 0, 0, '2017-06-14 17:05:51', 3),
	(39, 166, 'AUTOR', '2017-06-14', '5', 141, 'Fresenius Medical Care solicita, a ríaz de una auditoría llevada a cabo por su casa matriz mantener una doble bolsa en el empaque de los sitios de inyección, así como la continuidad de la identificación del producto. Aunque el amterial se empacaba en bolsas individuales de 1000 unidades, y a su vez varios de estos paquetes en una segunda bolsa debidamente identificada cumpliendo con el los requisitos, lo que finalmente ocurría cuando se dispensaba paquetes de 1000 unidades y quedaban sin dispensar paquetes, los paquetes que salían quedaban sin una identificación, y perdían la segunda bolsa de empaque.[////]Tambipen queían poder leer ellos mismos las etiquetas con un scanner, pero dado que el código de barras manejaba una información interna en Plastitec que no tenía ningún significado para ellos, pidieron la aparición de un segundo código de barras que les permitiera saber el código interno (en fresenius) del producto, así como identificación del lote en cuestión.[////]Esta sugerencia nos ha parecido útil por lo que se puede implementar para todas las etiquetas internas de todos los productos y para todos los clientes.[////]En en análisis de riesgos se verá que no se quita ninguna información contenida actalmente, y por el contrario se adiciona información que puede resultar útil para los clientes.[////]Dado que se van a fabricar dos tipos de sitios con diferente resellabilidad, se plantea que para evitar confusiones el color de la bolsa primaria para cada tipo de septum sea diferente', 0, '', NULL, NULL, NULL, 0, 0, '2017-06-14 17:26:12', 3),
	(42, 179, 'AUTOR', '2017-08-15', '4', 33, '[////]Se envían 3000 bolsas identificadas con lote 7184-27H02. El 11 de agosto de 2017', 0, '', NULL, NULL, NULL, 0, 0, '2017-08-15 17:49:36', 3),
	(43, 175, 'RESPONSABLE', '2017-06-17', '3', 140, 'Jaime, Wilson, procesar los 3 rollos P7491 a bolsas 100 ml P 7001 FT-DT-1248 v 9 segun OPB17-025.[////][////]Jaime reportar comportamiento de los moldes dado que  la materia prima en prueba va en la capa externa (M1071 vs M1010)', 0, '[12][10]', 'Se efectúa proceso de fabricación de bolsas de 100 ml en la maquina plumat con parámetros nominales de sellado según receta, durante la produccion no se evidenciaron cambios en el funcionamiento normal del equipo o marcas en las areas de contacto de los moldes de sellado.', '12', '2017-06-21 11:42:21', 0, 0, '2017-10-17 19:19:05', 1),
	(44, 201, 'AUTOR', '2016-04-19', '8', 19, 'Se adjunta documentación de calificación y FTP-I-001', 0, '', NULL, NULL, NULL, 0, 0, '2017-11-28 19:05:26', 3),
	(45, 185, 'AUTOR', '2017-11-09', '5', 161, '1. Elaboración de prototipo.[////]2. Entrega de muestras al cliente.[////]', 1, '', NULL, NULL, NULL, 0, 0, '2017-11-28 20:01:12', 3),
	(46, 167, 'RESPONSABLE', '2017-06-14', '5', 142, 'Solicitar a Yamile que le pida al proveedor Infotrack el cambio en la etiqueta[////]Que Yamile verifique que las nuevas etiquetas no alteren el proceso actual de picking para la generación de la etiqueta externa. y que el código de barras adicional que se genere sea legible.[////]A logística que pida al proveedor eserplex las bolsa de color[////]Wilmer y María Isabel verificar que la bolsa de color no transfiera pigmento al producto terminado.[////]Cuando se haya verificado el correcto funcionamiento se deberá cambiar la ficha técnica cuidando el control de cambios[////]Logística deberá enviar al cliente la nueva versión de la ficha técnica', 1, '[3][7][2][4][15][16][10][9]', 'Se recibe propuesta del diseño de la etiqueta de parte del proveedor Infotrack, se verifica con Don Eduardo y se procede a aceptarla y a comenzar proceso para pruebas internas', '9', '2017-06-21 09:39:49', 0, 0, '2017-11-29 14:42:46', 1),
	(47, 208, 'RESPONSABLE', '2017-11-09', '5', 185, 'Construir las cavidades de acuerdo a la altura optima sobre el molde de cúpula PP 2.', 1, '[8]', 'Se realiza montaje de 5 cavidades prototipo para prueba de retenciones M-160', '8', '2018-01-11 14:48:01', 0, 0, '2018-01-11 19:49:15', 1),
	(48, 208, 'RESPONSABLE', '2017-11-09', '5', 185, 'Construir las cavidades de acuerdo a la altura optima sobre el molde de cúpula PP 2.', 1, '[8]', 'El 2018-01-10 se realiza montaje de 5 cavidades prototipo para prueba de retenciones M-160', '8', '2018-01-11 14:49:15', 0, 0, '2018-01-24 17:36:40', 1),
	(49, 208, 'RESPONSABLE', '2017-11-09', '5', 185, 'Construir las cavidades de acuerdo a la altura optima sobre el molde de cúpula PP 2.', 1, '[8]', 'El 2018-01-10 se realiza montaje de 5 cavidades prototipo para prueba de retenciones M-160[////][////]El 2018-01-24 se finaliza fabricación del molde y se realiza montaje ', '8', '2018-01-24 12:36:40', 0, 0, '2018-01-24 19:02:01', 1),
	(50, 208, 'RESPONSABLE', '2017-11-09', '5', 185, 'Construir las cavidades de acuerdo a la altura optima sobre el molde de cúpula PP 2.', 1, '[8]', 'El 2018-01-10 se realiza montaje de 5 cavidades prototipo para prueba de retenciones M-160[////][////]El 2018-01-22 Se realiza montaje con 20 cavidades de Tapón H y 20 con cúpula, el molde no se puede trabajar en automático porque se quedan algunas cúpulas en el lado fijo.[////][////]El 2018-01-24 se finaliza fabricación del molde y se realiza montaje ', '8', '2018-01-24 14:02:01', 0, 0, '2018-01-24 19:04:19', 1),
	(51, 208, 'RESPONSABLE', '2017-11-09', '5', 185, 'Construir las cavidades de acuerdo a la altura optima sobre el molde de cúpula PP 2.', 1, '[8]', 'El 2018-01-10 se realiza montaje de 5 cavidades prototipo para prueba de retenciones M-160[////]El 2018-01-22 Se realiza montaje con 20 cavidades de Tapón H y 20 con cúpula, el molde no se puede trabajar en automático porque se quedan cúpulas en el lado fijo.[////]El 2018-01-24 se finaliza fabricación del molde y se realiza montaje.', '8', '2018-01-24 14:04:19', 0, 0, '2018-01-24 19:27:54', 1),
	(52, 216, 'AUTOR', '2018-04-18', '16', 18, '<div>\r\n<br />\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<div>\r\n<strong><font size="2">INFORMES DE VALIDACI&Oacute;N:</font></strong>\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<div>\r\n<strong>IQ:&nbsp;</strong><a href="UserFiles/File/0001/RESPUESTAS/IQ-M134_018V0.pdf" target="_blank">INFORME</a> \r\n</div>\r\n<div>\r\n<strong>&nbsp;</strong>\r\n</div>\r\n<div>\r\n<strong>OQ:&nbsp;</strong><a href="UserFiles/File/0001/RESPUESTAS/OQ-M134_018V0.pdf" target="_blank">INFORME</a> \r\n</div>\r\n<div>\r\n<strong>&nbsp;</strong>\r\n</div>\r\n<div>\r\n<strong>PQ :&nbsp;</strong><a href="UserFiles/File/0001/RESPUESTAS/PQ TWIST OFF CONNECTOR.pdf" target="_blank">INFORME</a> \r\n</div>\r\n', 0, '', NULL, NULL, NULL, 0, 0, '2018-04-19 23:13:55', 3),
