	(131, 231, 'AUTOR', '2018-10-29', '4', 232, '<p>\r\nSe fabrican y despachan 20.000 unidades,&nbsp;para validaci&oacute;n,con los siguientes certificados de calidad\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<p>\r\n<a href="UserFiles/File/0002-1/7184-28J20.pdf" target="_blank">Certificado lote&nbsp;&nbsp;</a>: 7184-28J20\r\n</p>\r\n<p>\r\n<a href="UserFiles/File/0002-1/7184-28J18.pdf" target="_blank">Certificado lote&nbsp;</a>&nbsp;:7184-28J18\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<p>\r\n<a href="UserFiles/File/0002-1/DROP TEST REPORT DRAINAGE BAG.pdf" target="_blank">Informe de validaci&oacute;n&nbsp;</a> \r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, '2019-06-25 20:33:42', 3),
