	(168, 293, 'AUTOR', '2019-12-26', '5', 290, '<p>\r\n&nbsp;\r\n</p>\r\n<p>\r\n&nbsp;ELABORAR PLANO PARA PROTOTIPO MEMBRANA CURVA\r\n</p>\r\n<p>\r\nPROGRAMAR FABRICACI&Oacute;N DE&nbsp; PIEZAS\r\n</p>\r\n<p>\r\nREVISAR DIMENSIONES FRENTE AL PLANO Y REALIZAR PRUEBAS FUNCIONALES A 129 &deg;C Y PRUEBAS DE USO CON DIFERENTES EQUIPOS DE INFUSI&Oacute;N.\r\n</p>\r\n<p>\r\nENVIAR MUESTRAS AL CLIENTE\r\n</p>\r\n', 0, '[3][7][4][8][16]', NULL, NULL, NULL, 0, 0, '2020-01-08 17:05:02', 1),
	(169, 293, 'AUTOR', '2019-12-26', '5', 290, '<p>\r\n&nbsp;\r\n</p>\r\n<p>\r\n&nbsp;ELABORAR PLANO PARA PROTOTIPO MEMBRANA CURVA\r\n</p>\r\n<p>\r\nPROGRAMAR FABRICACI&Oacute;N DE&nbsp; PIEZAS\r\n</p>\r\n<p>\r\nREVISAR DIMENSIONES FRENTE AL PLANO Y REALIZAR PRUEBAS FUNCIONALES A 129 &deg;C Y PRUEBAS DE USO CON DIFERENTES EQUIPOS DE INFUSI&Oacute;N.\r\n</p>\r\n<p>\r\nENVIAR MUESTRAS AL CLIENTE\r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, '2020-01-10 20:50:27', 3),
	(170, 293, 'RESPONSABLE', '2019-12-26', '5', 290, '<p>\r\n&nbsp;\r\n</p>\r\n<p>\r\n&nbsp;ELABORAR PLANO PARA PROTOTIPO MEMBRANA CURVA\r\n</p>\r\n<p>\r\nPROGRAMAR FABRICACI&Oacute;N DE&nbsp; PIEZAS\r\n</p>\r\n<p>\r\nREVISAR DIMENSIONES FRENTE AL PLANO Y REALIZAR PRUEBAS FUNCIONALES A 129 &deg;C Y PRUEBAS DE USO CON DIFERENTES EQUIPOS DE INFUSI&Oacute;N.\r\n</p>\r\n<p>\r\nENVIAR MUESTRAS AL CLIENTE\r\n</p>\r\n', 1, '[3][4][8][16]', '<b>Responsable :</b>WILMER HERNANDEZ / COORDINADOR SGC<br /><b>Fecha :</b>2019-12-12<br /><b>Respuesta :</b><div>\r\n<br />\r\n</div>\r\n<div>\r\nSe adjunta informe general de las pruebas realizadas.\r\n</div>\r\n<div>\r\n&nbsp;\r\n</div>\r\n<div>\r\n<a href="UserFiles/File/M004/Informe General.pdf" target="_blank">Ver&nbsp;</a> \r\n</div>\r\n', '16', '2020-01-10 15:58:36', 1, 0, '2020-01-10 21:02:32', 3),
	(171, 286, 'AUTOR', '2019-12-20', '5', 265, '<p class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<p class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<p class="MsoNormal">\r\n<span style="font-size: 10.5pt; line-height: 115%; font-family: Arial, sans-serif; color: #333333; background: white">Desarrollar una membrana\r\nen el conector twist off que soporte temperaturas de esterilizacion de 129\r\n&deg;C,&nbsp; y que cumpla con el proceso aplicado por el cliente Pharmatech.</span>\r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, '2020-01-21 20:07:33', 3),
	(172, 287, 'AUTOR', '2019-12-26', '5', 266, '<div>\r\n<br />\r\n</div>\r\n<div>\r\n<p class="MsoNormal">\r\nLas etapas ser&aacute;n:\r\n</p>\r\n<p style="text-indent: -18pt" class="MsoListParagraphCxSpFirst">\r\n<!--[if !supportLists]--><span style="font-size: 7pt; line-height: 115%; font-family: &quot;Segoe UI&quot;, sans-serif; color: #292929"><span>1.<span style="font: 7pt &quot;Times New Roman&quot;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span></span></span><!--[endif]--><span style="font-size: 7pt; line-height: 115%; font-family: &quot;Segoe UI&quot;, sans-serif; color: #292929; text-transform: uppercase; background: #eeeeee">ELABORACI&Oacute;N DE PLANOS DE LA NUEVA PIEZA</span>\r\n</p>\r\n<p style="text-indent: -18pt" class="MsoListParagraphCxSpMiddle">\r\n<!--[if !supportLists]--><span style="font-size: 7pt; line-height: 115%; font-family: &quot;Segoe UI&quot;, sans-serif; color: #292929"><span>2.<span style="font: 7pt &quot;Times New Roman&quot;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span></span></span><!--[endif]--><span style="font-size: 7pt; line-height: 115%; font-family: &quot;Segoe UI&quot;, sans-serif; color: #292929; text-transform: uppercase; background: #eeeeee"><span>&nbsp;</span>2 FABRICACI&Oacute;N DE\r\nCAVIDADES PROTOTIPO PARA MONTARLAS EN MOLDE DE mariposa twiist off </span>\r\n</p>\r\n<p style="text-indent: -18pt" class="MsoListParagraphCxSpMiddle">\r\n<!--[if !supportLists]--><span style="font-size: 7pt; line-height: 115%; font-family: &quot;Segoe UI&quot;, sans-serif; color: #292929"><span>3.<span style="font: 7pt &quot;Times New Roman&quot;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</span></span></span><!--[endif]--><span style="font-size: 7pt; line-height: 115%; font-family: &quot;Segoe UI&quot;, sans-serif; color: #292929; text-transform: uppercase; background: #eeeeee">3. FABRICACI&Oacute;N DE MUESTRAS PROTOTIPO</span>\r\n</p>\r\n<p style="text-indent: -18pt" class="MsoListParagraphCxSpMiddle"