	(173, 288, 'AUTOR', '2019-12-26', '5', 267, '<div>\r\n<br />\r\n</div>\r\n<div>\r\n<p class="MsoNormal">\r\n<span style="font-size: 7pt; line-height: 115%; font-family: &quot;Segoe UI&quot;, sans-serif; color: #292929; text-transform: uppercase; background: #eeeeee">REVISAR\r\nEL PLANO DEL PROTOTIPO FRENTE A LAS PRIMERAS PIEZAS OBTENIDAS.</span><span style="font-size: 7pt; line-height: 115%; font-family: &quot;Segoe UI&quot;, sans-serif; color: #292929; text-transform: uppercase"><br />\r\n<span style="background: #eeeeee"><span style="font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; widows: 2; -webkit-text-stroke-width: 0px; text-decoration-style: initial; text-decoration-color: initial; float: none; word-spacing: 0px">REVISI&Oacute;N DE ESPECIFICACIONES GENERADAS PARA ELABORAR LA FT.</span></span><br />\r\n<span style="background: #eeeeee"><span style="font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; widows: 2; -webkit-text-stroke-width: 0px; text-decoration-style: initial; text-decoration-color: initial; float: none; word-spacing: 0px">REVISI&Oacute;N DE REQUISITOS DE FUNCIONAMIENTO Y DESEMPE&Ntilde;O.</span></span></span>\r\n</p>\r\n<br />\r\n</div>\r\n', 1, '', NULL, NULL, NULL, 0, 0, '2020-01-21 20:08:29', 3),
	(174, 289, 'AUTOR', '2019-12-26', '5', 268, '<p class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<p class="MsoNormal">\r\n<span style="font-size: 7pt; line-height: 115%; font-family: &quot;Segoe UI&quot;, sans-serif; color: #292929; text-transform: uppercase; background: #eeeeee">VERIFICAR\r\nCUMPLIMIENTO DE LAS ESPECIFICACIONES DE LA FT.</span><span style="font-size: 7pt; line-height: 115%; font-family: &quot;Segoe UI&quot;, sans-serif; color: #292929; text-transform: uppercase"><br />\r\n<span style="background: #eeeeee"><span style="font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; widows: 2; -webkit-text-stroke-width: 0px; text-decoration-style: initial; text-decoration-color: initial; float: none; word-spacing: 0px">VERIFICAR PRUEBAS DE FUNCIONALIDAD Y USABILIDAD.</span></span><br />\r\n<span style="background: #eeeeee"><span style="font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; widows: 2; -webkit-text-stroke-width: 0px; text-decoration-style: initial; text-decoration-color: initial; float: none; word-spacing: 0px">VALIDACI&Oacute;N A TRAVES DE MUESTRAS ENVIADAS&nbsp; AL&nbsp; CLIENTE.</span></span><br />\r\n<span style="background: #eeeeee"><span style="font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; widows: 2; -webkit-text-stroke-width: 0px; text-decoration-style: initial; text-decoration-color: initial; float: none; word-spacing: 0px">TRANSFERENCIA A&nbsp; PRODUCCI&Oacute;N :</span></span><br />\r\n<span style="background: #eeeeee"><span style="font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; widows: 2; -webkit-text-stroke-width: 0px; text-decoration-style: initial; text-decoration-color: initial; float: none; word-spacing: 0px">REVISI&Oacute;N DE TARAS Y ACTUALIZACI&Oacute;N DE FICHAS T&Eacute;CNICAS.</span></span></span>\r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, '2020-01-21 20:08:53', 3),
	(175, 290, 'AUTOR', '2019-12-26', '5', 269, '<p class="MsoNormal">\r\n<span style="font-size: 7pt; line-height: 115%; font-family: &quot;Segoe UI&quot;, sans-serif; color: #292929; text-transform: uppercase"><br />\r\n</span>\r\nDE LAS MODIFICACIONES EN EL MOLDE: NESTOR CASTILLO\r\n</p>\r\n<p class="MsoNormal">\r\n<span style="font-size: 7pt; line-height: 115%; font-family: &quot;Segoe UI&quot;, sans-serif; color: #292929; text-transform: uppercase"><br />\r\n</span>\r\nDE LA PRUEBA EN PRODUCCI&Oacute;N: DIEGO OROZCO, LUIS EDUARDO RODRIGUEZ.\r\n</p>\r\n<span style="font-size: 7pt; line-height: 115%; font-family: &quot;Segoe UI&quot;, sans-serif; color: #292929; text-transform: uppercase"><br />\r\n</span><span style="font-size: 11pt; line-height: 115%; font-family: Calibri, sans-serif">\r\nDE LOS RESULTADOS DE LAS PRUEBAS: MAR&Iacute;A ISABEL COLMENARES , WILMER HERNANDEZ</span>\r\n', 1, '', NULL, NULL, NULL, 0, 0, '2020-01-21 20:09:19', 3),
	(176, 291, 'AUTOR', '2019-12-26', '5', 270, '<div>\r\n<br />\r\n</div>\r\n<div>\r\n<p class="MsoNormal">\r\n<span style="font-size: 7pt; line-height: 115%; font-family: &quot;Segoe UI&quot;, sans-serif; color: #292929; text-transform: uppercase; background: #eeeeee">LOS\r\nM&Eacute;TODOS SE ASEGURAN MEDIANTE LOS REGISTROS DE ACTIVIDADES O TAREAS GENERADAS EN\r\nEL APLICATIVO Y LOS REGISTROS ADJUNTOS QUE DESCRIBEN LA CODIFICACI&Oacute;N Y LOS\r\nLOTES DE LAS MUESTRAS.</span>\r\n</p>\r\n<br />\r\n</div>\r\n', 1, '', NULL, NULL, NULL, 0, 0, '2020-01-21 20:09:41', 3),
