	(183, 298, 'AUTOR', '2019-12-27', '5', 276, '<p>\r\nEL PLANO DEL PROTOTIPO PARA LA VERIFICACI&Oacute;N DIMENSIONAL.\r\n</p>\r\n<p>\r\nCUMPLIR PRUEBA DE ESTANQUEIDAD A UNA TEMPERATURA DE ESTERILIZACI&Oacute;N DE 129&deg;C. I-GC-006 V10\r\n</p>\r\n<p>\r\nCUMPLIR FUNCIONALIDAD CON DIFERENTES TIPOS DE EQUIPOS DE INFUSI&Oacute;N.\r\n</p>\r\n<p>\r\n&nbsp;AJUSTE DEL COMPARADOR CON LA GEOMETR&Iacute;A DE LA MEMBRANA CURVA.\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, '2020-01-21 20:15:14', 3),
