	(242, 328, 'AUTOR', '2018-06-11', '5', 298, '<p>\r\nLOS REQUISITOS, SON:\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<ol>\r\n	<li>&nbsp;DESEMPE&Ntilde;O: Cumplir&nbsp; 1.1&nbsp; Prueba de integridad de membrana (estanqueidad) a 129 &deg;C&nbsp; Y&nbsp; 1.2&nbsp; &nbsp;Prueba de Integridad de twist off a 129 &deg;C.</li>\r\n	<li>USABILIDAD: Cumplir prueba de perforado y torsi&oacute;n.</li>\r\n	<li>SEGURIDAD DE ACUERDO CON EL USO PREVISTO: 3.1 Pruebas dimensionales seg&uacute;n ficha t&eacute;cnica FT-E-0299 3.2 An&aacute;lisis F&iacute;sico Qu&iacute;mico del material Seg&uacute;n Farmacopea Europea capitulo 3.1.14</li>\r\n</ol>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<p style="margin-left: 0cm" class="MTemaNormal" align="left">\r\n&nbsp;\r\n</p>\r\n', 0, '', NULL, NULL, NULL, 0, 0, '2020-07-14 22:46:24', 3),
