	(292, 378, 'AUTOR', '2020-08-06', '5', 211, '<div>\r\n<br />\r\n</div>\r\n<div>\r\n<font size="1"><span style="line-height: 107%; font-family: Verdana, sans-serif; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial">Para mejorar la resellabilidad del elast&oacute;mero actual y\r\nlograr procesabilidad en inyecci&oacute;n, se programa la prueba de modificaciones en\r\nla formula actual 1369</span><span style="line-height: 107%; font-family: Verdana, sans-serif; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial">&nbsp;pist&oacute;n\r\nSiliprene blanco est&aacute;ndar USANDO DOS MP NUEVAS&nbsp;</span><strong>M1219 y M1220,&nbsp;</strong><span style="line-height: 107%; font-family: Verdana, sans-serif; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial">con el fin de tener\r\nun producto de calidad intermedio entre el pist&oacute;n actual y\r\nel&nbsp;cord&oacute;n&nbsp;extruido.</span></font>\r\n</div>\r\n', 1, '', NULL, NULL, NULL, 0, 0, '2020-08-27 16:39:43', 3),
