	(298, 391, 'AUTOR', '2020-03-20', '5', 324, '<p style="background: #eeeeee" class="MsoNormal">\r\n<font face="Segoe UI, sans-serif" size="1" color="#34495e"><span style="text-transform: uppercase">LOS REQUISITOS DE FUNCIONAMIENTO, DESEMPE&Ntilde;O, USABILIDAD&nbsp; Y SEGURIDAD CON EL USO PREVISTO,SON:</span></font>\r\n</p>\r\n<p style="background: #eeeeee" class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<p style="background: #eeeeee" class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<ul>\r\n	<li><br />\r\n	</li>\r\n	<li><br />\r\n	</li>\r\n</ul>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<p style="background: #eeeeee" class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<ul>\r\n	<li>AL QUEBRAR EL FRANGIBLE LA LANCETA DEBE QUEDAR TRABADA EN EL DUCTO&nbsp;</li>\r\n	<li><span style="font-size: 7pt; font-family: &quot;Segoe UI&quot;, sans-serif; color: #34495e; text-transform: uppercase">*eL ENSAMBLE A LA&nbsp; DEBE CUMPLIR PRUEBA DE PERMEABILIDAD A\r\n	MICROORGANISMOS</span></li>\r\n</ul>\r\n<p>\r\n&nbsp;\r\n</p>\r\n<p class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<table border="1" cellspacing="0" cellpadding="0">\r\n	<tbody>\r\n		<tr>\r\n			<td width="557" valign="top" style="width: 417.7pt; border: 1pt solid windowtext; background: #bfbfbf; padding: 0cm 5.4pt">\r\n			<p style="text-align: center" class="MsoNormal" align="center">\r\n			<strong><span style="font-size: 12pt; font-family: Arial, sans-serif; color: #006699; text-transform: uppercase">ENTRADA</span></strong><span style="font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: #006699; text-transform: uppercase"></span>\r\n			</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td width="557" valign="top" style="width: 417.7pt; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt">\r\n			<p class="MsoNormal">\r\n			<strong><span style="font-size: 12pt; font-family: Arial, sans-serif; color: #006699; text-transform: uppercase"><br />\r\n			</span></strong>\r\n			</p>\r\n			<p class="MsoNormal">\r\n			<strong><span style="font-size: 12pt; font-family: Arial, sans-serif; color: #006699; text-transform: uppercase">DESEMPE&Ntilde;O&nbsp;</span></strong><span style="font-size: 12pt; font-family: Arial, sans-serif; color: #006699; text-transform: uppercase">DEBE CUMPLIR:</span>\r\n			</p>\r\n			<p class="MsoNormal">\r\n			<font size="2">ESTANQUEIDAD ENTRE LOS COMPONENTES Y&nbsp; ENTRE EL CONJUNTO Y LA BOLSA.</font>\r\n			</p>\r\n			<p class="MsoNormal">\r\n			<font size="2">EL ENSAMBLE DEBE SER&nbsp; DE F&Aacute;CIL AJUSTE Y SU CONJUNTO NO SE DEBE SOLTAR DE LA BOLSA&nbsp;</font>\r\n			</p>\r\n			<p class="MsoNormal">\r\n			<font size="2"><span style="color: #34495e; font-family: &quot;Segoe UI&quot;, sans-serif; text-transform: uppercase">EL FRANGIBLE DEBE SER DE QUIEBRE SUAVE. Y&nbsp;</span>&nbsp;LA LANCETA DEBE QUEDAR TRABADA EN EL DUCTO&nbsp;</font>\r\n			</p>\r\n			<p class="MsoNormal">\r\n			&nbsp;\r\n			</p>\r\n			<p class="MsoNormal">\r\n			&nbsp;\r\n			</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td width="557" valign="top" style="width: 417.7pt; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt">\r\n			<p class="MsoNormal">\r\n			<strong><span style="font-size: 12pt; font-family: Arial, sans-serif; color: #006699; text-transform: uppercase">USABILIDAD&nbsp;</span></strong><span style="font-size: 12pt; font-family: Arial, sans-serif; color: #006699; text-transform: uppercase">DEBE CUMPLIR</span><span style="font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: #006699; text-transform: uppercase"></span>\r\n			</p>\r\n			<p style="text-indent: -18pt" class="MsoNormal">\r\n			<span style="font-size: 10pt; font-family: &quot;Times New Roman&quot;, serif; color: #006699; text-transform: uppercase">1.</span><span style="font-size: 7pt; font-family: &quot;Times New Roman&quot;, serif; color: #006699; text-transform: uppercase">&nbsp; &nbsp; &nbsp;</span><font size="2">ESTE CONJUNTO DEBE FACILITAR LA CONEXI&Oacute;N\r\n			DE LA&nbsp; BOLSA DE SOLUCI&Oacute;N, QUE SERVIR&Aacute; DE VEH&Iacute;CULO PARA DILUCI&Oacute;N DEL MEDICAMENTO QUE VENGA EN EL FRASCO VIAL</font>.\r\n			</p>\r\n			<p style="text-indent: -18pt" class="MsoNormal">\r\n			&nbsp;\r\n			</p>\r\n			<p style="text-indent: -18pt" class="MsoNormal">\r\n			&nbsp;\r\n			</p>\r\n			</td>\r\n		</tr>\r\n		<tr style="height: 122.7pt">\r\n			<td width="557" valign="top" style="width: 417.7pt; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt; height: 122.7pt">\r\n			<p class="MsoNormal">\r\n			<strong><span style="font-size: 12pt; font-family: Arial, sans-serif; color: #006699; text-transform: uppercase"><br />\r\n			</span></strong>\r\n			</p>\r\n			<p class="MsoNormal">\r\n			&nbsp;<strong><span style="font-size: 12pt; font-family: Arial, sans-serif; color: #006699; text-transform: uppercase">SEGURIDAD DE ACUERDO CON\r\n			EL USO PREVISTO</span></strong><span style="font-size: 12pt; font-family: Arial, sans-serif; color: #006699; text-transform: uppercase">:</span>\r\n			</p>\r\n			<p class="MsoNormal">\r\n			<font size="2">&nbsp;<font style="color: #006699; font-family: Arial, sans-serif; text-transform: uppercase">NINGUN COMPONENTE DEBE GENERAR PARTICULAS&nbsp;</font><span style="color: #006699; font-family: Arial, sans-serif; text-transform: uppercase">&nbsp;</span></font>\r\n			</p>\r\n			<p style="text-indent: -18pt" class="MsoNormal">\r\n			<font size="2"><span style="font-family: &quot;Times New Roman&quot;, serif; color: #006699; text-transform: uppercase">1.</span><span style="font-family: &quot;Times New Roman&quot;, serif; color: #006699; text-transform: uppercase">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span style="font-family: &quot;Times New Roman&quot;, serif; color: #006699; text-transform: uppercase">PRUEBAS DIMENSIONALES\r\n			SEG&Uacute;N FICHA T&Eacute;CNICA.</span><span style="font-family: &quot;Times New Roman&quot;, serif; color: #006699; text-transform: uppercase"></span></font>\r\n			</p>\r\n			<p style="text-indent: -18pt" class="MsoNormal">\r\n			<font size="2"><span style="font-family: &quot;Times New Roman&quot;, serif; color: #006699; text-transform: uppercase">2.</span><span style="font-family: &quot;Times New Roman&quot;, serif; color: #006699; text-transform: uppercase">&nbsp; &nbsp; PRUEBA DE PERMEABILIDAD A MICROORGANISMOS</span></font>\r\n			</p>\r\n			<p style="text-indent: -18pt" class="MsoNormal">\r\n			<span style="font-family: &quot;Times New Roman&quot;, serif; color: #006699; text-transform: uppercase"><font size="2">PR&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</font></span><span style="font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: #006699; text-transform: uppercase"></span>\r\n			</p>\r\n			<p style="text-indent: -18pt" class="MsoNormal">\r\n			<span style="font-size: 10pt; font-family: &quot;Times New Roman&quot;, serif; color: #006699; text-transform: uppercase">&nbsp; &nbsp; &nbsp; &nbsp;</span>\r\n			</p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n', 0, '', NULL, NULL, NULL, 0, 0, '2020-10-30 17:04:23', 3),
