	(336, 435, 'AUTOR', '2022-03-25', '17', 378, 'SE REALIZA PLAN DE RIESGOS PARA ESTA NUEVA PIEZA\r\n', 0, '', NULL, NULL, NULL, 0, 0, '2024-05-10 21:16:10', 3),
	(337, 449, 'AUTOR', '2023-03-24', '17', 394, '<p>\r\nSE REALIZA GESTION DEL PLAN DE RIESGOS.\r\n</p>\r\n<p>\r\n<a href="UserFiles/File/0013/0013/R-GC-096_V3_GESTION_DE_RIESGOS FRANGIBLE JP 2023.pdf" target="_blank">PLAN DE RIESGOS 2023&nbsp;</a> \r\n</p>\r\n', 0, '', NULL, NULL, NULL, 0, 0, '2024-05-10 21:19:07', 3),
	(338, 449, 'AUTOR', '2023-03-24', '17', 394, '', 0, '', NULL, NULL, NULL, 0, 0, '2024-05-10 21:19:08', 3),
