	(343, 401, 'AUTOR', '2021-09-28', '17', 343, '<p>\r\n&nbsp;\r\n</p>\r\n<p>\r\n*Mejorar la adhesi&oacute;n entre el ducto de polipropileno (PP) P8592&nbsp; y el sitio de inyecci&oacute;n actual de PC.\r\n</p>\r\n<p>\r\n&nbsp;\r\n</p>\r\n', 1, '', NULL, NULL, NULL, 0, 0, '2024-05-16 01:09:06', 3),
	(344, 406, 'RESPONSABLE', '2021-09-29', '17', 347, '<p class="MsoNormal">\r\nLAS RESPONSABILIDADES ASIGNADAS A ESTE PROYECTO SON:\r\n</p>\r\n<p class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<p class="MsoNormal">\r\nINTERACCI&Oacute;N CON EL CLIENTE:&nbsp; LUIS FELIPE OSORIO\r\n</p>\r\n<p class="MsoNormal">\r\nDIES&Ntilde;O Y CREACION DEL MOLDE Y GENERACI&Oacute;N PLANO COMPONENTE\r\nB&Aacute;SICO Y ENSAMBLE: NESTOR CASTILLO\r\n</p>\r\n<p class="MsoNormal">\r\nCOORDINACI&Oacute;N PRUEBAS DE PRODUCCI&Oacute;N: DIEGO OROZCO\r\n</p>\r\n<p class="MsoNormal">\r\nFABRICACI&Oacute;N DE PIEZAS INYECTADAS: LUIS EDUARDO RODRIGUEZ\r\n</p>\r\n<p class="MsoNormal">\r\nENSAMBLE DE PIEZAS INYECTADAS: WILSON BUSTOS/GERMAN PINZON.\r\n</p>\r\n<p class="MsoNormal">\r\nGENERACI&Oacute;N DE&nbsp; FICHA T&Eacute;CNICA DE PRODUCTO: MA. ISABEL\r\nCOLMENARES.\r\n</p>\r\n<p class="MsoNormal">\r\nVERIFICACI&Oacute;N Y VALIDACI&Oacute;N DEL PRODUCTO: MA. ISABEL\r\nCOLMENARES - WILMER HERNANDEZ.&nbsp;\r\n</p>\r\n<p class="MsoNormal">\r\nTRANSFERENCIA DEL DISE&Ntilde;O: MA. ISABEL COLMENARES\r\n</p>\r\n', 1, '[3][6][7][2][4][8][17][16][10]', '<b>Responsable :</b>RODRIGO PENA MUNOZ / ADMINISTRADOR PRODUCCION<br /><b>Fecha :</b>2021-09-29<br /><b>Respuesta :</b>', '17', '2024-05-15 20:07:42', 0, 0, '2024-05-16 01:10:43', 1),
	(345, 406, 'RESPONSABLE', '2021-09-29', '17', 347, '<p class="MsoNormal">\r\nLAS RESPONSABILIDADES ASIGNADAS A ESTE PROYECTO SON:\r\n</p>\r\n<p class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<p class="MsoNormal">\r\nINTERACCI&Oacute;N CON EL CLIENTE:&nbsp; LUIS FELIPE OSORIO\r\n</p>\r\n<p class="MsoNormal">\r\nDIES&Ntilde;O Y CREACION DEL MOLDE Y GENERACI&Oacute;N PLANO COMPONENTE\r\nB&Aacute;SICO Y ENSAMBLE: NESTOR CASTILLO\r\n</p>\r\n<p class="MsoNormal">\r\nCOORDINACI&Oacute;N PRUEBAS DE PRODUCCI&Oacute;N: DIEGO OROZCO\r\n</p>\r\n<p class="MsoNormal">\r\nFABRICACI&Oacute;N DE PIEZAS INYECTADAS: LUIS EDUARDO RODRIGUEZ\r\n</p>\r\n<p class="MsoNormal">\r\nENSAMBLE DE PIEZAS INYECTADAS: WILSON BUSTOS/GERMAN PINZON.\r\n</p>\r\n<p class="MsoNormal">\r\nGENERACI&Oacute;N DE&nbsp; FICHA T&Eacute;CNICA DE PRODUCTO: MA. ISABEL\r\nCOLMENARES.\r\n</p>\r\n<p class="MsoNormal">\r\nVERIFICACI&Oacute;N Y VALIDACI&Oacute;N DEL PRODUCTO: MA. ISABEL\r\nCOLMENARES - WILMER HERNANDEZ.&nbsp;\r\n</p>\r\n<p class="MsoNormal">\r\nTRANSFERENCIA DEL DISE&Ntilde;O: MA. ISABEL COLMENARES\r\n</p>\r\n', 1, '[3][6][7][2][4][8][17][16][10]', '<b>Responsable :</b>RODRIGO PENA MUNOZ / ADMINISTRADOR PRODUCCION<br /><b>Fecha :</b>2021-09-29<br /><b>Respuesta :</b><hr /><b>Responsable :</b>RODRIGO PENA MUNOZ / ADMINISTRADOR PRODUCCION<br /><b>Fecha :</b>2021-09-29<br /><b>Respuesta :</b>', '17', '2024-05-15 20:10:43', 0, 0, '2024-05-16 01:11:55', 1),
	(346, 409, 'AUTOR', '2021-09-29', '17', 350, '<p class="MsoNormal">\r\nLOS REQUISITOS SON:\r\n</p>\r\n<p class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<p class="MsoNormal">\r\nDESEMPE&Ntilde;O: CUMPLIR&nbsp;PRUEBA DE ADHERENCIA ENTRE EL DUCTO\r\nP8592 Y EL SITIO DE INYECCION DE PP&nbsp;\r\n</p>\r\n<p class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<p class="MsoNormal">\r\nUSABILIDAD: CUMPLIR&nbsp;PRUEBA DE ESTANQUEIDAD \r\n</p>\r\n<p class="MsoNormal">\r\nSEGURIDAD DE ACUERDO CON EL USO PREVISTO: \r\n</p>\r\n<p class="MsoNormal">\r\nPRUEBAS DIMENSIONALES SEG&Uacute;N FICHA T&Eacute;CNICA FT-E-<span style="background: yellow">0239</span> \r\n</p>\r\n<p class="MsoNormal">\r\nAN&Aacute;LISIS F&Iacute;SICO QU&Iacute;MICO DEL MATERIAL SEG&Uacute;N FARMACOPEA\r\nEUROPEA CAPITULO 3.2.2\r\n</p>\r\n', 0, '', NULL, NULL, NULL, 0, 0, '2024-05-16 01:19:23', 3),
	(347, 414, 'AUTOR', '2021-09-29', '17', 356, '<p class="MsoNormal">\r\nNO SE REQUIERE YA QUE LOS MATERIALES Y LAS CANTIDADES SON\r\nLAS MISMAS. NO HAY CAMBIO DE FORMULACI&Oacute;N.\r\n</p>\r\n', 0, '', NULL, NULL, NULL, 0, 0, '2024-05-16 01:26:21', 3),
	(348, 414, 'AUTOR', '2021-09-29', '17', 356, '<p class="MsoNormal">\r\nNO SE REQUIERE YA QUE LOS MATERIALES YA SE UTILIZAN EN OTROS PRODUCTOS SIMILARES.\r\n</p>\r\n', 0, '', NULL, NULL, NULL, 0, 0, '2024-05-16 01:26:50', 3),
	(349, 413, 'AUTOR', '2021-09-29', '17', 355, '<p class="MsoNormal">\r\n&nbsp;LAS SALIDAS CUMPLIERON CON LOS REQUISITOS DE ENTRADA DEL\r\nDISE&Ntilde;O:\r\n</p>\r\n<p class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<p class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<p class="MsoNormal">\r\nESPECIFICACIONES DEL PLANO Y LA FICHA T&Eacute;CNICA FT-E-XXXX :\r\nCUMPLIERON VER CERTIFICADO DE CALIDAD&nbsp;NO. \r\n</p>\r\n<p class="MsoNormal">\r\nPRUEBAS DE DESEMPE&Ntilde;O: CUMPLIERON.&nbsp;VER INFORME\r\n</p>\r\n<p class="MsoNormal">\r\nPRUEBAS DE USABILIDAD:&nbsp;CUMPLIERON\r\n</p>\r\n<p class="MsoNormal">\r\n&nbsp;\r\n</p>\r\n<p class="MsoNormal">\r\nSEGURIDAD DE ACUERDO CON EL USO PREVISTO: CUMPLIERON.&nbsp;VER\r\nINFORME&nbsp;&nbsp;TOXIKON&nbsp;\r\n</p>\r\n', 0, '', NULL, NULL, NULL, 0, 0, '2024-05-16 01:27:28', 3),
	(350, 451, 'AUTOR', '2021-09-29', '17', 352, 'PLAN GESTION DEL RIESGO.\r\n', 0, '', NULL, NULL, NULL, 0, 0, '2024-05-16 01:45:42', 3),
	(351, 416, 'AUTOR', '2021-09-29', '17', 358, '<p class="MsoNormal">\r\nLAS CARACTER&Iacute;STICAS ESENCIALES DEL PRODUCTO EST&Aacute;N DETALLADAS\r\nEN LOS PLANOS CB-XXX&nbsp; Y FICHAS TECNICAS VIGENTES F-E-XXXX\r\n</p>\r\n', 0, '', NULL, NULL, NULL, 0, 0, '2024-05-16 01:50:12', 3),
